-- =====================================================================================================================
-- LIVE MIRROR · the processor inside the database — EVERY SECTION: ORDERS · STOCK · SKUs · MASTERS · CONTROL (generated by tools/make-sync-engine.js; do not edit by hand)
--
-- core.sync_run() takes the waiting changes of the Orders lists from core.sync_inbox (what the ERP saved), applies each to
-- the record it belongs to — the record kept on its row (firebase) — and rebuilds that record's rows with the SAME rules as
-- load-orders.js: the frozen column list (orders-spec.json), the same links, the same Shopify-orders summary.
-- Nothing is deleted: a record removed in Firebase keeps its rows and goes on core.sync_gone.
-- The other sections are still done by the PC processor (tools/sync-apply.js); it leaves the Orders changes to this.
-- Safe to paste again.
-- =====================================================================================================================

-- 1 · helpers: JavaScript's trim / upper, the value converters (make-orders.js CONV), Firebase's way of writing a path
create or replace function core.fb_trim(t text) returns text language sql immutable as $$ select regexp_replace(coalesce(t, ''), '^\s+|\s+$', '', 'g') $$;
create or replace function core.fb_u(t text) returns text language sql immutable as $$ select upper(core.fb_trim(t)) $$;   -- = U() in the loaders ('' for nothing)

create or replace function core.fb_conv(v jsonb, t text) returns jsonb language plpgsql immutable as $$
declare s text; m text[]; y int; mo int; da int; ts timestamptz;
begin
  if v is null or jsonb_typeof(v) = 'null' then return null; end if;
  if t = 'j' then return v; end if;
  s := v #>> '{}';
  if t = 't' then
    if jsonb_typeof(v) = 'string' then return v; end if;
    return to_jsonb(core.js_json(v));                     -- a list or record as text, the way JSON.stringify writes it
  elsif t = 'n' then
    if jsonb_typeof(v) = 'number' then return v; end if;
    s := core.fb_trim(s); if s ~ '^-?\d+(\.\d+)?$' then return to_jsonb(s::numeric); end if; return null;
  elsif t = 'b' then
    if jsonb_typeof(v) = 'boolean' then return v; end if;
    s := lower(core.fb_trim(s));
    if s in ('true', 'yes', 'y') then return 'true'::jsonb; elsif s in ('false', 'no', 'n') then return 'false'::jsonb; end if; return null;
  elsif t = 'd' then
    s := core.fb_trim(s); if s = '' then return null; end if;
    if s ~ '^\d{4}-\d\d-\d\d' then y := substr(s, 1, 4)::int; mo := substr(s, 6, 2)::int; da := substr(s, 9, 2)::int;
    elsif s ~ '^\d\d?[/-]\d\d?[/-]\d{4}$' then m := regexp_match(s, '^(\d\d?)[/-](\d\d?)[/-](\d{4})$'); y := m[3]::int; mo := m[2]::int; da := m[1]::int;
    elsif s ~ '^\d\d?-[A-Za-z]{3}-\d{2,4}$' then
      m := regexp_match(s, '^(\d\d?)-([A-Za-z]{3})-(\d{2,4})$');
      mo := array_position(array['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'], lower(m[2])); if mo is null then return null; end if;
      if length(m[3]) = 2 then y := ('20' || m[3])::int; elsif length(m[3]) = 4 then y := m[3]::int; else return null; end if;
      da := m[1]::int;
    else return null; end if;
    if y < 100 or mo < 1 or mo > 12 or da < 1 or da > extract(day from (make_date(y, mo, 1) + interval '1 month - 1 day')) then return null; end if;   -- a real date only
    return to_jsonb(to_char(make_date(y, mo, da), 'YYYY-MM-DD'));
  elsif t = 'ts' then
    s := core.fb_trim(s); if s = '' then return null; end if;
    if s ~ '^\d{4}-\d\d-\d\d \d\d:\d\d$' then s := replace(s, ' ', 'T') || ':00+05:30';
    elsif s ~ '^\d{4}-\d\d-\d\d$' then s := s || 'T00:00:00+05:30';
    elsif s ~ '^\d{4}-\d\d-\d\d[T ]\d\d:\d\d(:\d\d(\.\d+)?)?$' then s := s || '+05:30';        -- no zone: India time, as the loaders read it
    elsif s ~ '^\d{4}-\d\d-\d\d[T ]\d\d:\d\d(:\d\d(\.\d+)?)?(Z|[+-]\d\d:?\d\d)$' then null;
    else return null; end if;
    begin ts := s::timestamptz; exception when others then return null; end;
    return to_jsonb(to_char(date_trunc('milliseconds', ts) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
  end if;
  return null;
end $$;

-- Firebase keeps no empty lists and no empty values
create or replace function core.fb_norm(v jsonb) returns jsonb language plpgsql immutable as $$
declare o jsonb := '{}'; a jsonb := '[]'; k text; x jsonb; y jsonb; n int;
begin
  if v is null or jsonb_typeof(v) = 'null' then return null; end if;
  if jsonb_typeof(v) = 'array' then
    for x in select e from jsonb_array_elements(v) e loop a := a || jsonb_build_array(coalesce(core.fb_norm(x), 'null'::jsonb)); end loop;
    n := jsonb_array_length(a);
    while n > 0 and jsonb_typeof(a -> (n - 1)) = 'null' loop a := a - (n - 1); n := n - 1; end loop;
    return case when n = 0 then null else a end;
  elsif jsonb_typeof(v) = 'object' then
    for k, x in select key, value from jsonb_each(v) loop y := core.fb_norm(x); if y is not null then o := o || jsonb_build_object(k, y); end if; end loop;
    return case when o = '{}'::jsonb then null else o end;
  end if;
  return v;
end $$;

-- write val at segs under node, the way Firebase does (null removes); = setIn() in sync-apply.js
create or replace function core.fb_set(node jsonb, segs text[], val jsonb) returns jsonb language plpgsql immutable as $$
declare h text; idx int; child jsonb; n int;
begin
  if coalesce(array_length(segs, 1), 0) = 0 then return core.fb_norm(val); end if;
  h := segs[1];
  if node is null or jsonb_typeof(node) not in ('object', 'array') then node := '{}'; end if;
  idx := case when h ~ '^(0|[1-9]\d{0,7})$' then h::int else -1 end;
  if jsonb_typeof(node) = 'array' and idx < 0 then
    node := coalesce((select jsonb_object_agg((o - 1)::text, e) from jsonb_array_elements(node) with ordinality t(e, o) where jsonb_typeof(e) <> 'null'), '{}');
  end if;
  child := core.fb_set(case when jsonb_typeof(node) = 'array' then node -> idx else node -> h end, segs[2:], val);
  if jsonb_typeof(node) = 'array' then
    if idx < jsonb_array_length(node) then node := jsonb_set(node, array[idx::text], coalesce(child, 'null'::jsonb));
    else
      while jsonb_array_length(node) < idx loop node := node || '[null]'::jsonb; end loop;
      node := node || jsonb_build_array(coalesce(child, 'null'::jsonb));
    end if;
    n := jsonb_array_length(node);
    while n > 0 and jsonb_typeof(node -> (n - 1)) = 'null' loop node := node - (n - 1); n := n - 1; end loop;
    return case when n = 0 then null else node end;
  end if;
  if child is null then node := node - h; else node := node || jsonb_build_object(h, child); end if;
  return case when node = '{}'::jsonb then null else node end;
end $$;

-- server time placeholders ({".sv":"timestamp"}) → the time of the save
create or replace function core.fb_sv(v jsonb, ms bigint) returns jsonb language plpgsql immutable as $$
begin
  if v is null or position('".sv"' in v::text) = 0 then return v; end if;
  if jsonb_typeof(v) = 'object' and v = '{".sv": "timestamp"}'::jsonb then return to_jsonb(ms); end if;
  if jsonb_typeof(v) = 'object' then return (select coalesce(jsonb_object_agg(key, core.fb_sv(value, ms)), '{}') from jsonb_each(v)); end if;
  if jsonb_typeof(v) = 'array' then return (select coalesce(jsonb_agg(core.fb_sv(e, ms) order by o), '[]') from jsonb_array_elements(v) with ordinality t(e, o)); end if;
  return v;
end $$;

-- the records a list holds: its entries that are records (objects), keyed by name or position (= objs() in make-orders.js)
create or replace function core.fb_objs(v jsonb) returns table (k text, x jsonb) language sql immutable as $$
  select key, value from jsonb_each(case when jsonb_typeof(v) = 'object' then v else '{}'::jsonb end) where jsonb_typeof(value) = 'object'
  union all
  select (o - 1)::text, e from jsonb_array_elements(case when jsonb_typeof(v) = 'array' then v else '[]'::jsonb end) with ordinality t(e, o) where jsonb_typeof(e) = 'object'
$$;
-- every entry of a list: records only, or (any_value) every value that is there
create or replace function core.fb_ents(v jsonb, any_value boolean) returns table (k text, x jsonb) language sql immutable as $$
  select * from core.fb_objs(v) where not any_value
  union all
  select key, value from jsonb_each(case when any_value and jsonb_typeof(v) = 'object' then v else '{}'::jsonb end) where jsonb_typeof(value) <> 'null'
  union all
  select (o - 1)::text, e from jsonb_array_elements(case when any_value and jsonb_typeof(v) = 'array' then v else '[]'::jsonb end) with ordinality t(e, o) where jsonb_typeof(e) <> 'null'
$$;
create or replace function core.fb_num(k text) returns jsonb language sql immutable as $$ select case when k ~ '^-?\d+(\.\d+)?$' then to_jsonb(k::numeric) end $$;   -- Number(i)

-- 2 · one builder per table: a record → its row (columns exactly as orders-spec.json says)
create or replace function core.syr_sales_orders(x jsonb, lk text, extra jsonb) returns jsonb language sql immutable as $$
  select jsonb_build_object('legacy_key', lk, 'firebase', x)
    || coalesce(extra, '{}'::jsonb)
    || jsonb_build_object('order_no', core.fb_conv(x -> '_id', 't'),
      'fb_key', core.fb_conv(x -> '_key', 't'),
      'approved_at', core.fb_conv(x -> 'approvedAt', 'ts'),
      'approved_by', core.fb_conv(x -> 'approvedBy', 't'),
      'auto_from', core.fb_conv(x -> 'autoFrom', 't'),
      'buyer_email', core.fb_conv(x -> 'buyerEmail', 't'),
      'buyer_name', core.fb_conv(x -> 'buyerName', 't'),
      'channel', core.fb_conv(x -> 'channel', 't'),
      'created_at_fb', core.fb_conv(x -> 'createdAt', 'ts'),
      'created_by_fb', core.fb_conv(x -> 'createdBy', 't'),
      'delivery_date', core.fb_conv(x -> 'deliveryDate', 'd'),
      'delivery_mode', core.fb_conv(x -> 'deliveryMode', 't'),
      'legacy_order_id', core.fb_conv(x -> 'legacyOrderId', 't'),
      'order_date', core.fb_conv(x -> 'orderDate', 'd'),
      'order_type_key', core.fb_conv(x -> 'orderTypeKey', 't'),
      'renumbered_from', core.fb_conv(x -> 'renumberedFrom', 't'),
      'reviewed_at', core.fb_conv(x -> 'reviewedAt', 'ts'),
      'reviewed_by', core.fb_conv(x -> 'reviewedBy', 't'),
      'sa_remarks', core.fb_conv(x -> 'saRemarks', 't'),
      'sale_month', core.fb_conv(x -> 'saleMonth', 't'),
      'ship_mode', core.fb_conv(x -> 'shipMode', 't'),
      'shop_order_id', core.fb_conv(x -> 'shopOrderId', 't'),
      'src', core.fb_conv(x -> 'src', 't'),
      'status', core.fb_conv(x -> 'status', 't'),
      'submitted_at', core.fb_conv(x -> 'submittedAt', 'ts'),
      'updated_at_fb', core.fb_conv(x -> 'updatedAt', 'ts'))
$$;
