-- 3 · links, the same as load-orders.js: SKU (normal and custom, first by id), channel, vendor (code, then name), Control request,
--     sales order by its number and by its Shopify order (the last one wins, as there), Shopify order, vendor order by its Firebase id
create index if not exists skus_fb_u_sku on core.skus (core.fb_u(sku));
create index if not exists custom_skus_fb_u_sku on core.custom_skus (core.fb_u(sku));
create index if not exists orders_fb_u_order_no on sales.orders (core.fb_u(order_no));
create index if not exists orders_shop_order_id on sales.orders (shop_order_id);
create index if not exists shopify_orders_shop_order_id on sales.shopify_orders (shop_order_id);
create index if not exists vendor_orders_fb_id on production.vendor_orders (fb_id);
create index if not exists order_book_shop_order_fb on production.order_book ((firebase ->> 'shopOrderId'));
create index if not exists order_book_fb_u_order_no on production.order_book (core.fb_u(order_no));
create index if not exists vendor_challan_lines_vo_id on production.vendor_challan_lines (vo_id);
create index if not exists sync_gone_tbl_key on core.sync_gone (tbl, legacy_key);

create or replace function core.sy_sku(r jsonb) returns jsonb language plpgsql stable security definer set search_path = core, public as $$
declare k text := core.fb_u(r ->> 'sku');
begin
  if k = '' then return r || jsonb_build_object('sku_id', null, 'custom_sku_id', null); end if;   -- no SKU written: no SKU link (as the loader)
  return r || jsonb_build_object('sku_id', (select id from core.skus where core.fb_u(sku) = k order by id limit 1),
                                 'custom_sku_id', (select id from core.custom_skus where core.fb_u(sku) = k order by id limit 1));
end $$;
create or replace function core.sy_channel(s text) returns bigint language sql stable security definer set search_path = core, public as $$
  select c.id from sales.channels c, (select core.fb_trim(s) v) a
   where c.code = (case when v = 'SHOPIFY' or v = 'SPY' or v = 'SHP' or v = 'Shopify' then 'SHOPIFY' when v = 'SHOPIFY_CPC' or v = 'CPC Shopify' then 'SHOPIFY_CPC' when v = 'AMAZON' or v = 'AMZ' or v = 'Amazon' or v = 'SP' then 'AMAZON' when v = 'AMAZON_CPC' or v = 'CPC' then 'AMAZON_CPC' when v = 'B2B' or v = 'B2B' then 'B2B' when v = 'ONLINE' or v = 'ONL' or v = 'Online' then 'ONLINE' end)
$$;
create or replace function core.sy_vendor(p_code text, p_name text) returns bigint language sql stable security definer set search_path = core, public as $$
  select coalesce(
    (select id from core.vendors where coalesce(code, '') <> '' and source = 'vendor' and core.fb_u(code) = core.fb_u(p_code) order by id limit 1),
    (select id from core.vendors where coalesce(name, '') <> '' and core.fb_u(name) = core.fb_u(p_name) order by id limit 1))
$$;
create or replace function core.sy_so_by_no(p text) returns bigint language sql stable security definer set search_path = core, public as $$
  select id from sales.orders where core.fb_u(order_no) = core.fb_u(p) order by id desc limit 1
$$;

-- every row goes in through the Orders load door; answers its id; a row written again is off the gone list
create or replace function core.sy_put(p_table text, p_row jsonb) returns bigint language plpgsql security definer set search_path = core, public as $$
declare rid bigint;
begin
  if split_part(p_table, '.', 1) = 'stock' then perform core.load_stock_rows(p_table, jsonb_build_array(p_row));
  elsif split_part(p_table, '.', 1) = 'core' then perform core.load_sku_rows(split_part(p_table, '.', 2), jsonb_build_array(p_row));   -- the SKU tables
  else perform core.load_order_rows(p_table, jsonb_build_array(p_row)); end if;
  execute format('select id from %s where legacy_key = $1', p_table) into rid using p_row ->> 'legacy_key';
  delete from core.sync_gone where tbl = p_table and legacy_key = p_row ->> 'legacy_key';   -- the list entry only
  return rid;
end $$;
-- rows of a record's list that the record no longer has → on the gone list (the rows stay)
create or replace function core.sy_gone_under(p_table text, p_prefix text, p_keep text[]) returns void language plpgsql security definer set search_path = core, public as $$
begin
  execute format('insert into core.sync_gone (tbl, legacy_key) select %L, legacy_key from %s where left(legacy_key, %s) = %L and not (legacy_key = any($1)) on conflict do nothing',
                 p_table, p_table, length(p_prefix), p_prefix) using coalesce(p_keep, '{}');
end $$;

-- 4 · one function per Firebase list: a whole record → its row and the rows of its lists (= load-orders.js)
create or replace function core.sy_sales(lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare r jsonb; pid bigint; c record; keep text[]; ck text; ono text; sho text;
begin
  r := core.syr_sales_orders(x, lk, '{}'); r := r || jsonb_build_object('channel_id', core.sy_channel(r ->> 'channel'));
  pid := core.sy_put('sales.orders', r); ono := r ->> 'order_no'; sho := nullif(r ->> 'shop_order_id', '');
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'lines') loop
    ck := lk || '/lines/' || c.k; keep := keep || ck;
    r := core.syr_sales_order_lines(c.x, ck, jsonb_build_object('line_no', core.fb_num(c.k))) || jsonb_build_object('order_id', pid);
    r := core.sy_sku(r);
    perform core.sy_put('sales.order_lines', r);
  end loop;
  perform core.sy_gone_under('sales.order_lines', lk || '/lines/', keep);
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'qtyAdjustments') loop
    ck := lk || '/qtyAdjustments/' || c.k; keep := keep || ck;
    r := core.syr_sales_order_qty_changes(c.x, ck, '{}'::jsonb) || jsonb_build_object('order_id', pid);
    r := core.sy_sku(r);
    perform core.sy_put('sales.order_qty_changes', r);
  end loop;
  perform core.sy_gone_under('sales.order_qty_changes', lk || '/qtyAdjustments/', keep);
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'removedLines') loop
    ck := lk || '/removedLines/' || c.k; keep := keep || ck;
    r := core.syr_sales_order_removed_lines(c.x, ck, jsonb_build_object('source', 'removedLines')) || jsonb_build_object('order_id', pid);
    r := core.sy_sku(r); r := r || jsonb_build_object('approval_id', (select id from core.approvals where legacy_key = 'pt_obDeleteReqs/' || (r ->> 'req_id')));
    perform core.sy_put('sales.order_removed_lines', r);
  end loop;
  perform core.sy_gone_under('sales.order_removed_lines', lk || '/removedLines/', keep);
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'lineRemovals') loop
    ck := lk || '/lineRemovals/' || c.k; keep := keep || ck;
    r := core.syr_sales_order_removed_lines(c.x, ck, jsonb_build_object('source', 'lineRemovals')) || jsonb_build_object('order_id', pid);
    r := core.sy_sku(r); r := r || jsonb_build_object('approval_id', (select id from core.approvals where legacy_key = 'pt_obDeleteReqs/' || (r ->> 'req_id')));
    perform core.sy_put('sales.order_removed_lines', r);
  end loop;
  perform core.sy_gone_under('sales.order_removed_lines', lk || '/lineRemovals/', keep);
  -- what points at a sales order by its number / its Shopify order finds it (the newest one with that number, as the loader)
  update production.order_book b set sales_order_id = core.sy_so_by_no(b.order_no) where core.fb_u(b.order_no) = core.fb_u(ono) and b.sales_order_id is distinct from core.sy_so_by_no(b.order_no);
  if sho is not null then
    update sales.shopify_orders s set sales_order_id = (select id from sales.orders o where o.shop_order_id = sho order by id desc limit 1)
     where s.shop_order_id = sho and s.sales_order_id is distinct from (select id from sales.orders o where o.shop_order_id = sho order by id desc limit 1);
  end if;
end $$;

-- the Shopify order summary, made again from every order-book record that names this Shopify order (= load-orders.js / make-orders.js)
create or replace function core.sy_shopify(k text) returns void language plpgsql security definer set search_path = core, public as $$
declare b record; n int := 0; sno text; ono text; says text; says_at text; why text; rid bigint;
begin
  if k is null or k = '' then return; end if;
  for b in select o.firebase x from production.order_book o
            where o.firebase ->> 'shopOrderId' = k
              and not exists (select 1 from core.sync_gone g where g.tbl = 'production.order_book' and g.legacy_key = o.legacy_key)
            order by o.legacy_key collate "C" loop
    if n = 0 then sno := b.x ->> 'shopOrderNo'; ono := nullif(b.x ->> 'orderNo', ''); end if;
    n := n + 1;
    if coalesce(b.x ->> 'shopSaysAt', '') <> '' and (says_at is null or (b.x ->> 'shopSaysAt') collate "C" > says_at collate "C") then
      says := nullif(b.x ->> 'shopSays', ''); says_at := b.x ->> 'shopSaysAt'; end if;
    if coalesce(b.x ->> 'shopDoneWhy', '') <> '' then why := b.x ->> 'shopDoneWhy'; end if;
  end loop;
  if n = 0 then
    insert into core.sync_gone (tbl, legacy_key) select 'sales.shopify_orders', 'shopify/' || k where exists (select 1 from sales.shopify_orders where legacy_key = 'shopify/' || k) on conflict do nothing;
    return;
  end if;
  rid := core.sy_put('sales.shopify_orders', jsonb_build_object('legacy_key', 'shopify/' || k, 'shop_order_id', k, 'shop_order_no', sno, 'order_no', ono,
    'rows_on_order_book', n, 'shop_says', says, 'shop_says_at', says_at, 'shop_done_why', why, 'firebase', null,
    'sales_order_id', (select id from sales.orders o where o.shop_order_id = k order by id desc limit 1), 'channel_id', (select id from sales.channels where code = 'SHOPIFY')));
  update production.order_book o set shopify_order_id = rid where o.shop_order_id = k and o.shopify_order_id is distinct from rid;
end $$;

create or replace function core.sy_order_book(lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare r jsonb; pid bigint; c record; keep text[]; ck text; was text; now_k text;
begin
  select firebase ->> 'shopOrderId' into was from production.order_book where legacy_key = lk;
  r := core.syr_order_book(x, lk, '{}');
  r := r || jsonb_build_object('sales_order_id', core.sy_so_by_no(r ->> 'order_no'),
    'shopify_order_id', case when r ->> 'shop_order_id' is not null then (select id from sales.shopify_orders s where s.shop_order_id = r ->> 'shop_order_id' order by id desc limit 1) end);
  r := core.sy_sku(r);
  pid := core.sy_put('production.order_book', r);
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'shopDoneLog') loop
    ck := lk || '/shopDoneLog/' || c.k; keep := keep || ck;
    r := core.syr_order_book_done_log(c.x, ck, '{}'::jsonb) || jsonb_build_object('order_book_id', pid);
    perform core.sy_put('production.order_book_done_log', r);
  end loop;
  perform core.sy_gone_under('production.order_book_done_log', lk || '/shopDoneLog/', keep);
  now_k := x ->> 'shopOrderId';
  perform core.sy_shopify(now_k);
  if was is distinct from now_k then perform core.sy_shopify(was); end if;
end $$;

create or replace function core.sy_vendor_order(lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare r jsonb; pid bigint; c record; keep text[]; ck text; fid text;
begin
  r := core.syr_vendor_orders(x, lk, jsonb_build_object('vendor_key', split_part(lk, '/', 2)));
  r := r || jsonb_build_object('vendor_id', core.sy_vendor(coalesce(nullif(r ->> 'vendor_code', ''), r ->> 'vendor_key'), r ->> 'vendor_name'),
    'channel_id', core.sy_channel(r ->> 'channel'),
    'approval_id', case when coalesce(r ->> 'request_id', '') <> '' then (select id from core.approvals where legacy_key = 'pt_vendorOrderReqs/' || (r ->> 'request_id')) end);
  pid := core.sy_put('production.vendor_orders', r); fid := r ->> 'fb_id';
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'lines') loop
    ck := lk || '/lines/' || c.k; keep := keep || ck;
    r := core.syr_vendor_order_lines(c.x, ck, jsonb_build_object('line_no', core.fb_num(c.k))) || jsonb_build_object('vendor_order_id', pid);
    r := core.sy_sku(r);
    perform core.sy_put('production.vendor_order_lines', r);
  end loop;
  perform core.sy_gone_under('production.vendor_order_lines', lk || '/lines/', keep);
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'rfdReqs') loop
    ck := lk || '/rfdReqs/' || c.k; keep := keep || ck;
    r := core.syr_vendor_rfd_requests(c.x, ck, '{}'::jsonb) || jsonb_build_object('vendor_order_id', pid);
    r := core.sy_sku(r);
    perform core.sy_put('production.vendor_rfd_requests', r);
  end loop;
  perform core.sy_gone_under('production.vendor_rfd_requests', lk || '/rfdReqs/', keep);
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'vSent') loop
    ck := lk || '/vSent/' || c.k; keep := keep || ck;
    r := core.syr_vendor_sent(c.x, ck, '{}'::jsonb) || jsonb_build_object('vendor_order_id', pid);
    r := core.sy_sku(r);
    perform core.sy_put('production.vendor_sent', r);
  end loop;
  perform core.sy_gone_under('production.vendor_sent', lk || '/vSent/', keep);
  if coalesce(fid, '') <> '' then     -- challan lines that name this vendor order find it
    update production.vendor_challan_lines l set vendor_order_id = (select id from production.vendor_orders v where v.fb_id = fid order by id desc limit 1)
     where l.vo_id = fid and l.vendor_order_id is distinct from (select id from production.vendor_orders v where v.fb_id = fid order by id desc limit 1);
  end if;
end $$;

create or replace function core.sy_challan(lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare r jsonb; pid bigint; c record; keep text[]; ck text;
begin
  r := core.syr_vendor_challans(x, lk, jsonb_build_object('vendor_key', split_part(lk, '/', 2)));
  r := r || jsonb_build_object('vendor_id', core.sy_vendor(coalesce(nullif(r ->> 'code', ''), r ->> 'vendor_key'), r ->> 'name'));
  pid := core.sy_put('production.vendor_challans', r);
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'lines') loop
    ck := lk || '/lines/' || c.k; keep := keep || ck;
    r := core.syr_vendor_challan_lines(c.x, ck, jsonb_build_object('line_no', core.fb_num(c.k))) || jsonb_build_object('vendor_challan_id', pid);
    r := core.sy_sku(r); r := r || jsonb_build_object('vendor_order_id', case when coalesce(r ->> 'vo_id', '') <> '' then (select id from production.vendor_orders v where v.fb_id = r ->> 'vo_id' order by id desc limit 1) end);
    perform core.sy_put('production.vendor_challan_lines', r);
  end loop;
  perform core.sy_gone_under('production.vendor_challan_lines', lk || '/lines/', keep);
end $$;

create or replace function core.sy_shop_floor(lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare r jsonb; pid bigint; c record; keep text[]; ck text;
begin
  r := core.sy_sku(core.syr_shop_production(x, lk, '{}'));
  r := r || jsonb_build_object('vendor_id', case when coalesce(r ->> 'printer', '') <> '' then
            (select id from core.vendors where coalesce(code, '') <> '' and source = 'vendor' and core.fb_u(code) = core.fb_u(r ->> 'printer') order by id limit 1) end);
  pid := core.sy_put('production.shop_floor', r);
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'handLog') loop
    ck := lk || '/handLog/' || c.k; keep := keep || ck;
    r := core.syr_shop_hand_log(c.x, ck, '{}'::jsonb) || jsonb_build_object('shop_floor_id', pid);
    perform core.sy_put('production.shop_hand_log', r);
  end loop;
  perform core.sy_gone_under('production.shop_hand_log', lk || '/handLog/', keep);
end $$;

create or replace function core.sy_amazon_po(lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare r jsonb; pid bigint; c record; keep text[]; ck text;
begin
  r := core.syr_amazon_pos(x, lk, '{}');
  r := r || jsonb_build_object('channel_id', (select id from sales.channels where code = case when core.fb_u(r ->> 'brand') = 'CPC' then 'AMAZON_CPC' else 'AMAZON' end));
  pid := core.sy_put('sales.amazon_pos', r);
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'lines') loop
    ck := lk || '/lines/' || c.k; keep := keep || ck;
    r := core.syr_amazon_po_lines(c.x, ck, jsonb_build_object('line_no', core.fb_num(c.k))) || jsonb_build_object('amazon_po_id', pid);
    r := core.sy_sku(r);
    perform core.sy_put('sales.amazon_po_lines', r);
  end loop;
  perform core.sy_gone_under('sales.amazon_po_lines', lk || '/lines/', keep);
  
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'followups') loop
    ck := lk || '/followups/' || c.k; keep := keep || ck;
    r := core.syr_amazon_po_followups(c.x, ck, '{}'::jsonb) || jsonb_build_object('amazon_po_id', pid);
    perform core.sy_put('sales.amazon_po_followups', r);
  end loop;
  perform core.sy_gone_under('sales.amazon_po_followups', lk || '/followups/', keep);
end $$;

create or replace function core.sy_packing_list(lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare r jsonb; pid bigint; bid bigint; c record; i record; keep text[]; ikeep text[] := '{}'; ck text; bk text;
begin
  pid := core.sy_put('shipping.packing_lists', core.syr_packing_lists(x, lk, '{}'));
  keep := '{}';
  for c in select * from core.fb_objs(x -> 'boxes') loop
    bk := lk || '/boxes/' || c.k; keep := keep || bk;
    bid := core.sy_put('shipping.boxes', core.syr_packing_boxes(c.x, bk, jsonb_build_object('box_index', core.fb_num(c.k))) || jsonb_build_object('packing_list_id', pid));
    for i in select * from core.fb_objs(c.x -> 'items') loop
      ck := bk || '/items/' || i.k; ikeep := ikeep || ck;
      perform core.sy_put('shipping.box_items', core.sy_sku(core.syr_packing_box_items(i.x, ck, jsonb_build_object('line_no', core.fb_num(i.k))) || jsonb_build_object('box_id', bid)));
    end loop;
  end loop;
  perform core.sy_gone_under('shipping.boxes', lk || '/boxes/', keep);
  perform core.sy_gone_under('shipping.box_items', lk || '/boxes/', ikeep);
end $$;

-- 4b · STOCK — its own converters for dates ("24/09/2026, 17:54" is a time in India; a day may have a time after it), links as load-stock.js
create or replace function core.fb_conv_stock(v jsonb, t text) returns jsonb language plpgsql immutable as $$
declare s text; m text[]; y int; mo int; da int; ts timestamptz;
begin
  if t not in ('d', 'ts') then return core.fb_conv(v, t); end if;
  if v is null or jsonb_typeof(v) = 'null' then return null; end if;
  s := core.fb_trim(v #>> '{}'); if s = '' then return null; end if;
  if t = 'ts' then
    m := regexp_match(s, '^(\d\d?)[/-](\d\d?)[/-](\d{4}),?\s+(\d\d?):(\d\d)$');
    if m is not null then
      y := m[3]::int; mo := m[2]::int; da := m[1]::int;
      if y < 100 or mo < 1 or mo > 12 or da < 1 or da > extract(day from (make_date(y, mo, 1) + interval '1 month - 1 day')) then return null; end if;
      begin ts := (to_char(make_date(y, mo, da), 'YYYY-MM-DD') || 'T' || lpad(m[4], 2, '0') || ':' || m[5] || ':00+05:30')::timestamptz; exception when others then return null; end;
      return to_jsonb(to_char(ts at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
    end if;
    return core.fb_conv(v, 'ts');
  end if;
  -- a day: ISO first, then d/m/yyyy (anything may follow), then 10-Nov-26
  if s ~ '^\d{4}-\d\d-\d\d' then y := substr(s, 1, 4)::int; mo := substr(s, 6, 2)::int; da := substr(s, 9, 2)::int;
  elsif s ~ '^\d\d?[/-]\d\d?[/-]\d{4}' then m := regexp_match(s, '^(\d\d?)[/-](\d\d?)[/-](\d{4})'); y := m[3]::int; mo := m[2]::int; da := m[1]::int;
  elsif s ~ '^\d\d?-[A-Za-z]{3}-\d{2,4}$' then
    m := regexp_match(s, '^(\d\d?)-([A-Za-z]{3})-(\d{2,4})$');
    mo := array_position(array['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'], lower(m[2])); if mo is null then return null; end if;
    if length(m[3]) = 2 then y := ('20' || m[3])::int; elsif length(m[3]) = 4 then y := m[3]::int; else return null; end if;
    da := m[1]::int;
  else return null; end if;
  if y < 100 or mo < 1 or mo > 12 or da < 1 or da > extract(day from (make_date(y, mo, 1) + interval '1 month - 1 day')) then return null; end if;
  return to_jsonb(to_char(make_date(y, mo, da), 'YYYY-MM-DD'));
end $$;
create or replace function core.fb_key(t text) returns text language sql immutable as $$ select lower(regexp_replace(core.fb_trim(t), '\s+', ' ', 'g')) $$;   -- = key() in the loaders

