-- links, as load-stock.js: SKU (first by id), sales order by its number (the FIRST one, as there), fabric / colour by name, accessory by code then name
create or replace function core.syk_sku(p text) returns jsonb language sql stable security definer set search_path = core, public as $$
  select case when core.fb_u(p) = '' then jsonb_build_object('sku_id', null, 'custom_sku_id', null) else jsonb_build_object(
    'sku_id', (select id from core.skus where core.fb_u(sku) = core.fb_u(p) order by id limit 1),
    'custom_sku_id', (select id from core.custom_skus where core.fb_u(sku) = core.fb_u(p) order by id limit 1)) end
$$;
create or replace function core.syk_so(p text) returns bigint language sql stable security definer set search_path = core, public as $$
  select case when core.fb_u(p) <> '' then (select id from sales.orders where core.fb_u(order_no) = core.fb_u(p) order by id limit 1) end
$$;
create or replace function core.sy_stock(reg text, lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare r jsonb; pid bigint; c record; keep text[]; ck text; v text;
begin
  case reg
  when 'pt_fgiLedger' then
    r := core.syk_fg_ledger(x, lk, '{}'); r := r || core.syk_sku(r ->> 'sku'); r := r || jsonb_build_object('sales_order_id', core.syk_so(r ->> 'order_no'));
    pid := core.sy_put('stock.fg_ledger', r);
    keep := '{}';
    for c in select * from core.fb_objs(x -> 'edits') loop
      ck := lk || '/edits/' || c.k; keep := keep || ck;
      perform core.sy_put('stock.fg_ledger_edits', core.syk_fg_ledger_edits(c.x, ck, '{}') || jsonb_build_object('fg_ledger_id', pid));
    end loop;
    perform core.sy_gone_under('stock.fg_ledger_edits', lk || '/edits/', keep);
  when 'pt_fabInvLedger' then
    r := core.syk_fabric_ledger(x, lk, '{}'); r := r || jsonb_build_object('fabric_id', (select id from core.fabrics where core.fb_key(name) = core.fb_key(r ->> 'fabric_type') and core.fb_key(r ->> 'fabric_type') <> '' order by id limit 1)); r := r || jsonb_build_object('sales_order_id', core.syk_so(r ->> 'order_no'));
    perform core.sy_put('stock.fabric_ledger', r);
  when 'pt_accLedger' then
    r := core.syk_accessory_ledger(x, lk, '{}'); v := r ->> 'item_code';
    r := r || jsonb_build_object('accessory_id', coalesce(
      case when core.fb_u(v) <> '' then (select id from core.accessories where core.fb_u(code) = core.fb_u(v) order by id limit 1) end,
      case when core.fb_key(v) <> '' then (select id from core.accessories where core.fb_key(name) = core.fb_key(v) order by id limit 1) end));
    perform core.sy_put('stock.accessory_ledger', r);
  when 'pt_pressInventory' then
    r := core.syk_press_stock(x, lk, '{}'); r := r || core.syk_sku(r ->> 'sku'); r := r || jsonb_build_object('sales_order_id', core.syk_so(r ->> 'order_no'));
    perform core.sy_put('stock.press_stock', r);
  when 'pt_accReserve' then
    r := core.syk_accessory_reserve(x, lk, '{}'); r := r || core.syk_sku(r ->> 'sku'); r := r || jsonb_build_object('sales_order_id', core.syk_so(r ->> 'order_no'));
    perform core.sy_put('stock.accessory_reserve', r);
  when 'pt_storeLedger' then
    r := core.syk_store_ledger(x, lk, '{}'); r := r || jsonb_build_object('fabric_id', (select id from core.fabrics where core.fb_key(name) = core.fb_key(r ->> 'fabric') and core.fb_key(r ->> 'fabric') <> '' order by id limit 1));
    r := r || jsonb_build_object('colour_id', (select id from core.colours where core.fb_key(name) = core.fb_key(r ->> 'colour') and core.fb_key(r ->> 'colour') <> '' order by id limit 1));
    r := r || core.syk_sku(r ->> 'sku');
    perform core.sy_put('stock.store_ledger', r);
  when 'pt_rfdStock' then
    r := core.syk_rfd_stock(x, lk, jsonb_build_object('group_key', split_part(lk, '/', 2)));
    v := coalesce(r ->> 'order_id', '');
    r := r || jsonb_build_object('vendor_order_id', case when v <> '' then (select id from production.vendor_orders where fb_id = v order by id limit 1) end);
    perform core.sy_put('stock.rfd_stock', r);
  when 'pt_issueRecipients' then
    perform core.sy_put('stock.issue_recipients', core.syk_issue_recipients(x, lk, '{}'));
  end case;
end $$;

-- 4c · SKUs — times as their loader reads them (a number = milliseconds, a bare day = UTC), links to Masters by name,
--      code clashes counted over both tables, the FNSKU list one row per line; Orders and Stock lines linked again when a SKU changes
create or replace function core.fb_conv_sku(v jsonb, t text) returns jsonb language plpgsql immutable as $$
declare s text; ts timestamptz;
begin
  if t <> 'ts' then return core.fb_conv(v, t); end if;
  if v is null or jsonb_typeof(v) = 'null' then return null; end if;
  if jsonb_typeof(v) = 'number' then
    begin ts := to_timestamp((v #>> '{}')::numeric / 1000); exception when others then return null; end;
  else
    s := core.fb_trim(v #>> '{}'); if s = '' then return null; end if;
    if s ~ '^\d{4}-\d\d-\d\d$' then s := s || 'T00:00:00Z';                                            -- a bare day is UTC in JavaScript
    elsif s ~ '^\d{4}-\d\d-\d\d[T ]\d\d:\d\d(:\d\d(\.\d+)?)?$' then s := s || '+05:30';            -- no zone: India time
    elsif s ~ '^\d{4}-\d\d-\d\d[T ]\d\d:\d\d(:\d\d(\.\d+)?)?(Z|[+-]\d\d:?\d\d)$' then null;
    else return null; end if;
    begin ts := s::timestamptz; exception when others then return null; end;
  end if;
  return to_jsonb(to_char(date_trunc('milliseconds', ts) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
end $$;
