-- links to Masters, as load-skus.js: type by name, else by its code; subtype by name (the one under that type first); colour, size, fabric by name
create or replace function core.sy_sku_links(r jsonb) returns jsonb language plpgsql stable security definer set search_path = core, public as $$
declare tid bigint; k text;
begin
  k := core.fb_key(r ->> 'article_type');
  tid := coalesce((select id from core.article_types where k <> '' and core.fb_key(name) = k order by id limit 1),
                  (select id from core.article_types where k <> '' and coalesce(code, '') <> '' and core.fb_key(code) = k order by id limit 1));
  k := core.fb_key(r ->> 'subtype');
  return r || jsonb_build_object('article_type_id', tid,
    'subtype_id', (select id from core.article_subtypes where k <> '' and core.fb_key(name) = k order by (article_type_id is not distinct from tid) desc, id limit 1),
    'colour_id', (select id from core.colours where core.fb_key(r ->> 'color') <> '' and core.fb_key(name) = core.fb_key(r ->> 'color') order by id limit 1),
    'size_id', (select id from core.sizes where core.fb_key(r ->> 'size') <> '' and core.fb_key(name) = core.fb_key(r ->> 'size') order by id limit 1),
    'fabric_id', (select id from core.fabrics where core.fb_key(r ->> 'fabric') <> '' and core.fb_key(name) = core.fb_key(r ->> 'fabric') order by id limit 1));
end $$;
-- the clash mark of every SKU with this code, in both tables (rows Firebase no longer has are not counted)
create or replace function core.sy_clash(c text) returns void language plpgsql security definer set search_path = core, public as $$
#variable_conflict use_variable
declare n int; m int;
begin
  if coalesce(c, '') = '' then return; end if;
  select count(*) into n from core.skus s where core.fb_u(s.sku) = c and not exists (select 1 from core.sync_gone g where g.tbl = 'core.skus' and g.legacy_key = s.legacy_key);
  select count(*) into m from core.custom_skus s where core.fb_u(s.sku) = c and not exists (select 1 from core.sync_gone g where g.tbl = 'core.custom_skus' and g.legacy_key = s.legacy_key);
  update core.skus s set code_clash = nullif(concat_ws(' · ', case when n > 1 then 'twice in this table' end, case when m > 0 then 'also a custom SKU' end), '')
   where core.fb_u(s.sku) = c and not exists (select 1 from core.sync_gone g where g.tbl = 'core.skus' and g.legacy_key = s.legacy_key)
     and s.code_clash is distinct from nullif(concat_ws(' · ', case when n > 1 then 'twice in this table' end, case when m > 0 then 'also a custom SKU' end), '');
  update core.custom_skus s set code_clash = nullif(concat_ws(' · ', case when m > 1 then 'twice in this table' end, case when n > 0 then 'also a normal SKU' end), '')
   where core.fb_u(s.sku) = c and not exists (select 1 from core.sync_gone g where g.tbl = 'core.custom_skus' and g.legacy_key = s.legacy_key)
     and s.code_clash is distinct from nullif(concat_ws(' · ', case when m > 1 then 'twice in this table' end, case when n > 0 then 'also a normal SKU' end), '');
end $$;
-- Orders and Stock lines with this code find the SKU (first by id, normal and custom — as their loaders)
create or replace function core.sy_relink_sku(p_code text) returns void language plpgsql security definer set search_path = core, public as $$
declare v_n bigint; v_m bigint;
begin
  if coalesce(p_code, '') = '' then return; end if;
  v_n := (select id from core.skus where core.fb_u(sku) = p_code order by id limit 1);
  v_m := (select id from core.custom_skus where core.fb_u(sku) = p_code order by id limit 1);
  update sales.order_lines set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update sales.order_qty_changes set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update sales.order_removed_lines set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update production.order_book set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update production.vendor_order_lines set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update production.vendor_rfd_requests set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update production.vendor_sent set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update production.vendor_challan_lines set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update production.shop_floor set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update sales.amazon_po_lines set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update shipping.box_items set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update stock.fg_ledger set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update stock.press_stock set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update stock.accessory_reserve set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
  update stock.store_ledger set sku_id = v_n, custom_sku_id = v_m where core.fb_u(sku) = p_code and (sku_id, custom_sku_id) is distinct from (v_n, v_m);
end $$;

create or replace function core.sy_skus(reg text, lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare r jsonb; was text; tbl text; c record; keep text[] := '{}'; fl text;
begin
  if reg in ('pt_masterDB', 'pt_customSkus') then
    tbl := case reg when 'pt_masterDB' then 'core.skus' else 'core.custom_skus' end;
    execute format('select core.fb_u(sku) from %s where legacy_key = $1', tbl) into was using lk;
    r := core.sy_sku_links(case reg when 'pt_masterDB' then core.sys_skus(x, lk) else core.sys_custom_skus(x, lk) end);
    perform core.sy_put(tbl, r);
    perform core.sy_clash(core.fb_u(r ->> 'sku')); perform core.sy_relink_sku(core.fb_u(r ->> 'sku'));
    if was is distinct from core.fb_u(r ->> 'sku') then perform core.sy_clash(was); perform core.sy_relink_sku(was); end if;
  elsif reg in ('pt_skuImages', 'pt_skuPriority') then
    perform core.sy_put(case reg when 'pt_skuImages' then 'core.sku_images' else 'core.sku_priority' end,
      jsonb_build_object('legacy_key', lk, 'sku', split_part(lk, '/', 2), case reg when 'pt_skuImages' then 'image_url' else 'priority' end,
                         case when jsonb_typeof(x) = 'string' then x #>> '{}' else x::text end, 'firebase', x));
  elsif reg = 'pt_fnskuMap' then
    -- the record itself is kept as a setting; its list becomes one row per line
    perform core.load_settings(jsonb_build_array(jsonb_build_object('key', 'skus.fnsku_map', 'value', x,
      'note', 'pt_fnskuMap exactly as it is (at, by, src, n, and the whole list); its lines are also in core.fnsku_list', 'legacy_key', 'pt_fnskuMap')));
    for c in select l, i from unnest(string_to_array(coalesce(x ->> 'list', ''), E'\n')) with ordinality u(l, i) where l <> '' loop
      fl := 'pt_fnskuMap/list#' || c.i; keep := keep || fl;
      perform core.sy_put('core.fnsku_list', jsonb_build_object('legacy_key', fl, 'line_no', c.i, 'fnsku', split_part(c.l, E'\t', 1),
        'sku', case when position(E'\t' in c.l) > 0 then substr(c.l, position(E'\t' in c.l) + 1) else '' end, 'firebase', null));
    end loop;
    perform core.sy_gone_under('core.fnsku_list', 'pt_fnskuMap/', keep);
  end if;
end $$;


-- =====================================================================================================================
-- MASTERS + CONTROL — the engine's working copy of their Firebase lists, the JavaScript value rules, the two builders
-- =====================================================================================================================
create table if not exists core.sync_raw (
  reg    text not null,                 -- pt_masters · pt_colorGroups · pt_gdTest · the six request lists
  k      text not null,                 -- the key under it (a Masters list name, a request id …)
  value  jsonb,                         -- as Firebase has it (null = no longer there; the row is kept)
  at     timestamptz not null default now(),
  primary key (reg, k)
);
alter table core.sync_raw enable row level security;
comment on table core.sync_raw is 'The live mirror engine''s working copy of the Firebase lists whose tables do not keep each record whole (Masters, Control).';
create or replace function core.sync_raw_load(p jsonb) returns int language plpgsql security definer set search_path = core, public as $$
declare n int;
begin
  insert into core.sync_raw (reg, k, value) select x ->> 'reg', x ->> 'k', case when x -> 'value' = 'null'::jsonb then null else x -> 'value' end from jsonb_array_elements(p) x
  on conflict (reg, k) do update set value = excluded.value, at = now();
  get diagnostics n = row_count; return n;
end $$;

-- JavaScript's own value rules, as the two loaders use them
create or replace function core.js_json(v jsonb) returns text language plpgsql immutable as $$    -- JSON.stringify(v): no spaces (a record's own key order is Firebase's, not kept)
begin
  if v is null then return null; end if;
  if jsonb_typeof(v) = 'array' then return '[' || coalesce((select string_agg(core.js_json(e), ',' order by o) from jsonb_array_elements(v) with ordinality t(e, o)), '') || ']'; end if;
  if jsonb_typeof(v) = 'object' then return '{' || coalesce((select string_agg(to_jsonb(key)::text || ':' || core.js_json(value), ',') from jsonb_each(v)), '') || '}'; end if;
  return v::text;
end $$;
create or replace function core.js_str(v jsonb) returns text language plpgsql immutable as $$   -- String(v)
begin
  if v is null or jsonb_typeof(v) = 'null' then return ''; end if;
  if jsonb_typeof(v) = 'object' then return '[object Object]'; end if;
  if jsonb_typeof(v) = 'array' then return (select coalesce(string_agg(case when jsonb_typeof(e) = 'null' then '' else core.js_str(e) end, ',' order by o), '') from jsonb_array_elements(v) with ordinality t(e, o)); end if;
  return v #>> '{}';
end $$;
create or replace function core.js_truthy(v jsonb) returns boolean language sql immutable as $$
  select not (v is null or jsonb_typeof(v) = 'null' or v = '""'::jsonb or v = 'false'::jsonb or (jsonb_typeof(v) = 'number' and (v #>> '{}')::numeric = 0))
$$;
create or replace function core.js_or(a jsonb, b jsonb) returns jsonb language sql immutable as $$ select case when core.js_truthy(a) then a else b end $$;   -- a || b
create or replace function core.js_nn(a jsonb, b jsonb) returns jsonb language sql immutable as $$ select case when a is null or jsonb_typeof(a) = 'null' then b else a end $$;   -- a ?? b
create or replace function core.fb_tidy(t text) returns text language sql immutable as $$ select regexp_replace(core.fb_trim(t), '\s+', ' ', 'g') $$;
create or replace function core.js_tidy(v jsonb) returns text language sql immutable as $$ select core.fb_tidy(core.js_str(v)) $$;          -- tidy(v)
create or replace function core.js_tidyn(v jsonb) returns jsonb language sql immutable as $$ select to_jsonb(nullif(core.js_tidy(v), '')) $$;   -- tidy(v) || null
create or replace function core.js_number(v jsonb) returns numeric language plpgsql immutable as $$   -- Number(v); null when NaN
declare s text;
begin
  if v is null then return null; end if;                                   -- undefined → NaN
  if jsonb_typeof(v) = 'null' then return 0; end if;
  if jsonb_typeof(v) = 'number' then return (v #>> '{}')::numeric; end if;
  if jsonb_typeof(v) = 'boolean' then return case when v = 'true'::jsonb then 1 else 0 end; end if;
  if jsonb_typeof(v) <> 'string' then return null; end if;
  s := core.fb_trim(v #>> '{}'); if s = '' then return 0; end if;
  if s ~ '^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$' then return s::numeric; end if;
  return null;
end $$;
create or replace function core.js_num(v jsonb) returns numeric language plpgsql immutable as $$     -- make-masters-data.js num(): digits and dots only, > 0
declare s text := regexp_replace(core.js_str(v), '[^0-9.]', '', 'g');
begin
  if s = '' then return null; end if;
  if s ~ '^(\d+\.?\d*|\.\d+)$' and s::numeric > 0 then return s::numeric; end if;
  return null;
end $$;
create or replace function core.js_dec(v jsonb) returns numeric language plpgsql immutable as $$     -- make-masters-data.js dec()
declare s text;
begin
  if core.fb_trim(core.js_str(v)) = '' then return null; end if;
  s := regexp_replace(core.js_str(v), '[^0-9.\-]', '', 'g');
  if s = '' then return 0; end if;
  if s ~ '^-?(\d+\.?\d*|\.\d+)$' then return s::numeric; end if;
  return null;
end $$;
create or replace function core.js_bool(v jsonb) returns boolean language sql immutable as $$     -- make-masters-data.js bool()
  select case when v = 'true'::jsonb or lower(core.fb_trim(core.js_str(v))) in ('yes', 'true', 'y', '1') then true
              when v = 'false'::jsonb or lower(core.fb_trim(core.js_str(v))) in ('no', 'false', 'n', '0') then false end
$$;
create or replace function core.js_txt(v jsonb) returns jsonb language sql immutable as $$         -- make-masters-data.js txt()
  select case when v is null or jsonb_typeof(v) = 'null' or v = '""'::jsonb then null
              when jsonb_typeof(v) in ('object', 'array') then to_jsonb(core.js_json(v)) else to_jsonb(core.js_tidy(v)) end
$$;
create or replace function core.js_iso(v jsonb) returns jsonb language sql immutable as $$         -- iso(): nothing → null; a number is milliseconds
  select case when not core.js_truthy(v) then null else core.fb_conv_sku(v, 'ts') end
$$;
-- the entries of a Firebase list in JavaScript's order (whole-number keys first, then the others as Firebase sends them)
create or replace function core.fb_ents_ord(v jsonb, only_obj boolean) returns table (k text, x jsonb, ord bigint) language sql immutable as $$
  select k, x, row_number() over (order by intk is null, intk, k collate "C") from (
    select key k, value x, case when key ~ '^(0|[1-9]\d{0,8})$' then key::bigint end intk from jsonb_each(case when jsonb_typeof(v) = 'object' then v else '{}'::jsonb end)) a
   where case when only_obj then jsonb_typeof(x) in ('object', 'array') else jsonb_typeof(x) <> 'null' end
  union all
  select (o - 1)::text, e, o from jsonb_array_elements(case when jsonb_typeof(v) = 'array' then v else '[]'::jsonb end) with ordinality t(e, o)
   where case when only_obj then jsonb_typeof(e) in ('object', 'array') else jsonb_typeof(e) <> 'null' end
$$;

-- ---------------------------------------------------------------------------------------------- CONTROL (make-control-sql.js)
create or replace function core.js_lc(v jsonb) returns jsonb language sql immutable as $$
  select case when v is null or jsonb_typeof(v) = 'null' or v = '""'::jsonb then null else to_jsonb(lower(core.fb_trim(core.js_str(v)))) end
$$;
create or replace function core.js_pick(o jsonb, keys text[]) returns jsonb language sql immutable as $$   -- pick(): the given keys that hold something ('' left out)
  select nullif((select coalesce(jsonb_object_agg(k, o -> k), '{}') from unnest(keys) k where o ? k and o -> k <> '""'::jsonb), '{}'::jsonb)
$$;
create or replace function core.syc_approval(reg text, k text, x jsonb) returns jsonb language plpgsql immutable as $$
declare r jsonb; st text; lg jsonb; ok boolean;
begin
  r := jsonb_build_object('legacy_key', reg || '/' || k, 'no', null, 'ref_room', null, 'ref_table', null, 'ref_legacy_key', null, 'order_no', null, 'sku_code', null,
    'snapshot', null, 'change', null, 'reason', null, 'old_status', null, 'asked_email', null, 'asked_at', null, 'answered_email', null, 'answered_at', null,
    'answer_note', null, 'withdrawn_email', null, 'withdrawn_at', null, 'result_legacy_key', null, 'result_no', null);
  if reg = 'pt_jwCorrReqs' then
    r := r || jsonb_build_object('kind', 'jw_correction', 'ref_room', 'erp', 'ref_table', 'job_work', 'ref_legacy_key', x -> 'rowId',
      'order_no', core.js_or(x -> 'orderNo', 'null'), 'sku_code', core.js_or(x -> 'sku', 'null'), 'snapshot', core.js_or(x -> 'snapshot', 'null'),
      'change', case when jsonb_typeof(x -> 'change') = 'object' then x -> 'change' else '{}'::jsonb end
                || case when core.js_truthy(x -> 'empName') then jsonb_build_object('empName', x -> 'empName') else '{}'::jsonb end,
      'reason', core.js_or(x -> 'why', 'null'), 'status', x -> 'status', 'old_status', x -> 'status', 'asked_email', core.js_lc(x -> 'by'), 'asked_at', core.js_iso(x -> 'at'),
      'answered_email', core.js_lc(x -> 'answeredBy'), 'answered_at', core.js_iso(x -> 'answeredAt'), 'answer_note', core.js_or(x -> 'answerNote', 'null'));
  elsif reg = 'pt_fgiCorrReqs' then
    r := r || jsonb_build_object('kind', 'fgi_correction', 'ref_room', 'erp', 'ref_table', 'stock_moves',
      'ref_legacy_key', case when core.js_truthy(x -> 'snapshot') then x -> 'snapshot' -> '_id' end,
      'order_no', core.js_or(case when core.js_truthy(x -> 'snapshot') then x -> 'snapshot' -> 'orderNo' end, 'null'), 'sku_code', core.js_or(x -> 'sku', 'null'),
      'snapshot', core.js_or(x -> 'snapshot', 'null'),
      'change', case when jsonb_typeof(x -> 'change') = 'object' then x -> 'change' else '{}'::jsonb end || coalesce(core.js_pick(x, array['kind', 'qty', 'txnType', 'note']), '{}'),
      'reason', core.js_or(x -> 'why', 'null'), 'status', case when x ->> 'status' = 'closed' then '"approved"'::jsonb else x -> 'status' end, 'old_status', x -> 'status',
      'asked_email', core.js_lc(x -> 'by'), 'asked_at', core.js_iso(x -> 'at'), 'answered_email', core.js_lc(x -> 'answeredBy'), 'answered_at', core.js_iso(x -> 'answeredAt'));
  elsif reg = 'pt_obDeleteReqs' then
    r := r || jsonb_build_object('kind', 'order_delete', 'ref_room', 'erp', 'ref_table', 'production_demand', 'ref_legacy_key', core.js_or(x -> 'id', to_jsonb(k)),
      'order_no', core.js_or(x -> 'orderNo', 'null'), 'sku_code', core.js_or(x -> 'sku', 'null'),
      'snapshot', core.js_pick(x, array['articleType', 'articleSubtype', 'color', 'size', 'orderDate', 'qty', 'src', 'from', 'work', 'workAtDelete']),
      'change', core.js_pick(x, array['obRowsRemoved', 'soQtyRemoved']), 'reason', core.js_or(x -> 'why', 'null'),
      'status', case when x ->> 'status' = 'deleted' then '"approved"'::jsonb else x -> 'status' end, 'old_status', x -> 'status',
      'asked_email', core.js_lc(x -> 'by'), 'asked_at', core.js_iso(x -> 'at'), 'answered_email', core.js_lc(x -> 'answeredBy'), 'answered_at', core.js_iso(x -> 'answeredAt'));
  elsif reg = 'pt_vendorOrderReqs' then
    st := x ->> 'status';
    r := r || jsonb_build_object('no', core.js_or(x -> 'reqNo', 'null'), 'kind', 'vendor_order_request', 'ref_room', 'core', 'ref_table', 'vendors', 'ref_legacy_key', core.js_or(x -> 'vendorCode', 'null'),
      'snapshot', core.js_pick(x, array['category', 'service', 'orderType', 'channel', 'vendorCode', 'vendorName', 'filler', 'notes', 'sentTo', 'sentToName', 'lines', 'log']),
      'reason', core.js_or(core.js_or(x -> 'why', x -> 'notes'), 'null'), 'status', x -> 'status', 'old_status', x -> 'status',
      'asked_email', core.js_lc(x -> 'requestedBy'), 'asked_at', core.js_iso(x -> 'requestedAt'),
      'answered_email', case st when 'approved' then core.js_lc(x -> 'approvedBy') when 'rejected' then core.js_lc(x -> 'rejectedBy') end,
      'answered_at', case st when 'approved' then core.js_iso(x -> 'approvedAt') when 'rejected' then core.js_iso(x -> 'rejectedAt') end,
      'answer_note', core.js_or(case when st = 'rejected' then x -> 'rejectReason' else x -> 'approveNote' end, 'null'),
      'withdrawn_email', case when st = 'withdrawn' then case when position('@' in core.js_str(core.js_or(x -> 'withdrawnBy', '""'))) > 0 then core.js_lc(x -> 'withdrawnBy') else core.js_or(x -> 'withdrawnBy', 'null') end end,
      'withdrawn_at', case when st = 'withdrawn' then core.js_iso(x -> 'withdrawnAt') end,
      'result_legacy_key', core.js_or(x -> 'vendorOrderId', 'null'), 'result_no', core.js_or(x -> 'vendorOrderNo', 'null'));
  elsif reg = 'pt_rfdDecisions' then
    -- the decision log, oldest first (JavaScript sorts by the text of "at")
    lg := case when jsonb_typeof(x -> 'log') = 'array' then (select coalesce(jsonb_agg(e order by core.js_str(e -> 'at') collate "C", o), '[]') from jsonb_array_elements(x -> 'log') with ordinality t(e, o) where core.js_truthy(e)) else '[]' end;
    r := r || jsonb_build_object('kind', 'rfd_decision', 'ref_room', 'erp', 'ref_table', 'vendor_orders', 'ref_legacy_key', core.js_or(x -> 'orderId', 'null'),
      'order_no', core.js_or(x -> 'orderNo', 'null'), 'sku_code', core.js_or(x -> 'sku', 'null'),
      'snapshot', core.js_pick(x, array['orderId', 'orderNo', 'vendorCode', 'vendorName', 'sku', 'size', 'fabric', 'unit', 'metres', 'pieces', 'sends', 'log']),
      'change', core.js_pick(x, array['want']), 'reason', core.js_or(x -> 'note', 'null'), 'status', x -> 'stage', 'old_status', x -> 'stage',
      'asked_at', core.js_or(core.js_iso(lg -> 0 -> 'at'), core.js_iso(x -> 'at')),
      'answered_email', core.js_lc(core.js_or(x -> 'by', lg -> (jsonb_array_length(lg) - 1) -> 'by')),
      'answered_at', core.js_iso(core.js_or(x -> 'at', lg -> (jsonb_array_length(lg) - 1) -> 'at')));
  elsif reg = 'pt_printerRates' then
    ok := lower(core.js_str(x -> 'status')) = 'approved';
    r := r || jsonb_build_object('kind', 'rate', 'ref_room', 'erp', 'ref_table', 'print_rates', 'ref_legacy_key', k,
      'snapshot', x - 'status' - 'approvedAt' - 'approvedBy', 'status', case when ok then 'approved' else 'pending' end, 'old_status', core.js_or(x -> 'status', 'null'),
      'asked_email', core.js_lc(x -> 'by'), 'asked_at', core.js_iso(core.js_or(x -> 'at', x -> 'addedAt')),
      'answered_email', case when ok then core.js_lc(x -> 'approvedBy') end, 'answered_at', case when ok then core.js_iso(x -> 'approvedAt') end);
  else return null; end if;
  r := r || jsonb_build_object('asked_at', coalesce(r -> 'asked_at', r -> 'answered_at', r -> 'withdrawn_at', '"2026-01-01T00:00:00.000Z"'::jsonb));
  if jsonb_typeof(r -> 'asked_at') = 'null' then r := r || jsonb_build_object('asked_at', coalesce(nullif(r -> 'answered_at', 'null'), nullif(r -> 'withdrawn_at', 'null'), '"2026-01-01T00:00:00.000Z"'::jsonb)); end if;
  if coalesce(r ->> 'status', '') not in ('pending', 'approved', 'rejected', 'withdrawn') then raise exception 'cannot place %/%: status %', reg, k, r ->> 'status'; end if;
  if r ->> 'status' in ('approved', 'rejected') and coalesce(r ->> 'answered_at', '') = '' then raise exception 'cannot place %/%: answered without a time', reg, k; end if;
  return r || jsonb_build_object('legacy_self_approved', coalesce(r ->> 'asked_email', '') <> '' and coalesce(r ->> 'answered_email', '') <> '' and r ->> 'asked_email' = r ->> 'answered_email');
end $$;
create or replace function core.syc_record(reg text, k text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare r jsonb;
begin
  if x is null or jsonb_typeof(x) not in ('object', 'array') then             -- gone from Firebase (or not a record): the approval stays, marked
    insert into core.sync_gone (tbl, legacy_key) select 'core.approvals', reg || '/' || k where exists (select 1 from core.approvals where legacy_key = reg || '/' || k) on conflict do nothing;
    return;
  end if;
  r := core.syc_approval(reg, k, x);
  perform core.load_approvals(jsonb_build_array(r));
  delete from core.sync_gone where tbl = 'core.approvals' and legacy_key = reg || '/' || k;     -- the list entry only
end $$;
create or replace function core.syc_settings(co jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare s jsonb := '[]';
begin
  co := coalesce(co, '{}');
  if core.js_pick(co, array['name', 'addr', 'email', 'gstin', 'pan', 'iec', 'jurisdiction']) is not null then
    s := s || jsonb_build_object('key', 'company', 'value', core.js_pick(co, array['name', 'addr', 'email', 'gstin', 'pan', 'iec', 'jurisdiction']), 'note', 'Company details on POs and challans (from the Greige Desk)', 'legacy_key', 'pt_gdTest/co#company'); end if;
  if core.js_nn(co -> 'poPrefix', 'null') <> 'null' then s := s || jsonb_build_object('key', 'greige_po.prefix', 'value', co -> 'poPrefix', 'note', 'Greige PO number prefix', 'legacy_key', 'pt_gdTest/co#greige_po.prefix'); end if;
  if core.js_nn(co -> 'poNext', 'null') <> 'null' then s := s || jsonb_build_object('key', 'greige_po.next', 'value', co -> 'poNext', 'note', 'Next greige PO number (becomes a database counter with purchasing)', 'legacy_key', 'pt_gdTest/co#greige_po.next'); end if;
  if core.js_nn(co -> 'rfdPrefix', 'null') <> 'null' then s := s || jsonb_build_object('key', 'rfd.prefix', 'value', co -> 'rfdPrefix', 'note', 'RFD number prefix', 'legacy_key', 'pt_gdTest/co#rfd.prefix'); end if;
  if jsonb_array_length(s) > 0 then perform core.load_settings(s); end if;
end $$;

-- ---------------------------------------------------------------------------------------------- MASTERS (make-masters-data.js + load-masters.js)
create or replace function core.sym_size(nm text) returns jsonb language plpgsql immutable as $$      -- sizeShape()
declare n text := lower(nm); nums numeric[]; w text;
begin
  nums := array(select (m[1])::numeric from regexp_matches(n, '(\d+(?:\.\d+)?)', 'g') m);
  w := case when n ~ '(round|circle|dia)' then 'round' when n ~ 'oval' then 'oval' when n ~ 'runner' then 'runner' when n ~ '(square|sq\M)' then 'square' when n ~ 'rect' then 'rectangle' end;
  if w = 'round' then return jsonb_build_object('shape', 'round', 'width_in', nullif(nums[1], 0), 'length_in', nullif(nums[1], 0)); end if;
  if coalesce(array_length(nums, 1), 0) >= 2 then return jsonb_build_object('shape', coalesce(w, case when nums[1] = nums[2] then 'square' else 'rectangle' end), 'width_in', nullif(nums[1], 0), 'length_in', nullif(nums[2], 0)); end if;
  if coalesce(array_length(nums, 1), 0) = 1 and w = 'square' then return jsonb_build_object('shape', 'square', 'width_in', nums[1], 'length_in', nums[1]); end if;
  return jsonb_build_object('shape', coalesce(w, 'other'), 'width_in', null, 'length_in', null);
end $$;
-- one list of pt_masters → rows, duplicates folded into the first (the switched-on one wins) — fromList()
create or replace function core.sym_list(v jsonb, lkey text, tbl text) returns jsonb language plpgsql immutable as $$
declare e record; nm text; kk text; r jsonb; was jsonb; m jsonb := '{}'; o text[] := '{}'; x jsonb;
begin
  for e in select * from core.fb_ents_ord(v, true) order by ord loop
    x := e.x;
    nm := core.js_tidy(core.js_or(core.js_or(x -> 'desc', x -> 'name'), x -> 'code'));
    if nm = '' then continue; end if;
    r := jsonb_build_object('legacy_key', 'pt_masters/' || lkey || '/' || e.k, 'code', core.js_tidyn(x -> 'code'), 'name', nm, 'active', not (x -> 'active' = 'false'::jsonb), 'firebase', x);
    if core.js_iso(x -> 'createdAt') is not null then r := r || jsonb_build_object('created_at', core.js_iso(x -> 'createdAt')); end if;
    r := r || case tbl when 'article_subtypes' then jsonb_build_object('_type', core.js_tidyn(x -> 'parentCode'))
                       when 'colours' then jsonb_build_object('no_print', x -> 'noPrint' = 'true'::jsonb)
                       when 'sizes' then core.sym_size(nm)
                       when 'pack_sizes' then jsonb_build_object('qty', nullif(round(coalesce(core.js_num(core.js_nn(x -> 'code', x -> 'desc')), 0)), 0))
                       else '{}'::jsonb end;
    kk := core.fb_key(nm);
    if m ? kk then
      was := m -> kk;
      if not (was ->> 'active')::boolean and (r ->> 'active')::boolean then m := m || jsonb_build_object(kk, was || r || jsonb_build_object('legacy_key', was ->> 'legacy_key')); end if;
      continue;
    end if;
    m := m || jsonb_build_object(kk, r); o := o || kk;
  end loop;
  return jsonb_build_object('m', m, 'o', to_jsonb(o));
end $$;
-- rows of a map in their order
create or replace function core.sym_rows(l jsonb) returns jsonb language sql immutable as $$
  select coalesce(jsonb_agg(l -> 'm' -> (k #>> '{}') order by o), '[]') from jsonb_array_elements(l -> 'o') with ordinality t(k, o)
$$;
-- every row of a table gets the same columns (helper fields left out), the empty ones filled as load-masters.js does
create or replace function core.sym_shape(p_rows jsonb) returns jsonb language plpgsql stable as $$
declare cols text[]; stamp text := to_char(current_date, 'YYYY-MM-DD') || 'T00:00:00Z'; d jsonb := '{"active": true, "added_from_skus": false, "no_print": false, "returnable": false, "is_auto": false, "kind": "other", "shape": "other", "status": "pending", "skus": 0}';
begin
  cols := array(select distinct k from jsonb_array_elements(p_rows) r, jsonb_object_keys(r) k where left(k, 1) <> '_');
  if not ('created_at' = any(cols)) then cols := array_append(cols, 'created_at'::text); end if;
  return (select coalesce(jsonb_agg((select jsonb_object_agg(c, case when r ? c and jsonb_typeof(r -> c) <> 'null' then r -> c when c = 'created_at' then to_jsonb(stamp) when d ? c then d -> c else 'null'::jsonb end) from unnest(cols) c) order by o), '[]')
            from jsonb_array_elements(p_rows) with ordinality t(r, o));
end $$;
create or replace function core.sym_load(tbl text, p_rows jsonb, keep_shape boolean default true) returns void language plpgsql security definer set search_path = core, public as $$
declare i int := 0; n int := jsonb_array_length(p_rows); body jsonb := case when keep_shape then core.sym_shape(p_rows) else p_rows end;
begin
  while i < n loop
    perform core.load_rows(tbl, (select jsonb_agg(e order by o) from jsonb_array_elements(body) with ordinality t(e, o) where o > i and o <= i + 200));
    i := i + 200;
  end loop;
end $$;

create or replace function core.sy_masters_rebuild() returns jsonb language plpgsql security definer set search_path = core, public as $$
#variable_conflict use_column
declare
  M jsonb := coalesce((select jsonb_object_agg(k, value) from core.sync_raw where reg = 'pt_masters' and value is not null), '{}');
  GD jsonb := coalesce((select jsonb_object_agg(k, value) from core.sync_raw where reg = 'pt_gdTest' and value is not null), '{}');
  CG jsonb := coalesce((select jsonb_object_agg(k, value) from core.sync_raw where reg = 'pt_colorGroups' and value is not null), '{}');
  types jsonb; subs jsonb; cols jsonb; sizes jsonb; packs jsonb; deps jsonb; emps jsonb;
  accs jsonb := '[]'; acck text[] := '{}';
  fab jsonb := '{}'; fo text[] := '{}';
  e record; x jsonb; nm text; kk text; gk text; rk text; f jsonb; g jsonb; r jsonb; base text; col text; sku text;
  grp jsonb := '{}'; go text[] := '{}'; mem jsonb := '[]'; link text; brand text; gname text;
  prules jsonb; recs jsonb; codes jsonb; vend jsonb := '[]'; sets jsonb := '[]';
  fb jsonb := '[]'; covered text[] := '{}'; notmoved jsonb;
  tid jsonb; cid jsonb; fid jsonb; grid jsonb; t0 timestamptz := clock_timestamp(); t text; mk record; tally record;
begin
  perform set_config('core.loading', 'on', true);
  types := core.sym_list(M -> 'articleType', 'articleType', 'article_types');
  subs  := core.sym_list(M -> 'articleSubtype', 'articleSubtype', 'article_subtypes');
  cols  := core.sym_list(M -> 'colour', 'colour', 'colours');
  sizes := core.sym_list(M -> 'size', 'size', 'sizes');
  packs := core.sym_list(M -> 'packOf', 'packOf', 'pack_sizes');
  deps  := core.sym_list(M -> 'department', 'department', 'departments');
  emps  := core.sym_list(M -> 'employmentType', 'employmentType', 'employment_types');
  -- accessories (name first; a second one with the same name is left out)
  for e in select * from core.fb_ents_ord(M -> 'accessories', true) order by ord loop
    x := e.x; nm := core.js_tidy(core.js_or(core.js_or(x -> 'name', x -> 'desc'), x -> 'code'));
    if nm = '' or core.fb_key(nm) = any(acck) then continue; end if;
    acck := acck || core.fb_key(nm);
    r := jsonb_build_object('legacy_key', 'pt_masters/accessories/' || e.k, 'code', core.js_tidyn(x -> 'code'), 'name', nm, 'unit', core.js_tidyn(x -> 'unit'), 'category', core.js_tidyn(x -> 'category'), 'firebase', x,
      'reorder_level', case when x -> 'reorderLevel' is null or x -> 'reorderLevel' in ('null'::jsonb, '""'::jsonb) then null when core.js_number(x -> 'reorderLevel') >= 0 then core.js_number(x -> 'reorderLevel') end,
      'returnable', x -> 'returnable' = 'true'::jsonb or x -> 'returnable' = '"yes"'::jsonb, 'is_auto', x -> 'auto' = 'true'::jsonb, 'active', not (x -> 'active' = 'false'::jsonb));
    if core.js_iso(x -> 'addedAt') is not null then r := r || jsonb_build_object('created_at', core.js_iso(x -> 'addedAt')); end if;
    accs := accs || jsonb_build_array(r);
  end loop;
  -- pack sizes that are not a number are left out
  packs := jsonb_build_object('m', packs -> 'm', 'o', (select coalesce(jsonb_agg(k order by o), '[]') from jsonb_array_elements(packs -> 'o') with ordinality t(k, o) where coalesce(packs -> 'm' -> (k #>> '{}') ->> 'qty', '') <> ''));

  -- FABRICS: the fabric list, greige→RFD pairs, the Greige Desk (it wins), printed fabrics
  for e in select * from core.fb_ents_ord(M -> 'fabricType', true) order by ord loop
    x := e.x; nm := core.js_tidy(core.js_nn(core.js_nn(x -> 'desc', x -> 'name'), x -> 'code'));
    if nm = '' then continue; end if;
    kk := core.fb_key(nm); if fab ? kk then continue; end if;
    f := jsonb_build_object('legacy_key', 'pt_masters/fabricType/' || e.k, 'name', nm, 'kind', case when x -> 'greige' = 'true'::jsonb then 'greige' else 'rfd' end, 'active', true)
      || jsonb_build_object('code', core.js_tidyn(x -> 'code'), 'width_in', core.js_num(x -> 'widthIn'), 'active', not (x -> 'active' = 'false'::jsonb), 'firebase', jsonb_build_object('fabricType', jsonb_build_object(e.k, x)));
    if core.js_iso(x -> 'createdAt') is not null then f := f || jsonb_build_object('created_at', core.js_iso(x -> 'createdAt')); end if;
    if jsonb_typeof(x -> 'greige') = 'string' and core.fb_trim(x ->> 'greige') <> '' then f := f || jsonb_build_object('_greige', core.js_tidy(x -> 'greige')); end if;
    fab := fab || jsonb_build_object(kk, f); fo := fo || kk;
  end loop;
  for e in select * from core.fb_ents_ord(M -> 'greigeRfd', true) order by ord loop
    x := e.x;
    if not core.js_truthy(x -> 'greige') and not core.js_truthy(x -> 'rfd') then continue; end if;
    gk := null; rk := null;
    if core.js_truthy(x -> 'greige') then gk := core.fb_key(core.js_str(x -> 'greige'));
      if gk <> '' and not fab ? gk then fab := fab || jsonb_build_object(gk, jsonb_build_object('legacy_key', 'pt_masters/greigeRfd/' || e.k || '#greige', 'name', core.js_tidy(x -> 'greige'), 'kind', 'greige', 'active', true)); fo := fo || gk; end if;
      if gk = '' then gk := null; end if; end if;
    if core.js_truthy(x -> 'rfd') then rk := core.fb_key(core.js_str(x -> 'rfd'));
      if rk <> '' and not fab ? rk then fab := fab || jsonb_build_object(rk, jsonb_build_object('legacy_key', 'pt_masters/greigeRfd/' || e.k, 'name', core.js_tidy(x -> 'rfd'), 'kind', 'rfd', 'active', true)); fo := fo || rk; end if;
      if rk = '' then rk := null; end if; end if;
    foreach t in array array[gk, rk] loop
      if t is not null then f := fab -> t;
        f := f || jsonb_build_object('firebase', coalesce(f -> 'firebase', '{}') || jsonb_build_object('greigeRfd', coalesce(f -> 'firebase' -> 'greigeRfd', '{}') || jsonb_build_object(e.k, x)));
        fab := fab || jsonb_build_object(t, f); end if;
    end loop;
    if gk is not null then g := fab -> gk;
      g := g || jsonb_build_object('kind', 'greige', 'width_in', core.js_or(g -> 'width_in', to_jsonb(core.js_num(x -> 'gw'))),
        'construction', core.js_or(core.js_or(g -> 'construction', core.js_tidyn(x -> 'constr')), 'null'), 'yarn_count', core.js_or(core.js_or(g -> 'yarn_count', core.js_tidyn(x -> 'count')), 'null'),
        'hsn', core.js_or(core.js_or(g -> 'hsn', core.js_tidyn(x -> 'hsn')), 'null'));
      fab := fab || jsonb_build_object(gk, g); end if;
    if rk is not null then r := fab -> rk;
      r := r || jsonb_build_object('width_in', core.js_or(r -> 'width_in', to_jsonb(core.js_num(x -> 'rw'))), 'gsm', core.js_or(r -> 'gsm', to_jsonb(core.js_num(x -> 'gsm'))),
        'hsn', core.js_or(core.js_or(r -> 'hsn', core.js_tidyn(x -> 'hsn')), 'null'));
      if core.js_number(x -> 'order') is not null then r := r || jsonb_build_object('sort_order', core.js_number(x -> 'order')); end if;
      if gk is not null then r := r || jsonb_build_object('_greige', fab -> gk -> 'name'); end if;
      fab := fab || jsonb_build_object(rk, r); end if;
  end loop;
  for e in select * from core.fb_ents_ord(GD -> 'mst', true) order by ord loop                    -- the Greige Desk wins
    x := e.x; gk := null; rk := null;
    if core.js_truthy(x -> 'greige') then gk := core.fb_key(core.js_str(x -> 'greige'));
      if gk <> '' and not fab ? gk then fab := fab || jsonb_build_object(gk, jsonb_build_object('legacy_key', 'pt_gdTest/mst/' || e.k || '#greige', 'name', core.js_tidy(x -> 'greige'), 'kind', 'greige', 'active', true)); fo := fo || gk; end if;
      if gk = '' then gk := null; end if; end if;
    if core.js_truthy(x -> 'rfd') then rk := core.fb_key(core.js_str(x -> 'rfd'));
      if rk <> '' and not fab ? rk then fab := fab || jsonb_build_object(rk, jsonb_build_object('legacy_key', 'pt_gdTest/mst/' || e.k, 'name', core.js_tidy(x -> 'rfd'), 'kind', 'rfd', 'active', true)); fo := fo || rk; end if;
      if rk = '' then rk := null; end if; end if;
    foreach t in array array[gk, rk] loop
      if t is not null then f := fab -> t;
        f := f || jsonb_build_object('firebase', coalesce(f -> 'firebase', '{}') || jsonb_build_object('greigeDesk', coalesce(f -> 'firebase' -> 'greigeDesk', '{}') || jsonb_build_object(e.k, x)));
        fab := fab || jsonb_build_object(t, f); end if;
    end loop;
    if gk is not null then g := fab -> gk;
      g := g || jsonb_build_object('kind', 'greige', 'title', core.js_or(core.js_or(core.js_tidyn(x -> 'title'), g -> 'title'), 'null'),
        'width_in', core.js_or(to_jsonb(core.js_num(x -> 'greigeWidth')), g -> 'width_in'),
        'epi', core.js_or(core.js_or(to_jsonb(core.js_num(x -> 'epi')), g -> 'epi'), 'null'), 'ppi', core.js_or(core.js_or(to_jsonb(core.js_num(x -> 'ppi')), g -> 'ppi'), 'null'),
        'warp', core.js_or(core.js_or(core.js_tidyn(x -> 'warp'), g -> 'warp'), 'null'), 'weft', core.js_or(core.js_or(core.js_tidyn(x -> 'weft'), g -> 'weft'), 'null'),
        'active', not (x -> 'active' = 'false'::jsonb));
      fab := fab || jsonb_build_object(gk, g); end if;
    if rk is not null then r := fab -> rk;
      r := r || jsonb_build_object('kind', 'rfd', 'width_in', core.js_or(to_jsonb(core.js_num(x -> 'rfdWidth')), r -> 'width_in'), 'active', not (x -> 'active' = 'false'::jsonb));
      if gk is not null then r := r || jsonb_build_object('_greige', fab -> gk -> 'name'); end if;
      fab := fab || jsonb_build_object(rk, r); end if;
  end loop;
  for e in select * from core.fb_ents_ord(M -> 'fabricSku', true) order by ord loop                -- printed fabrics, one per SKU
    x := e.x; base := core.js_tidy(x -> 'fabric'); col := core.js_tidy(x -> 'colour'); sku := core.js_tidy(core.js_or(x -> 'sku', to_jsonb(e.k)));
    nm := regexp_replace(coalesce(nullif(base, ''), 'Fabric') || ' – ' || coalesce(nullif(col, ''), '?') || ' (' || core.js_tidy(x -> 'brand') || ' ' || sku || ')', '\(\s+', '(');
    kk := core.fb_key(nm);
    if kk = '' then continue; end if;
    if not fab ? kk then fab := fab || jsonb_build_object(kk, jsonb_build_object('legacy_key', 'pt_masters/fabricSku/' || e.k, 'name', core.fb_tidy(nm), 'kind', 'printed', 'active', true)); fo := fo || kk; end if;
    f := fab -> kk;
    f := f || jsonb_build_object('code', core.js_tidyn(x -> 'code'), 'brand', case when x -> 'brand' in ('"RBP"'::jsonb, '"CPC"'::jsonb) then x -> 'brand' end,
      'print_direction', core.js_tidyn(x -> 'dir'), 'print_side', core.js_tidyn(x -> 'side'), 'sku_code', sku, 'image_url', core.js_tidyn(x -> 'imageUrl'), 'note', core.js_tidyn(x -> 'note'),
      'firebase', coalesce(f -> 'firebase', '{}') || jsonb_build_object('fabricSku', jsonb_build_object(e.k, x)), '_base', nullif(base, ''), '_colour', nullif(col, ''));
    if core.js_iso(x -> 'addedAt') is not null then f := f || jsonb_build_object('created_at', core.js_iso(x -> 'addedAt')); else f := f - 'created_at'; end if;
    fab := fab || jsonb_build_object(kk, f);
  end loop;
  -- a greige named on an RFD that is not itself a fabric yet
  foreach kk in array fo loop
    f := fab -> kk;
    if coalesce(f ->> '_greige', '') <> '' and not fab ? core.fb_key(f ->> '_greige') then
      fab := fab || jsonb_build_object(core.fb_key(f ->> '_greige'), jsonb_build_object('legacy_key', 'link/greige/' || core.fb_key(f ->> '_greige'), 'name', core.fb_tidy(f ->> '_greige'), 'kind', 'greige', 'active', true));
      fo := fo || core.fb_key(f ->> '_greige');
    end if;
  end loop;

