    (266, 'sizes', '55x75"'),
    (267, 'sizes', '2x4x4'),
    (268, 'sizes', '30*60 cm'),
    (269, 'sizes', '60*102 inches'),
    (270, 'sizes', '84'),
    (271, 'sizes', '112'),
    (272, 'sizes', '52Wx84L'),
    (273, 'sizes', '48x60'),
    (274, 'sizes', '32x32'),
    (275, 'sizes', '18*18 inch'),
    (276, 'sizes', '15x15 inch'),
    (277, 'sizes', 'Top/base: 36" × 75" in white cotton sheeting
Ruffle: Gathered coral stripe fabric
Ruffle drop: 18" from the top of the box spring to the floor
Ruffle: Three sides of each bed
Back/inner side: We can either use white cotton sheeting, or use the coral stripe sheeting fabric, which would not require a separate lining.'),
    (278, 'sizes', '17.7*14.6*6.7 inches'),
    (279, 'sizes', '90" Round'),
    (280, 'sizes', '110" Round'),
    (281, 'sizes', '120" Round'),
    (282, 'sizes', 'Round 90�'),
    (283, 'sizes', '82"'),
    (284, 'sizes', '62x91'),
    (285, 'sizes', '52x36'),
    (286, 'sizes', '68x110'),
    (287, 'sizes', '43x84'),
    (288, 'fabrics', 'Poplin'),
    (289, 'fabrics', 'Parcale'),
    (290, 'fabrics', 'INSA DRESS'),
    (291, 'fabrics', 'Sheeti g'),
    (292, 'fabrics', 'Sheetilg'),
    (293, 'fabrics', 'SheetiLg'),
    (294, 'fabrics', 'illow Coverriien 16'),
    (295, 'fabrics', 'illow Coverriien 26'),
    (296, 'fabrics', 'VnGriieenm 57'),
    (297, 'fabrics', 'neeiing 56'),
    (298, 'fabrics', 'LNLllow CoverBliiuee 26'),
    (299, 'fabrics', 'Dllow Coverneii Blueq 24'),
    (300, 'fabrics', 'leclothngbiee 16'),
    (301, 'fabrics', 'illow Coveriniien 16'),
    (302, 'fabrics', 'illow Coveriniien 26'),
    (303, 'fabrics', 'LnBliiuep 57'),
    (304, 'fabrics', 'nayiia 56'),
    (305, 'fabrics', 'ynnkiio 56'),
    (306, 'fabrics', 'vpshadeBliioom Bluei 11'),
    (307, 'fabrics', 'fhLated Lampshademoein Pinka 48'),
    (308, 'fabrics', 'fated Lampshadelueieo 412'),
    (309, 'fabrics', 'Sheetisg'),
    (310, 'fabrics', 'vvas Tote BagSteeiil Bluei 21'),
    (311, 'fabrics', 'LNLllow CoverBliiuee 16'),
    (312, 'fabrics', 'Lllow Covereeiil Bluei 24'),
    (313, 'fabrics', 'Yllow Covermoiin Pinka 14'),
    (314, 'fabrics', 'Yllow Covermoiin Pinka 24'),
    (315, 'fabrics', 'Dllow Coverneii Blueq 14'),
    (316, 'fabrics', 'leclothe biMoss Greenu 14'),
    (317, 'fabrics', 'lleclothcebi Rede 17'),
    (318, 'fabrics', 'Percale'),
    (319, 'fabrics', 'Napkin'),
    (320, 'pack_sizes', '16'),
    (321, 'pack_sizes', '24')) v (n, tbl, val) where tbl <> 'none' order by n loop
    nm := core.fb_tidy(mk.val); kk := core.fb_key(nm);
    r := jsonb_build_object('legacy_key', 'sku-value/' || mk.tbl || '/' || kk, 'name', nm, 'active', true, 'added_from_skus', true);
    if mk.tbl = 'article_types' and not (types -> 'm') ? kk then types := jsonb_build_object('m', (types -> 'm') || jsonb_build_object(kk, r), 'o', (types -> 'o') || to_jsonb(kk));
    elsif mk.tbl = 'article_subtypes' and not (subs -> 'm') ? kk then
      -- its type = the type most SKUs with this subtype have (the first one met wins a tie)
      select t2.at into tally from (
        select core.fb_tidy(s.firebase ->> 'articleType') at, count(*) n, min(s.ord) first_at from (
          select firebase, row_number() over (order by w, intk is null, intk, kk2 collate "C") ord from (
            select firebase, 1 w, split_part(legacy_key, '/', 2) kk2, case when split_part(legacy_key, '/', 2) ~ '^(0|[1-9]\d{0,8})$' then split_part(legacy_key, '/', 2)::bigint end intk
              from core.skus where legacy_key like 'pt\_masterDB/%' and not exists (select 1 from core.sync_gone g2 where g2.tbl = 'core.skus' and g2.legacy_key = core.skus.legacy_key)
            union all
            select firebase, 2, split_part(legacy_key, '/', 2), case when split_part(legacy_key, '/', 2) ~ '^(0|[1-9]\d{0,8})$' then split_part(legacy_key, '/', 2)::bigint end
              from core.custom_skus where legacy_key like 'pt\_customSkus/%' and not exists (select 1 from core.sync_gone g2 where g2.tbl = 'core.custom_skus' and g2.legacy_key = core.custom_skus.legacy_key)) z) s
         where core.fb_key(s.firebase ->> 'subtype') = kk and core.js_truthy(s.firebase -> 'articleType')
         group by 1 order by count(*) desc, min(s.ord) limit 1) t2;
      r := r || jsonb_build_object('_type', tally.at);
      subs := jsonb_build_object('m', (subs -> 'm') || jsonb_build_object(kk, r), 'o', (subs -> 'o') || to_jsonb(kk));
    elsif mk.tbl = 'colours' and not (cols -> 'm') ? kk then cols := jsonb_build_object('m', (cols -> 'm') || jsonb_build_object(kk, r), 'o', (cols -> 'o') || to_jsonb(kk));
    elsif mk.tbl = 'sizes' and not (sizes -> 'm') ? kk then sizes := jsonb_build_object('m', (sizes -> 'm') || jsonb_build_object(kk, r || core.sym_size(nm)), 'o', (sizes -> 'o') || to_jsonb(kk));
    elsif mk.tbl = 'fabrics' and not fab ? kk then fab := fab || jsonb_build_object(kk, r || jsonb_build_object('kind', 'other')); fo := fo || kk;
    elsif mk.tbl = 'pack_sizes' and coalesce(round(core.js_num(to_jsonb(nm))), 0) <> 0
          and not exists (select 1 from jsonb_array_elements(packs -> 'o') p where (packs -> 'm' -> (p #>> '{}') ->> 'qty')::numeric = round(core.js_num(to_jsonb(nm)))) then
      packs := jsonb_build_object('m', (packs -> 'm') || jsonb_build_object('mark:' || kk, r || jsonb_build_object('qty', round(core.js_num(to_jsonb(nm))))), 'o', (packs -> 'o') || to_jsonb('mark:' || kk));
    end if;
  end loop;
  -- a type named by a subtype that is not on the type list
  for r in select value from jsonb_array_elements(core.sym_rows(subs)) loop
    if coalesce(r ->> '_type', '') <> '' and not (types -> 'm') ? core.fb_key(r ->> '_type')
       and not exists (select 1 from jsonb_each(types -> 'm') t3 where core.fb_key(t3.value ->> 'code') = core.fb_key(r ->> '_type') and coalesce(t3.value ->> 'code', '') <> '') then
      kk := core.fb_key(r ->> '_type');
      types := jsonb_build_object('m', (types -> 'm') || jsonb_build_object(kk, jsonb_build_object('legacy_key', 'sku-value/article_types/' || kk, 'name', r ->> '_type', 'active', true, 'added_from_skus', true)), 'o', (types -> 'o') || to_jsonb(kk));
    end if;
  end loop;

  -- COLOUR GROUPS: "BRAND|Colour" → group name; "NR" = no group; other brands are not moved
  for e in select * from core.fb_ents_ord(CG -> 'map', false) order by ord loop
    link := e.k; brand := split_part(link, '|', 1); col := core.fb_tidy(substr(link, length(brand) + 2)); gname := core.js_tidy(e.x);
    if brand not in ('RBP', 'CPC') or gname = '' or upper(gname) = 'NR' then continue; end if;
    gk := brand || '|' || core.fb_key(gname);
    if not grp ? gk then grp := grp || jsonb_build_object(gk, jsonb_build_object('legacy_key', 'pt_colorGroups/' || brand || '/' || gname, 'brand', brand, 'name', gname, 'active', true)); go := go || gk; end if;
    grp := grp || jsonb_build_object(gk, (grp -> gk) || jsonb_build_object('firebase', coalesce(grp -> gk -> 'firebase', '{}') || jsonb_build_object(link, e.x)));
    if (cols -> 'm') ? core.fb_key(col) then mem := mem || jsonb_build_array(jsonb_build_object('brand', brand, '_colour', col, '_group', gk, '_link', link, '_fb', jsonb_build_object(link, e.x))); end if;
  end loop;

  -- the other four lists of pt_masters, as they are
  prules := (select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('created_at', core.js_iso(x -> 'at'))) || jsonb_build_object('legacy_key', 'pt_masters/printRule/' || k, 'article_type', core.js_txt(x -> 'articleType'),
    'subtype', core.js_txt(x -> 'subtype'), 'fabric', core.js_txt(x -> 'fabric'), 'print', case when jsonb_typeof(x -> 'print') = 'boolean' then x -> 'print' else to_jsonb(core.js_bool(x -> 'print')) end,
    'direction', core.js_txt(x -> 'dir'), 'issue_as', core.js_txt(x -> 'issueAs'), 'panels', core.js_txt(x -> 'panels'), 'note', core.js_txt(x -> 'note'), 'active', true, 'firebase', x) order by ord), '[]')
    from core.fb_ents_ord(M -> 'printRule', true));
  recs := (select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('created_at', core.js_iso(x -> 'uploadedAt'))) || jsonb_build_object('legacy_key', 'pt_masters/recipe/' || k, 'article_type', core.js_txt(x -> 'articleType'),
    'subtype', core.js_txt(x -> 'subtype'), 'size', core.js_txt(x -> 'size'), 'fabric', core.js_txt(x -> 'fabric'), 'consumption', core.js_dec(x -> 'consumption'), 'pack_of', core.js_txt(x -> 'packOf'),
    'cutting_required', core.js_bool(x -> 'cuttingRequired'), 'is_piping', core.js_bool(x -> 'isPiping'), 'piping_meters', core.js_dec(x -> 'pipingMeters'), 'is_ruffle', core.js_bool(x -> 'isRuffle'),
    'ruffle_fabric', core.js_txt(x -> 'ruffleFabric'), 'ruffle_meters', core.js_dec(x -> 'ruffleMeters'), 'is_zip', core.js_bool(x -> 'isZip'), 'zip_qty', core.js_dec(x -> 'zipQty'),
    'chain_length', core.js_txt(x -> 'chainLength'), 'active', true, 'firebase', x) order by ord), '[]') from core.fb_ents_ord(M -> 'recipe', true));
  codes := (select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('created_at', core.js_iso(x -> 'at'))) || jsonb_build_object('legacy_key', 'pt_masters/skuCode/' || k, 'article', core.js_txt(x -> 'article'),
    'subtype', core.js_txt(x -> 'subtype'), 'size', core.js_txt(x -> 'size'), 'base', core.js_txt(x -> 'base'), 'source', core.js_txt(x -> 'src'), 'active', true, 'firebase', x) order by ord), '[]')
    from core.fb_ents_ord(M -> 'skuCode', true));
  vend := (select coalesce(jsonb_agg(v order by w, ord), '[]') from (
    select 1 w, ord, jsonb_strip_nulls(jsonb_build_object('created_at', core.js_iso(x -> 'createdAt'))) || jsonb_build_object('legacy_key', 'pt_masters/vendor/' || k, 'source', 'vendor', 'code', core.js_txt(x -> 'code'),
      'name', core.js_tidy(core.js_or(core.js_or(x -> 'name', x -> 'desc'), x -> 'code')), 'category', core.js_txt(x -> 'category'), 'email', core.js_txt(x -> 'email'), 'phone', core.js_txt(x -> 'phone'),
      'contact', core.js_txt(x -> 'poc'), 'address', core.js_txt(x -> 'address'), 'state', core.js_txt(x -> 'state'), 'state_code', core.js_txt(x -> 'stateCode'), 'gstin', core.js_txt(x -> 'gstin'),
      'active', not (x -> 'active' = 'false'::jsonb), 'firebase', x) v from core.fb_ents_ord(M -> 'vendor', true)
    union all
    select 2, ord, jsonb_build_object('legacy_key', 'pt_masters/vendorBook/' || k, 'source', 'vendorBook', 'code', k, 'name', core.js_tidy(x -> 'name'), 'category', core.js_txt(x -> 'type'),
      'work', core.js_txt(x -> 'work'), 'phone', core.js_txt(x -> 'phone'), 'contact', core.js_txt(x -> 'contact'), 'address', core.js_txt(x -> 'address'), 'city', core.js_txt(x -> 'city'),
      'state', core.js_txt(x -> 'state'), 'pincode', core.js_txt(x -> 'pincode'), 'gstin', core.js_txt(x -> 'gstin'), 'pan', core.js_txt(x -> 'pan'), 'reg', core.js_txt(x -> 'reg'), 'tds', core.js_txt(x -> 'tds'),
      'note', core.js_txt(x -> 'note'), 'sort_order', case when jsonb_typeof(x -> 'order') = 'number' and (x ->> 'order')::numeric = trunc((x ->> 'order')::numeric) then x -> 'order' end, 'active', true, 'firebase', x)
      from core.fb_ents_ord(M -> 'vendorBook', true) where jsonb_typeof(x) = 'object'
    union all
    select 3, ord, jsonb_build_object('legacy_key', 'pt_gdTest/ven/' || k, 'source', 'greigeDesk', 'code', core.js_or(core.js_txt(x -> 'md'), to_jsonb(k)), 'name', core.js_tidy(x -> 'name'),
      'category', core.js_txt(x -> 'kind'), 'email', core.js_txt(x -> 'email'), 'phone', core.js_txt(x -> 'phone'), 'address', core.js_txt(x -> 'addr'), 'city', core.js_txt(x -> 'city'),
      'gstin', core.js_txt(x -> 'gstin'), 'pan', core.js_txt(x -> 'pan'), 'active', not (x -> 'active' = 'false'::jsonb), 'firebase', x)
      from core.fb_ents_ord(GD -> 'ven', true)) z where coalesce(v ->> 'name', '') <> '');
  -- the notes on the greige→RFD list and the vendor book: settings
  if core.js_truthy(M -> 'greigeRfd' -> '_source') then sets := sets || jsonb_build_object('key', 'masters.greige_rfd_source', 'value', to_jsonb(core.js_str(M -> 'greigeRfd' -> '_source')), 'note', 'pt_masters/greigeRfd/_source, as it was', 'legacy_key', 'pt_masters/greigeRfd/_source'); end if;
  if core.js_truthy(M -> 'greigeRfd' -> '_others') then sets := sets || jsonb_build_object('key', 'masters.greige_rfd_others', 'value', to_jsonb(core.js_json(M -> 'greigeRfd' -> '_others')), 'note', 'pt_masters/greigeRfd/_others, as it was', 'legacy_key', 'pt_masters/greigeRfd/_others'); end if;
  if core.js_truthy(M -> 'vendorBook' -> '_source') then sets := sets || jsonb_build_object('key', 'masters.vendor_book_source', 'value', to_jsonb(core.js_str(M -> 'vendorBook' -> '_source')), 'note', 'pt_masters/vendorBook/_source, as it was', 'legacy_key', 'pt_masters/vendorBook/_source'); end if;

  -- nothing left behind: every Masters record by its path, and those on no table kept aside as they are
  fb := (select coalesce(jsonb_agg(jsonb_build_object('path', p, 'rec', rec) order by w, o1, o2), '[]') from (
      select 1 w, l.ord o1, c.ord o2, 'pt_masters/' || l.k || '/' || c.k p, c.x rec from core.fb_ents_ord(M, false) l, core.fb_ents_ord(l.x, false) c where jsonb_typeof(l.x) in ('object', 'array')
      union all select 1, l.ord, 0, 'pt_masters/' || l.k, l.x from core.fb_ents_ord(M, false) l where jsonb_typeof(l.x) not in ('object', 'array')
      union all select 2, l.ord, c.ord, 'pt_colorGroups/map/' || c.k, c.x from core.fb_ents_ord(CG, false) l, core.fb_ents_ord(l.x, false) c where l.k = 'map' and jsonb_typeof(l.x) = 'object'
      union all select 2, l.ord, 0, 'pt_colorGroups/' || l.k, l.x from core.fb_ents_ord(CG, false) l where not (l.k = 'map' and jsonb_typeof(l.x) = 'object')
      union all select 3, case p2 when 'mst' then 1 else 2 end, c.ord, 'pt_gdTest/' || p2 || '/' || c.k, c.x from unnest(array['mst', 'ven']) p2, core.fb_ents_ord(GD -> p2, false) c) z);
  covered := array(
    select r ->> 'legacy_key' from jsonb_array_elements(core.sym_rows(types) || core.sym_rows(subs) || core.sym_rows(cols) || core.sym_rows(sizes) || core.sym_rows(packs) || core.sym_rows(deps)
                                                      || core.sym_rows(emps) || accs || prules || recs || codes || vend) r where r ? 'firebase' and jsonb_typeof(r -> 'firebase') <> 'null'
    union all select case src.key when 'fabricType' then 'pt_masters/fabricType/' when 'greigeRfd' then 'pt_masters/greigeRfd/' when 'greigeDesk' then 'pt_gdTest/mst/' else 'pt_masters/fabricSku/' end || rec.key
      from jsonb_each(fab) f2, jsonb_each(coalesce(f2.value -> 'firebase', '{}')) src, jsonb_each(src.value) rec
    union all select 'pt_colorGroups/map/' || (m2 ->> '_link') from jsonb_array_elements(mem) m2);
  notmoved := (select coalesce(jsonb_agg(e2 order by o), '[]') from jsonb_array_elements(fb) with ordinality t(e2, o) where not (e2 ->> 'path' = any(covered)));
  sets := sets || jsonb_build_object('key', 'masters.not_moved', 'value', notmoved, 'note', 'Firebase Masters records not on any list table, kept exactly as they were (path + record)', 'legacy_key', 'masters/not_moved');

  -- ---- into the tables, in the loader's order, with the loader's links
  perform core.sym_load('article_types', core.sym_rows(types));
  tid := (select jsonb_object_agg(k2, id) from (select core.fb_key(name) k2, max(id) id from core.article_types group by 1) z);      -- the last one wins (a JavaScript Map)
  perform core.sym_load('article_subtypes', (select coalesce(jsonb_agg(s || jsonb_build_object('article_type_id', case when coalesce(s ->> '_type', '') <> '' then coalesce(tid -> core.fb_key(s ->> '_type'),
      (select tid -> core.fb_key(t4 ->> 'name') from jsonb_array_elements(core.sym_rows(types)) with ordinality u4(t4, o4)          -- by code: the last type with it (a JavaScript Map)
        where coalesce(t4 ->> 'code', '') <> '' and core.fb_key(t4 ->> 'code') = core.fb_key(s ->> '_type') order by o4 desc limit 1)) end) order by o), '[]')
    from jsonb_array_elements(core.sym_rows(subs)) with ordinality t(s, o)));
  perform core.sym_load('colours', core.sym_rows(cols));
  perform core.sym_load('sizes', core.sym_rows(sizes));
  perform core.sym_load('pack_sizes', core.sym_rows(packs));
  perform core.sym_load('departments', core.sym_rows(deps));
  perform core.sym_load('employment_types', core.sym_rows(emps));
  perform core.sym_load('accessories', accs);
  perform core.sym_load('print_rules', prules);
  perform core.sym_load('recipes', recs);
  perform core.sym_load('sku_code_rules', codes);
  perform core.sym_load('vendors', vend);
  perform core.load_settings(sets);
  -- fabrics: the new ones first without links (they point at each other), then all of them with their links
  perform core.sym_load('fabrics', (select coalesce(jsonb_agg(fab -> k3 || jsonb_build_object('rfd_of_greige_id', null, 'base_fabric_id', null, 'colour_id', null) order by o), '[]')
    from unnest(fo) with ordinality t(k3, o) where not exists (select 1 from core.fabrics f3 where f3.legacy_key = fab -> k3 ->> 'legacy_key')));
  fid := (select jsonb_object_agg(k2, id) from (select core.fb_key(name) k2, max(id) id from core.fabrics group by 1) z);
  cid := (select jsonb_object_agg(k2, id) from (select core.fb_key(name) k2, max(id) id from core.colours group by 1) z);
  perform core.sym_load('fabrics', (select coalesce(jsonb_agg(f4 || jsonb_build_object(
      'rfd_of_greige_id', case when f4 ->> 'kind' = 'rfd' and coalesce(f4 ->> '_greige', '') <> '' then fid -> core.fb_key(f4 ->> '_greige') end,
      'base_fabric_id', case when f4 ->> 'kind' = 'printed' and coalesce(f4 ->> '_base', '') <> '' then fid -> core.fb_key(f4 ->> '_base') end,
      'colour_id', case when coalesce(f4 ->> '_colour', '') <> '' then cid -> core.fb_key(f4 ->> '_colour') end) order by o), '[]')
    from unnest(fo) with ordinality t(k3, o), lateral (select fab -> k3 f4) z));
  perform core.sym_load('colour_groups', (select coalesce(jsonb_agg(grp -> k3 order by o), '[]') from unnest(go) with ordinality t(k3, o)));
  grid := (select jsonb_object_agg(k2, id) from (select brand || '|' || core.fb_key(name) k2, max(id) id from core.colour_groups group by 1) z);
  perform core.sym_load('colour_group_members', (select coalesce(jsonb_agg(jsonb_build_object('brand', m3 ->> 'brand', 'colour_id', (cid ->> core.fb_key(m3 ->> '_colour'))::bigint,
      'colour_group_id', (grid ->> (m3 ->> '_group'))::bigint, 'legacy_key', 'pt_colorGroups/map/' || (m3 ->> 'brand') || '|' || (m3 ->> '_colour'), 'firebase', m3 -> '_fb') order by o), '[]')
    from (select m3, o, row_number() over (partition by m3 ->> 'brand', cid ->> core.fb_key(m3 ->> '_colour') order by o) rn
            from jsonb_array_elements(mem) with ordinality t(m3, o) where cid ? core.fb_key(m3 ->> '_colour')) z where rn = 1), false);

  -- rows Firebase no longer has: on the gone list (they stay); rows it has: off it
  foreach t in array array['article_types', 'article_subtypes', 'colours', 'sizes', 'pack_sizes', 'departments', 'employment_types', 'accessories', 'print_rules', 'recipes', 'sku_code_rules', 'vendors', 'fabrics', 'colour_groups', 'colour_group_members'] loop
    execute format($q$
      with built as (select r ->> 'legacy_key' k from jsonb_array_elements($1) r)
      , g as (insert into core.sync_gone (tbl, legacy_key) select 'core.%1$s', legacy_key from core.%1$I where legacy_key is not null and legacy_key not in (select k from built) on conflict do nothing returning 1)
      delete from core.sync_gone where tbl = 'core.%1$s' and legacy_key in (select k from built)$q$, t)
    using case t when 'article_types' then core.sym_rows(types) when 'article_subtypes' then core.sym_rows(subs) when 'colours' then core.sym_rows(cols) when 'sizes' then core.sym_rows(sizes)
                 when 'pack_sizes' then core.sym_rows(packs) when 'departments' then core.sym_rows(deps) when 'employment_types' then core.sym_rows(emps) when 'accessories' then accs
                 when 'print_rules' then prules when 'recipes' then recs when 'sku_code_rules' then codes when 'vendors' then vend
                 when 'fabrics' then (select coalesce(jsonb_agg(fab -> k3), '[]') from unnest(fo) k3)
                 when 'colour_groups' then (select coalesce(jsonb_agg(grp -> k3), '[]') from unnest(go) k3)
                 else (select coalesce(jsonb_agg(jsonb_build_object('legacy_key', 'pt_colorGroups/map/' || (m3 ->> 'brand') || '|' || (m3 ->> '_colour'))), '[]') from jsonb_array_elements(mem) m3) end;
  end loop;
  update core.settings set value = 'false'::jsonb where key = 'sync.masters_dirty';
  return jsonb_build_object('ms', round(extract(epoch from clock_timestamp() - t0) * 1000), 'fabrics', array_length(fo, 1));
end $$;

-- a change to one of these lists: into the working copy; Control rebuilds that request, Masters is marked to be built again
create or replace function core.sy_raw_apply(p text, val jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare segs text[] := string_to_array(trim(both '/' from p), '/'); v_reg text := segs[1]; v_k text; v_old jsonb; v_nxt jsonb; ch text[] := '{}'; e record;
begin
  if array_length(segs, 1) = 1 then                                  -- the whole list at once
    for e in select r.k as rk, r.value as rv from core.sync_raw r where r.reg = v_reg and r.value is not null loop
      if val is null or not (val ? e.rk) then update core.sync_raw r set value = null, at = now() where r.reg = v_reg and r.k = e.rk; ch := ch || e.rk; end if;
    end loop;
    if core.fb_norm(val) is not null and jsonb_typeof(core.fb_norm(val)) not in ('object', 'array') then   -- a list that is ONE value (a date, a number): kept under the key ''
      insert into core.sync_raw as r (reg, k, value) values (v_reg, '', core.fb_norm(val)) on conflict on constraint sync_raw_pkey do update set value = excluded.value, at = now();
      ch := ch || ''::text;
    end if;
    for e in select a.k as rk, a.x as rv from core.fb_ents_ord(core.fb_norm(val), false) a loop
      insert into core.sync_raw as r (reg, k, value) values (v_reg, e.rk, e.rv) on conflict on constraint sync_raw_pkey do update set value = excluded.value, at = now();
      ch := ch || e.rk;
    end loop;
  else
    v_k := segs[2];
    select r.value into v_old from core.sync_raw r where r.reg = v_reg and r.k = v_k;
    v_nxt := core.fb_set(v_old, segs[3:], val);
    insert into core.sync_raw as r (reg, k, value) values (v_reg, v_k, v_nxt) on conflict on constraint sync_raw_pkey do update set value = excluded.value, at = now();
    ch := array[v_k];
  end if;
  if v_reg in ('pt_jwCorrReqs', 'pt_fgiCorrReqs', 'pt_obDeleteReqs', 'pt_vendorOrderReqs', 'pt_rfdDecisions', 'pt_printerRates') then
    foreach v_k in array ch loop perform core.syc_record(v_reg, v_k, (select r.value from core.sync_raw r where r.reg = v_reg and r.k = v_k)); end loop;
  end if;
  if v_reg = 'pt_gdTest' and 'co' = any(ch) then perform core.syc_settings((select r.value from core.sync_raw r where r.reg = 'pt_gdTest' and r.k = 'co')); end if;
  if v_reg in ('pt_empList', 'pt_attend', 'pt_extraHours', 'pt_rateList', 'pt_teamSize', 'pt_contractorHeads', 'pt_ehFreezes', 'pt_payoutFreezes', 'pt_advances',
               'pt_loginDir', 'pt_vendorByEmail', 'pt_vendorMap', 'pt_printers', 'pt_perms') then
    insert into core.settings (key, value, note) values ('sync.hr_dirty', 'true', 'HR changed: built again after this round of the live mirror')
    on conflict (key) do update set value = 'true';
  end if;
  if v_reg = 'pt_blockNeed' then
    insert into core.settings (key, value, note) values ('sync.blocks_dirty', 'true', 'The printing-blocks list changed: built again after this round') on conflict (key) do update set value = 'true';
  end if;
  if v_reg = 'pt_amzListings' then
    insert into core.settings (key, value, note) values ('sync.listings_dirty', 'true', 'The Amazon listing report changed: built again after this round') on conflict (key) do update set value = 'true';
  end if;
  if v_reg in ('pt_masters', 'pt_colorGroups') or (v_reg = 'pt_gdTest' and (ch && array['mst', 'ven'])) then
    insert into core.settings (key, value, note) values ('sync.masters_dirty', 'true', 'Masters changed: built again after this round of the live mirror')
    on conflict (key) do update set value = 'true';
  end if;
end $$;


-- =====================================================================================================================
-- HR — the value rules of make-hr.js, the links of load-hr.js, the builder
-- =====================================================================================================================
create or replace function core.sy_hr_k(v jsonb) returns text language sql immutable as $$          -- K(): trim, one space, small letters
  select lower(core.fb_tidy(core.js_str(v)))
$$;
create or replace function core.sy_hr_t(v jsonb) returns jsonb language sql immutable as $$         -- t(): text as written
  select case when v is null or jsonb_typeof(v) = 'null' then null
              when jsonb_typeof(v) = 'string' then v
              when jsonb_typeof(v) in ('object', 'array') then to_jsonb(core.js_json(v))
              else to_jsonb(v #>> '{}') end
$$;
create or replace function core.sy_hr_n(v jsonb) returns jsonb language sql immutable as $$         -- n(): a number, or digits written as text
  select case when v is null or jsonb_typeof(v) = 'null' then null
              when jsonb_typeof(v) = 'number' then v
              when jsonb_typeof(v) = 'string' and core.fb_trim(v #>> '{}') ~ '^-?\d+(\.\d+)?$' then to_jsonb(core.fb_trim(v #>> '{}')::numeric) end
$$;
create or replace function core.sy_hr_ts(v jsonb) returns jsonb language plpgsql stable as $$       -- ts(): a time (a number = milliseconds)
declare s text;
begin
  if v is null or jsonb_typeof(v) = 'null' or v = '""'::jsonb then return null; end if;
  if jsonb_typeof(v) = 'number' then return to_jsonb(to_char(to_timestamp((v #>> '{}')::numeric / 1000) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')); end if;
  if jsonb_typeof(v) <> 'string' then return null; end if;
  s := v #>> '{}';
  if s !~ '^\s*\d{4}-\d{2}-\d{2}' then return null; end if;
  begin return to_jsonb(to_char((s::timestamptz) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')); exception when others then return null; end;
end $$;
create or replace function core.sy_hr_day(v jsonb) returns jsonb language plpgsql immutable as $$   -- day(): YYYY-MM-DD and a real day
declare s text := core.fb_trim(core.js_str(v));
begin
  if s !~ '^\d{4}-\d{2}-\d{2}$' then return null; end if;
  begin perform s::date; exception when others then return null; end;
  return to_jsonb(s);
end $$;
create or replace function core.sy_hr_b(v jsonb) returns jsonb language sql immutable as $$         -- b(): yes / no
  select case when v is null or jsonb_typeof(v) = 'null' then null
              when jsonb_typeof(v) = 'boolean' then v
              when lower(core.js_str(v)) in ('true', 'yes') then 'true'::jsonb
              when lower(core.js_str(v)) in ('false', 'no') then 'false'::jsonb end
$$;
-- one HR list from the working copy, in JavaScript's order (whole-number keys first)
create or replace function core.sy_hr_ents(p_reg text) returns table (k text, x jsonb, o bigint) language sql stable as $$
  select r.k, r.value, row_number() over (order by (r.k ~ '^(0|[1-9]\d{0,8})$') desc, case when r.k ~ '^(0|[1-9]\d{0,8})$' then r.k::bigint end, r.k collate "C")
    from core.sync_raw r where r.reg = p_reg and r.value is not null and jsonb_typeof(r.value) <> 'null'
$$;
-- D4: a name → its worker (two lines of that name: the department decides; a contractor's team: the contractor line)
create or replace function core.sy_hr_worker(p_name jsonb, p_dept jsonb, p_prefer text) returns jsonb language plpgsql stable as $$
declare nk text := core.sy_hr_k(p_name); c bigint[]; pk bigint[]; m int;
begin
  c := case when nk = '' then '{}'::bigint[] else array(select w.id from hr.workers w where core.sy_hr_k(to_jsonb(w.name)) = nk order by w.id) end;
  if coalesce(array_length(c, 1), 0) = 0 then return jsonb_build_object('id', null, 'mark', 'name not in worker list'); end if;
  pk := case when array_length(c, 1) = 1 then c
             else array(select w.id from hr.workers w where w.id = any(c) and core.sy_hr_k(to_jsonb(w.department)) = core.sy_hr_k(p_dept) order by w.id) end;
  if coalesce(array_length(pk, 1), 0) <> 1 and p_prefer = 'contractor' then
    pk := array(select w.id from hr.workers w where w.id = any(c) and coalesce(w.emp_type, '') ~* 'contractor' order by w.id);
  end if;
  m := coalesce(array_length(pk, 1), 0);
  return jsonb_build_object('id', pk[1], 'mark', case when m = 1 then null when m > 0 then 'name in 2 departments — first line used' else 'name in 2 departments, none matches' end);
end $$;
create or replace function core.sy_hr_first(p_tbl text, p_col text, p_v jsonb) returns bigint language plpgsql stable as $$   -- first(): lowest id whose name matches
declare r bigint;
begin
  if core.sy_hr_k(p_v) = '' then return null; end if;
  execute format('select id from %s where core.sy_hr_k(to_jsonb(%I)) = $1 order by id limit 1', p_tbl, p_col) into r using core.sy_hr_k(p_v);
  return r;
end $$;
create or replace function core.sy_hr_vendor(p_code jsonb, p_name jsonb) returns bigint language sql stable as $$       -- vendorOf(): ERP vendor code, then name
  select coalesce(
    (select v.id from core.vendors v where v.source = 'vendor' and core.sy_hr_k(p_code) <> '' and core.sy_hr_k(to_jsonb(v.code)) = core.sy_hr_k(p_code) order by v.id limit 1),
    (select v.id from core.vendors v where core.sy_hr_k(p_name) <> '' and core.sy_hr_k(to_jsonb(v.name)) = core.sy_hr_k(p_name) order by (v.source = 'vendor') desc, v.id limit 1))
$$;
-- load one HR table and its gone list (rows are never deleted)
create or replace function core.sy_hr_put(p_tbl text, p_rows jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare i int := 0; n int := jsonb_array_length(p_rows); body jsonb;
begin
  body := (select coalesce(jsonb_agg(r - '_name' - '_dept' order by o), '[]') from jsonb_array_elements(p_rows) with ordinality t(r, o));
  while i < n loop
    perform core.load_hr_rows(p_tbl, (select jsonb_agg(e order by o) from jsonb_array_elements(body) with ordinality t(e, o) where o > i and o <= i + 200));
    i := i + 200;
  end loop;
  execute format($q$
    with built as (select r ->> 'legacy_key' k from jsonb_array_elements($1) r)
    , g as (insert into core.sync_gone (tbl, legacy_key) select %L, legacy_key from %s where legacy_key is not null and legacy_key not in (select k from built) on conflict do nothing returning 1)
    delete from core.sync_gone where tbl = %L and legacy_key in (select k from built)$q$, p_tbl, p_tbl, p_tbl) using body;
end $$;

create or replace function core.sy_hr_rebuild() returns jsonb language plpgsql security definer set search_path = core, public as $$
declare t0 timestamptz := clock_timestamp(); v_w jsonb; v_x jsonb; n int := 0;          -- (not "x": a variable may not share a column's name)
begin
  perform set_config('core.loading', 'on', true);
  -- 1 · workers (pt_empList: [type, name, department, phone]) — lasting key type|name|department, #2 for an exact repeat
  with l as (select e.k, e.o, case when jsonb_typeof(e.x) = 'array' then e.x else '[]'::jsonb end x from core.sy_hr_ents('pt_empList') e),
  l2 as (select l.*, core.sy_hr_k(x -> 0) || '|' || core.sy_hr_k(x -> 1) || '|' || core.sy_hr_k(x -> 2) wk, core.sy_hr_k(x -> 1) nk, core.sy_hr_k(x -> 2) dk from l),
  l3 as (select l2.*, count(*) over (partition by wk) full_n, row_number() over (partition by wk order by o) seen,
                (select count(distinct b.dk) from l2 b where b.nk = l2.nk) dn from l2)
  select coalesce(jsonb_agg(jsonb_build_object(
           'legacy_key', 'pt_empList:' || kk, 'line_no', k::int, 'worker_key', kk,
           'emp_type', core.sy_hr_t(x -> 0), 'name', core.sy_hr_t(x -> 1), 'department', core.sy_hr_t(x -> 2), 'phone', core.sy_hr_t(x -> 3),
           'department_id', core.sy_hr_first('core.departments', 'name', core.sy_hr_t(x -> 2)),
           'employment_type_id', core.sy_hr_first('core.employment_types', 'name', core.sy_hr_t(x -> 0)),
           'mark', nullif(concat_ws(' · ', case when full_n > 1 then 'exact repeat' when dn > 1 then 'same name in 2 departments' end,
                                           case when core.fb_trim(core.js_str(x -> 1)) ~* '^(blank|)$' then 'placeholder name' end), ''),
           'firebase', x) order by o), '[]') into v_w
    from (select l3.*, case when seen > 1 then wk || '#' || seen else wk end kk from l3) z;
  perform core.sy_hr_put('hr.workers', v_w); n := n + jsonb_array_length(v_w);

  -- 2 · attendance and extra hours → worker (name; the department picks between two lines)
  select coalesce(jsonb_agg(r || jsonb_build_object('worker_id', w -> 'id', 'mark', w -> 'mark') order by o), '[]') into v_x from (
    select e.o, jsonb_build_object('legacy_key', 'pt_attend/' || e.k, 'fb_key', core.sy_hr_t(e.x -> '_key'), 'fb_id', core.sy_hr_t(e.x -> 'id'),
             'day', core.sy_hr_day(e.x -> 'day'), 'emp_name', core.sy_hr_t(e.x -> 'empName'), 'emp_type', core.sy_hr_t(e.x -> 'empType'), 'dept', core.sy_hr_t(e.x -> 'dept'),
             'status', core.sy_hr_t(e.x -> 'status'), 'in_at', core.sy_hr_t(e.x -> 'inAt'), 'out_at', core.sy_hr_t(e.x -> 'outAt'), 'remarks', core.sy_hr_t(e.x -> 'remarks'),
             'marked_at', core.sy_hr_ts(e.x -> 'markedAt'), 'marked_by', core.sy_hr_t(e.x -> 'markedBy'),
             'updated_at_fb', core.sy_hr_ts(e.x -> 'updatedAt'), 'updated_by_fb', core.sy_hr_t(e.x -> 'updatedBy'), 'firebase', e.x) r,
           core.sy_hr_worker(e.x -> 'empName', e.x -> 'dept', 'mark') w
      from core.sy_hr_ents('pt_attend') e) z;
  perform core.sy_hr_put('hr.attendance', v_x); n := n + jsonb_array_length(v_x);
  select coalesce(jsonb_agg(r || jsonb_build_object('worker_id', w -> 'id', 'mark', w -> 'mark') order by o), '[]') into v_x from (
    select e.o, jsonb_build_object('legacy_key', 'pt_extraHours/' || e.k, 'fb_id', core.sy_hr_t(e.x -> 'id'), 'day', core.sy_hr_day(e.x -> 'date'),
             'emp_name', core.sy_hr_t(e.x -> 'empName'), 'department', core.sy_hr_t(e.x -> 'department'),
             'from_time', core.sy_hr_t(e.x -> 'fromTime'), 'to_time', core.sy_hr_t(e.x -> 'toTime'), 'hours', core.sy_hr_n(e.x -> 'hours'),
             'status', core.sy_hr_t(e.x -> 'status'), 'remarks', core.sy_hr_t(e.x -> 'remarks'),
             'entered_at', core.sy_hr_ts(e.x -> 'enteredAt'), 'entered_by', core.sy_hr_t(e.x -> 'enteredBy'), 'entered_by_name', core.sy_hr_t(e.x -> 'enteredByName'),
             'authorized_at', core.sy_hr_ts(e.x -> 'authorizedAt'), 'authorized_by', core.sy_hr_t(e.x -> 'authorizedBy'), 'authorized_by_name', core.sy_hr_t(e.x -> 'authorizedByName'),
             'edited_at', core.sy_hr_ts(e.x -> 'editedAt'), 'edited_by', core.sy_hr_t(e.x -> 'editedBy'), 'firebase', e.x) r,
           core.sy_hr_worker(e.x -> 'empName', e.x -> 'department', 'mark') w
      from core.sy_hr_ents('pt_extraHours') e) z;
  perform core.sy_hr_put('hr.extra_hours', v_x); n := n + jsonb_array_length(v_x);

  -- 3 · team sizes (one row per change) and weekly headcounts → the contractor's worker line
  select coalesce(jsonb_agg(jsonb_build_object('legacy_key', 'pt_teamSize/' || e.k || '/sizes/' || s.k, 'team_key', e.k, 'name', core.sy_hr_t(e.x -> 'name'),
           'change_no', case when s.k ~ '^\d{1,9}$' then s.k::int end, 'from_day', core.sy_hr_day(s.x -> 'from'), 'headcount', core.sy_hr_n(s.x -> 'n'),
           'at_time', core.sy_hr_ts(s.x -> 'at'), 'by_email', core.sy_hr_t(s.x -> 'by'),
           'worker_id', core.sy_hr_worker(core.js_or(e.x -> 'name', to_jsonb(e.k)), null, 'contractor') -> 'id', 'firebase', s.x) order by e.o, s.ord), '[]') into v_x
    from core.sy_hr_ents('pt_teamSize') e, core.fb_ents_ord(e.x -> 'sizes', false) s;
  perform core.sy_hr_put('hr.team_sizes', v_x); n := n + jsonb_array_length(v_x);
  select coalesce(jsonb_agg(r || jsonb_build_object('worker_id', case when coalesce(nm, '') <> '' then core.sy_hr_worker(to_jsonb(nm), null, 'contractor') -> 'id' end) order by o1, o2), '[]') into v_x from (
    select e.o o1, s.ord o2, case when left(e.k, 1) = '_' then null else replace(s.k, '_', ' ') end nm,
           jsonb_build_object('legacy_key', 'pt_contractorHeads/' || e.k || '/' || s.k, 'week', e.k, 'contractor_key', s.k, 'heads', core.sy_hr_n(s.x), 'value', s.x, 'firebase', s.x) r
      from core.sy_hr_ents('pt_contractorHeads') e, core.fb_ents_ord(e.x, false) s where jsonb_typeof(e.x) in ('object', 'array')
    union all
    select e.o, 0, null, jsonb_build_object('legacy_key', 'pt_contractorHeads/' || e.k, 'week', e.k, 'contractor_key', null, 'heads', core.sy_hr_n(e.x), 'value', e.x, 'firebase', e.x)
      from core.sy_hr_ents('pt_contractorHeads') e where jsonb_typeof(e.x) not in ('object', 'array')) z;
  perform core.sy_hr_put('hr.contractor_heads', v_x); n := n + jsonb_array_length(v_x);

  -- 4 · piece rates (pt_rateList) — lasting key article|subtype|size|for, links to Masters, D6 mark
  with l as (select e.k, e.o, case when jsonb_typeof(e.x) = 'array' then e.x else '[]'::jsonb end x from core.sy_hr_ents('pt_rateList') e),
  l2 as (select l.*, core.sy_hr_k(x -> 0) || '|' || core.sy_hr_k(x -> 1) || '|' || core.sy_hr_k(x -> 2) || '|' || core.sy_hr_k(x -> 3) rk0 from l),
  l3 as (select l2.*, row_number() over (partition by rk0 order by o) seen from l2),
  r as (select o, x, case when seen > 1 then rk0 || '#' || seen else rk0 end rk, k from l3)
  select coalesce(jsonb_agg(jsonb_build_object('legacy_key', 'pt_rateList:' || r.rk, 'line_no', r.k::int, 'rate_key', r.rk,
           'article_type', core.sy_hr_t(x -> 0), 'subtype', core.sy_hr_t(x -> 1), 'size', core.sy_hr_t(x -> 2), 'applicable_for', core.sy_hr_t(x -> 3),
           'rate', core.sy_hr_n(x -> 4), 'commission', core.sy_hr_n(x -> 5),
           'commission_text', case when x -> 5 is null or jsonb_typeof(x -> 5) = 'null' then null else core.sy_hr_t(x -> 5) end,
           'article_type_id', a.id, 'subtype_id', coalesce(sp.id, case when sc.n = 1 then sc.id end),
           'size_id', core.sy_hr_first('core.sizes', 'name', core.sy_hr_t(x -> 2)),
           'mark', case when a.id is null then 'type looks wrong (not in Masters)' end, 'firebase', x) order by r.o), '[]') into v_x
    from r
    left join lateral (select core.sy_hr_first('core.article_types', 'name', core.sy_hr_t(r.x -> 0)) id) a on true
    left join lateral (select s.id from core.article_subtypes s where core.sy_hr_k(to_jsonb(s.name)) = core.sy_hr_k(core.sy_hr_t(r.x -> 1))
                          and s.article_type_id is not distinct from a.id order by s.id limit 1) sp on true
    left join lateral (select min(s.id) id, count(*) n from core.article_subtypes s where core.sy_hr_k(to_jsonb(s.name)) = core.sy_hr_k(core.sy_hr_t(r.x -> 1))) sc on true;
  perform core.sy_hr_put('hr.piece_rates', v_x); n := n + jsonb_array_length(v_x);

  -- 5 · the three lists that are empty today, kept whole
  select coalesce(jsonb_agg(jsonb_build_object('legacy_key', 'pt_ehFreezes/' || k, 'fb_key', k, 'value', x, 'firebase', x) order by o), '[]') into v_x from core.sy_hr_ents('pt_ehFreezes');
  perform core.sy_hr_put('hr.extra_hours_locks', v_x); n := n + jsonb_array_length(v_x);
  select coalesce(jsonb_agg(jsonb_build_object('legacy_key', 'pt_payoutFreezes/' || k, 'fb_key', k, 'value', x, 'firebase', x) order by o), '[]') into v_x from core.sy_hr_ents('pt_payoutFreezes');
  perform core.sy_hr_put('hr.payout_locks', v_x); n := n + jsonb_array_length(v_x);
  select coalesce(jsonb_agg(jsonb_build_object('legacy_key', 'pt_advances/' || k, 'fb_key', k, 'value', x, 'firebase', x) order by o), '[]') into v_x from core.sy_hr_ents('pt_advances');
  perform core.sy_hr_put('hr.advances', v_x); n := n + jsonb_array_length(v_x);

  -- 6 · logins, vendor lists, printers, the old rights copy
  select coalesce(jsonb_agg(jsonb_build_object('legacy_key', 'pt_loginDir/' || k, 'phone', k, 'email', core.sy_hr_t(x -> 'email'), 'name', core.sy_hr_t(x -> 'name'),
           'updated_at_fb', core.sy_hr_ts(x -> 'updatedAt'), 'person_id', core.sy_hr_first('core.people', 'email', core.sy_hr_t(x -> 'email')), 'firebase', x) order by o), '[]') into v_x
    from core.sy_hr_ents('pt_loginDir');
  perform core.sy_hr_put('core.login_directory', v_x); n := n + jsonb_array_length(v_x);
  select coalesce(jsonb_agg(jsonb_build_object('legacy_key', 'pt_vendorByEmail/' || k, 'email_key', k, 'email', lower(core.fb_trim(replace(k, ',', '.'))),
           'code', core.sy_hr_t(x -> 'code'), 'name', core.sy_hr_t(x -> 'name'), 'phone', core.sy_hr_t(x -> 'phone'),
           'vendor_id', core.sy_hr_vendor(core.sy_hr_t(x -> 'code'), core.sy_hr_t(x -> 'name')),
           'person_id', core.sy_hr_first('core.people', 'email', to_jsonb(lower(core.fb_trim(replace(k, ',', '.'))))), 'firebase', x) order by o), '[]') into v_x
    from core.sy_hr_ents('pt_vendorByEmail');
  perform core.sy_hr_put('core.vendor_logins', v_x); n := n + jsonb_array_length(v_x);
  select coalesce(jsonb_agg(jsonb_build_object('legacy_key', 'pt_vendorMap/' || k, 'code', k, 'email', core.sy_hr_t(x -> 'email'), 'name', core.sy_hr_t(x -> 'name'),
           'phone', core.sy_hr_t(x -> 'phone'), 'vendor_id', core.sy_hr_vendor(to_jsonb(k), core.sy_hr_t(x -> 'name')),
           'person_id', core.sy_hr_first('core.people', 'email', core.sy_hr_t(x -> 'email')), 'firebase', x) order by o), '[]') into v_x
    from core.sy_hr_ents('pt_vendorMap');
  perform core.sy_hr_put('core.vendor_map', v_x); n := n + jsonb_array_length(v_x);
  select coalesce(jsonb_agg(jsonb_build_object('legacy_key', 'pt_printers/' || k, 'fb_id', k, 'name', core.sy_hr_t(x -> 'name'), 'active', core.sy_hr_b(x -> 'active'),
           'tables', core.sy_hr_n(x -> 'tables'), 'pcs_month', core.sy_hr_n(x -> 'pcsMonth'), 'note', core.sy_hr_t(x -> 'note'),
           'at_time', core.sy_hr_ts(x -> 'at'), 'by_email', core.sy_hr_t(x -> 'by'), 'vendor_id', core.sy_hr_vendor(null, core.sy_hr_t(x -> 'name')), 'firebase', x) order by o), '[]') into v_x
    from core.sy_hr_ents('pt_printers');
  perform core.sy_hr_put('core.printers', v_x); n := n + jsonb_array_length(v_x);
  select coalesce(jsonb_agg(jsonb_build_object('legacy_key', 'pt_perms/' || k, 'email_key', k, 'email', lower(core.fb_trim(replace(k, ',', '.'))),
           'admin', core.sy_hr_b(x -> 'admin'), 'tabs', case when jsonb_typeof(x -> 't') = 'null' then null else x -> 't' end,
           'rights', case when jsonb_typeof(x -> 'r') = 'null' then null else x -> 'r' end, 'at_time', core.sy_hr_ts(x -> 'at'), 'by_text', core.sy_hr_t(x -> 'by'),
           'person_id', core.sy_hr_first('core.people', 'email', to_jsonb(lower(core.fb_trim(replace(k, ',', '.'))))), 'firebase', x) order by o), '[]') into v_x
    from core.sy_hr_ents('pt_perms');
  perform core.sy_hr_put('archive.perms_copy', v_x); n := n + jsonb_array_length(v_x);

  insert into core.settings (key, value, note) values ('sync.hr_backup', to_jsonb('live ' || to_char(now() at time zone 'UTC', 'YYYY-MM-DD HH24:MI') || ' UTC'), 'Which Firebase backup the HR copy is from')
  on conflict (key) do update set value = excluded.value;
  update core.settings set value = 'false'::jsonb where key = 'sync.hr_dirty';
  return jsonb_build_object('ms', round(extract(epoch from clock_timestamp() - t0) * 1000), 'rows', n);
end $$;


-- =====================================================================================================================
-- PRODUCTION — row builders from production-spec.json, the links of load-production.js, one handler per Firebase list
-- =====================================================================================================================
-- the value at a path, the way make-production.js flattens a record: a plain object (with something in it) becomes its
-- fields' columns, so a column for the object itself only gets a value that is not such an object (unless kept whole)
create or replace function core.syp_get(x jsonb, p text[], whole boolean default false) returns jsonb language plpgsql immutable as $$
declare v jsonb := x; i int; n int := coalesce(array_length(p, 1), 0);
begin
  for i in 1 .. n loop
    if v is null or jsonb_typeof(v) <> 'object' or (i > 1 and v = '{}'::jsonb) then return null; end if;
    v := v -> p[i];
  end loop;
  if v is not null and jsonb_typeof(v) = 'object' and v <> '{}'::jsonb and not whole then return null; end if;
  return v;
end $$;
