-- links (= load-production.js)
create or replace function core.syp_sku(code text) returns jsonb language sql stable security definer set search_path = core, public as $$
  select case when core.fb_u(code) = '' then jsonb_build_object('sku_id', null, 'custom_sku_id', null)
    else jsonb_build_object('sku_id', (select id from core.skus where core.fb_u(sku) = core.fb_u(code) order by id limit 1),
                            'custom_sku_id', (select id from core.custom_skus where core.fb_u(sku) = core.fb_u(code) order by id limit 1)) end
$$;
create or replace function core.syp_line(o text, s text) returns bigint language sql stable security definer set search_path = core, public as $$
  select id from production.order_book where core.fb_u(order_no) = core.fb_u(o) and core.fb_u(sku) = core.fb_u(s) order by id limit 1
$$;
create or replace function core.syp_line_key(k text) returns bigint language sql stable as $$
  select core.syp_line(split_part(coalesce(k, ''), '__', 1), substr(coalesce(k, ''), length(split_part(coalesce(k, ''), '__', 1)) + 3))
$$;
create or replace function core.syp_fabric(nm text) returns bigint language sql stable security definer set search_path = core, public as $$
  select case when core.fb_key(nm) = '' then null else (select id from core.fabrics where core.fb_key(name) = core.fb_key(nm) order by id limit 1) end
$$;
create or replace function core.syp_vendor(code text, nm text) returns bigint language sql stable security definer set search_path = core, public as $$
  select coalesce(
    case when core.fb_u(code) = '' then null else (select id from core.vendors where source = 'vendor' and core.fb_u(code) = core.fb_u(syp_vendor.code) order by id limit 1) end,
    case when core.fb_key(nm) = '' then null else (select id from core.vendors where core.fb_key(name) = core.fb_key(nm) order by (source = 'vendor') desc, id limit 1) end)
$$;
create or replace function core.syp_so(o text) returns bigint language sql stable security definer set search_path = core, public as $$
  select case when core.fb_u(o) = '' then null else (select id from sales.orders where core.fb_u(order_no) = core.fb_u(o) order by id limit 1) end
$$;
-- the HR rule: the name; two lines of that name → the department, then the type, then a contractor line decides
create or replace function core.syp_worker(p_name jsonb, p_label text, p_dept text, p_type text, p_contractor boolean) returns jsonb language plpgsql stable security definer set search_path = core, public as $$
declare k text := core.fb_key(core.js_str(p_name)); c bigint[]; pk bigint[]; nm text := core.fb_trim(core.js_str(p_name)); use_id bigint;
begin
  if k = '' then return jsonb_build_object('id', null, 'note', null); end if;
  c := array(select w.id from hr.workers w where core.fb_key(w.name) = k and core.fb_key(w.name) <> '' order by w.id);
  if coalesce(array_length(c, 1), 0) = 0 then return jsonb_build_object('id', null, 'note', p_label || ' "' || nm || '" not in worker list'); end if;
  pk := case when array_length(c, 1) = 1 then c else array(select w.id from hr.workers w where w.id = any(c) and coalesce(p_dept, '') <> '' and core.fb_key(w.department) = core.fb_key(p_dept) order by w.id) end;
  if coalesce(array_length(pk, 1), 0) <> 1 then pk := array(select w.id from hr.workers w where w.id = any(c) and coalesce(p_type, '') <> '' and core.fb_key(w.emp_type) = core.fb_key(p_type) order by w.id); end if;
  if coalesce(array_length(pk, 1), 0) <> 1 and p_contractor then pk := array(select w.id from hr.workers w where w.id = any(c) and coalesce(w.emp_type, '') ~* 'contractor' order by w.id); end if;
  use_id := case when coalesce(array_length(pk, 1), 0) > 0 then pk[1] else c[1] end;
  return jsonb_build_object('id', use_id, 'note', case when coalesce(array_length(pk, 1), 0) = 1 then null else p_label || ' "' || nm || '" is in ' || array_length(c, 1) || ' lines — first line used' end);
end $$;
create or replace function core.syp_note(a text, b text) returns text language sql immutable as $$ select case when b is null then a when a is null then b else a || ' · ' || b end $$;
-- every row goes in through the Production (or Leftovers) load door; answers its id; a row written again is off the gone list
create or replace function core.syp_put(p_table text, p_row jsonb) returns bigint language plpgsql security definer set search_path = core, public as $$
declare rid bigint;
begin
  if split_part(p_table, '.', 1) = 'production' then perform core.load_production_rows(p_table, jsonb_build_array(p_row));
  else perform core.load_leftover_rows(p_table, jsonb_build_array(p_row)); end if;
  execute format('select id from %s where legacy_key = $1', p_table) into rid using p_row ->> 'legacy_key';
  delete from core.sync_gone where tbl = p_table and legacy_key = p_row ->> 'legacy_key';
  return rid;
end $$;
create or replace function core.syp_live(p_table text, p_col text, p_val text) returns bigint language plpgsql stable security definer set search_path = core, public as $$
declare rid bigint;          -- the id of a row whose Firebase record is still there (last one wins, as a Map in the loader)
begin
  if coalesce(p_val, '') = '' then return null; end if;
  execute format('select t.id from %s t where t.%I = $1 and not exists (select 1 from core.sync_gone g where g.tbl = %L and g.legacy_key = t.legacy_key) order by t.id desc limit 1', p_table, p_col, p_table) into rid using p_val;
  return rid;
end $$;

-- one Firebase record → its rows
create or replace function core.syp_record(reg text, lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare r jsonb; pid bigint; cid bigint; c record; d record; keep text[] := '{}'; ck text; dk text; k text; w jsonb; w2 jsonb; nt text; kind text; g text;
begin
  k := split_part(lk, '/', array_length(string_to_array(lk, '/'), 1));
  case reg
  when 'pt_ppc' then
    r := core.syp_ppc_plans(x, lk, jsonb_build_object('line_key', k), x) || core.syp_sku(x ->> 'sku')
      || jsonb_build_object('order_book_id', core.syp_line_key(k), 'fabric_id', core.syp_fabric(x #>> '{fabric,name}'),
           'printer_vendor_id', case when jsonb_typeof(x -> 'printer') = 'object' then core.syp_vendor(x #>> '{printer,code}', x #>> '{printer,name}') end,
           'ruffle_vendor_id', case when jsonb_typeof(x -> 'rufflePrinter') = 'object' then core.syp_vendor(x #>> '{rufflePrinter,code}', x #>> '{rufflePrinter,name}') end,
           'out_vendor_id', case when core.fb_trim(core.js_str(x -> 'outVendor')) <> '' then core.syp_vendor(null, core.js_str(x -> 'outVendor')) end);
    pid := core.syp_put('production.ppc_plans', r);
    foreach kind in array array['extra', 'acc'] loop
      for c in select * from core.fb_objs(x -> kind) loop
        ck := lk || '/' || kind || '/' || c.k; keep := keep || ck;
        perform core.syp_put('production.ppc_plan_items', core.syp_ppc_plan_items(c.x, ck, jsonb_build_object('item_kind', case when kind = 'acc' then 'accessory' else 'extra' end, 'item_no', core.fb_num(c.k), 'ppc_plan_id', pid), c.x)
          || jsonb_build_object('accessory_id', case when kind = 'acc' then coalesce(
               (select id from core.accessories where core.fb_u(c.x ->> 'code') <> '' and core.fb_u(code) = core.fb_u(c.x ->> 'code') order by id limit 1),
               (select id from core.accessories where core.fb_key(c.x ->> 'what') <> '' and core.fb_key(name) = core.fb_key(c.x ->> 'what') order by id limit 1)) end));
      end loop;
    end loop;
    perform core.sy_gone_under('production.ppc_plan_items', lk || '/', keep);
  when 'pt_flowDemand' then
    r := core.syp_fabric_ready(x, lk, jsonb_build_object('line_key', k), x) || core.syp_sku(substr(k, length(split_part(k, '__', 1)) + 3))
      || jsonb_build_object('order_book_id', core.syp_line_key(k), 'cloth_challan_id', core.syp_live('production.cloth_challans', 'doc_no', x #>> '{fabricReady,challan}'),
           'vendor_id', core.syp_vendor(null, x #>> '{fabricReady,vendor}'), 'fabric_id', core.syp_fabric(x #>> '{fabricReady,what}'));
    perform core.syp_put('production.fabric_ready', r);
  when 'pt_flowChallans' then
    r := core.syp_cloth_challans(x, lk, '{}', x) || jsonb_build_object('vendor_id', case when jsonb_typeof(x -> 'vendor') = 'object' then core.syp_vendor(x #>> '{vendor,code}', x #>> '{vendor,name}') end,
           'sales_order_id', core.syp_so(x ->> 'orderNo'));
    pid := core.syp_put('production.cloth_challans', r);
    for c in select * from core.fb_objs(x -> 'lines') loop
      ck := lk || '/lines/' || c.k; keep := keep || ck;
      cid := core.syp_put('production.cloth_challan_lines', core.syp_cloth_challan_lines(c.x, ck, jsonb_build_object('line_no', core.fb_num(c.k), 'cloth_challan_id', pid), c.x) || core.syp_sku(c.x ->> 'sku')
        || jsonb_build_object('order_book_id', case when coalesce(c.x ->> 'key', '') <> '' then core.syp_line_key(c.x ->> 'key') else core.syp_line(c.x ->> 'orderNo', c.x ->> 'sku') end, 'fabric_id', core.syp_fabric(c.x ->> 'fabric')));
      for d in select * from core.fb_objs(c.x -> 'extras') loop
        dk := ck || '/extras/' || d.k; keep := keep || dk;
        perform core.syp_put('production.cloth_challan_line_extras', core.syp_cloth_challan_line_extras(d.x, dk, jsonb_build_object('extra_no', core.fb_num(d.k), 'cloth_challan_line_id', cid), d.x));
      end loop;
    end loop;
    for c in select * from core.fb_objs(x -> 'receipts') loop
      ck := lk || '/receipts/' || c.k; keep := keep || ck;
      cid := core.syp_put('production.cloth_challan_receipts', core.syp_cloth_challan_receipts(c.x, ck, jsonb_build_object('receipt_key', c.k, 'cloth_challan_id', pid), c.x));
      for d in select * from core.fb_ents(c.x -> 'items', true) loop
        dk := ck || '/items/' || d.k; keep := keep || dk;
        perform core.syp_put('production.cloth_challan_receipt_items', core.syp_cloth_challan_receipt_items(case when jsonb_typeof(d.x) = 'object' then d.x else jsonb_build_object('qty', d.x) end, dk,
          jsonb_build_object('item_key', d.k, 'cloth_challan_receipt_id', cid, 'order_book_id', core.syp_line_key(d.k)), d.x));
      end loop;
    end loop;
    for c in select * from core.fb_objs(x -> 'moved') loop
      ck := lk || '/moved/' || c.k; keep := keep || ck;
      perform core.syp_put('production.cloth_challan_moves', core.syp_cloth_challan_moves(c.x, ck, jsonb_build_object('move_key', c.k, 'cloth_challan_id', pid), c.x));
    end loop;
    foreach g in array array['production.cloth_challan_lines', 'production.cloth_challan_line_extras', 'production.cloth_challan_receipts', 'production.cloth_challan_receipt_items', 'production.cloth_challan_moves'] loop
      perform core.sy_gone_under(g, lk || '/', keep);
    end loop;
  when 'pt_flowPrintOrders' then
    r := core.syp_print_orders(x, lk, '{}', x) || jsonb_build_object('vendor_id', case when jsonb_typeof(x -> 'printer') = 'object' then core.syp_vendor(x #>> '{printer,code}', x #>> '{printer,name}') end,
           'sales_order_id', core.syp_so(x ->> 'orderNo'),
           'vendor_order_id', (select id from production.vendor_orders where coalesce(x #>> '{vo,cut,id}', '') <> '' and split_part(legacy_key, '/', 3) = x #>> '{vo,cut,id}' order by id desc limit 1),
           'running_vendor_order_id', (select id from production.vendor_orders where coalesce(x #>> '{vo,running,id}', '') <> '' and split_part(legacy_key, '/', 3) = x #>> '{vo,running,id}' order by id desc limit 1));
    pid := core.syp_put('production.print_orders', r);
    for c in select * from core.fb_objs(x -> 'items') loop
      ck := lk || '/items/' || c.k; keep := keep || ck;
      cid := core.syp_put('production.print_order_lines', core.syp_print_order_lines(c.x, ck, jsonb_build_object('item_key', c.k, 'print_order_id', pid, 'order_book_id', core.syp_line_key(c.k)), c.x) || core.syp_sku(c.x ->> 'sku'));
      for d in select * from core.fb_objs(c.x -> 'extras') loop
        dk := ck || '/extras/' || d.k; keep := keep || dk;
        perform core.syp_put('production.print_order_line_extras', core.syp_print_order_line_extras(d.x, dk, jsonb_build_object('extra_no', core.fb_num(d.k), 'print_order_line_id', cid), d.x));
      end loop;
    end loop;
    perform core.sy_gone_under('production.print_order_lines', lk || '/', keep);
    perform core.sy_gone_under('production.print_order_line_extras', lk || '/', keep);
  when 'pt_cuttingData' then
    perform core.syp_put('production.cutting', core.syp_cutting(x, lk, '{}', x) || core.syp_sku(x ->> 'sku')
      || jsonb_build_object('order_book_id', core.syp_line(x ->> 'orderNo', x ->> 'sku'), 'fabric_id', core.syp_fabric(core.js_str(x -> 'fabricWidth'))));
  when 'pt_baseData', 'pt_baseDone' then
    if reg = 'pt_baseDone' and left(split_part(lk, '/', 2), 1) = '_' then          -- the job-work helpers (_auto, _ver): settings, as they are
      g := 'production.job_work' || split_part(lk, '/', 2);
      update core.settings s set value = core.fb_set(s.value, array[split_part(lk, '/', 3)], x) where s.key = g;
      return;
    end if;
    w := core.syp_worker(x -> 'empName', 'worker', null, x ->> 'empType', coalesce(x ->> 'empType', '') ~* 'contractor');
    r := core.syp_job_work(x, lk, jsonb_build_object('place', case when reg = 'pt_baseData' then 'open' else 'completed' end, 'day_group', case when reg = 'pt_baseDone' then split_part(lk, '/', 2) end), x)
      || core.syp_sku(x ->> 'sku') || jsonb_build_object('worker_id', w -> 'id', 'link_note', w -> 'note', 'order_book_id', core.syp_line(x ->> 'orderNo', x ->> 'sku'));
    pid := core.syp_put('production.job_work', r);
    for c in select * from core.fb_objs(x -> 'receipts') loop
      ck := lk || '/receipts/' || c.k; keep := keep || ck;
      perform core.syp_put('production.job_work_receipts', core.syp_job_work_receipts(c.x, ck, jsonb_build_object('receipt_no', core.fb_num(c.k), 'job_work_id', pid), c.x));
    end loop;
    perform core.sy_gone_under('production.job_work_receipts', lk || '/', keep);
  when 'pt_qcChecks' then
    nt := case when coalesce(x ->> 'baseId', '') <> '' and core.syp_live('production.job_work', 'fb_id', x ->> 'baseId') is null then 'job ' || (x ->> 'baseId') || ' not in Firebase any more' end;
    w := core.syp_worker(x -> 'karigar', 'karigar', null, null, true); w2 := core.syp_worker(x -> 'checkedBy', 'checked by', 'Quality Control', null, false);
    perform core.syp_put('production.qc_checks', core.syp_qc_checks(x, lk, '{}', x) || core.syp_sku(x ->> 'sku')
      || jsonb_build_object('job_work_id', case when coalesce(x ->> 'baseId', '') <> '' then core.syp_live('production.job_work', 'fb_id', x ->> 'baseId') end,
           'karigar_worker_id', w -> 'id', 'checked_by_worker_id', w2 -> 'id', 'order_book_id', core.syp_line(x ->> 'orderNo', x ->> 'sku'),
           'link_note', core.syp_note(core.syp_note(nt, w ->> 'note'), w2 ->> 'note')));
  when 'pt_qcIssuance' then
    w := core.syp_worker(x -> 'employee', 'worker', null, x ->> 'employmentType', true);
    perform core.syp_put('production.qc_rework_out', core.syp_qc_rework_out(x, lk, '{}', x) || core.syp_sku(x ->> 'sku') || jsonb_build_object('worker_id', w -> 'id', 'link_note', w -> 'note'));
  when 'pt_qcReturns' then
    w := core.syp_worker(x -> 'employee', 'worker', null, x ->> 'employmentType', true); w2 := core.syp_worker(x -> 'receivedBy', 'received by', 'Quality Control', null, false);
    perform core.syp_put('production.qc_rework_back', core.syp_qc_rework_back(x, lk, '{}', x) || core.syp_sku(x ->> 'sku')
      || jsonb_build_object('qc_rework_out_id', core.syp_live('production.qc_rework_out', 'fb_id', coalesce(x ->> 'issuanceId', '')), 'worker_id', w -> 'id', 'received_by_worker_id', w2 -> 'id',
           'link_note', core.syp_note(w ->> 'note', w2 ->> 'note')));
  when 'pt_flowFgSend' then
    perform core.syp_put('production.fg_sends', core.syp_fg_sends(x, lk, '{}', x) || core.syp_sku(x ->> 'sku')
      || jsonb_build_object('order_book_id', core.syp_line(x ->> 'orderNo', x ->> 'sku'),
           'fg_ledger_id', case when coalesce(x ->> 'fgId', '') <> '' then (select id from stock.fg_ledger where entry_id = x ->> 'fgId' or split_part(legacy_key, '/', 2) = x ->> 'fgId' order by id limit 1) end));
  when 'pt_shpBoardPress' then
    w := core.syp_worker(x -> 'pressman', 'pressman', 'Pressman', null, false);
    perform core.syp_put('production.shopify_board_press', core.syp_shopify_board_press(x, lk, '{}', x) || core.syp_sku(x ->> 'sku')
      || jsonb_build_object('worker_id', w -> 'id', 'link_note', w -> 'note', 'sales_order_id', core.syp_so(x ->> 'orderNo')));
  when 'pt_shpBoardTest' then
    perform core.syp_put('production.shopify_board_status', core.syp_shopify_board_status(x, lk, jsonb_build_object('line_key', k), x) || core.syp_sku(x ->> 'sku')
      || jsonb_build_object('sales_order_id', core.syp_so(x ->> 'orderNo')));
  when 'pt_listingAlerts' then
    perform core.syp_put('sales.listing_alerts', core.syl_listing_alerts(x, lk, '{}', x) || core.syp_sku(x ->> 'sku'));
  end case;
end $$;

-- the two one-record lists, built again from the working copy after the round (like Masters / HR)
create or replace function core.syp_blocks_rebuild() returns void language plpgsql security definer set search_path = core, public as $$
declare B jsonb := coalesce((select jsonb_object_agg(k, value) from core.sync_raw where reg = 'pt_blockNeed' and value is not null), '{}'); bc text; rec jsonb; keep text[] := '{}';
begin
  perform set_config('core.loading', 'on', true);
  for bc in select distinct z from (select jsonb_object_keys(case when jsonb_typeof(B -> 'info') = 'object' then B -> 'info' else '{}' end) z
                                    union select jsonb_object_keys(case when jsonb_typeof(B -> 'map') = 'object' then B -> 'map' else '{}' end)) u loop
    rec := '{}';
    if B -> 'info' -> bc is not null and jsonb_typeof(B -> 'info' -> bc) <> 'null' then rec := rec || jsonb_build_object('info', B -> 'info' -> bc); end if;
    if B -> 'map' -> bc is not null and jsonb_typeof(B -> 'map' -> bc) <> 'null' then rec := rec || jsonb_build_object('map', B -> 'map' -> bc); end if;
    keep := keep || ('pt_blockNeed:' || bc);
    perform core.syp_put('production.print_blocks', core.syp_print_blocks(rec, 'pt_blockNeed:' || bc, jsonb_build_object('block_key', bc), rec)
      || jsonb_build_object('vendor_id', case when jsonb_typeof(rec -> 'info') = 'object' then core.syp_vendor(rec #>> '{info,printer}', null) end));
  end loop;
  perform core.sy_gone_under('production.print_blocks', 'pt_blockNeed:', keep);
  insert into core.settings (key, value, note, legacy_key) values ('production.print_blocks_saved', jsonb_build_object('at', coalesce(B -> 'at', 'null'), 'by', coalesce(B -> 'by', 'null')),
    'pt_blockNeed at / by (the blocks list itself is production.print_blocks)', 'pt_blockNeed') on conflict (key) do update set value = excluded.value;
  update core.settings set value = 'false'::jsonb where key = 'sync.blocks_dirty';
end $$;
create or replace function core.syl_listings_rebuild() returns void language plpgsql security definer set search_path = core, public as $$
declare A jsonb := coalesce((select jsonb_object_agg(k, value) from core.sync_raw where reg = 'pt_amzListings' and value is not null), '{}'); ln text; i int := 0; p text[]; keep text[] := '{}'; lk text;
begin
  perform set_config('core.loading', 'on', true);
  foreach ln in array string_to_array(coalesce(A ->> 'list', ''), E'\n') loop
    i := i + 1;
    if ln = '' then continue; end if;
    p := string_to_array(ln, E'\t'); lk := 'pt_amzListings/list#' || i; keep := keep || lk;
    perform core.syp_put('sales.amazon_listings', jsonb_build_object('legacy_key', lk, 'firebase', to_jsonb(ln), 'line_no', i, 'sku', p[1], 'status', p[2], 'channel', p[3], 'asin', p[4],
      'more', case when array_length(p, 1) > 4 then array_to_string(p[5:], E'\t') end) || core.syp_sku(p[1]));
  end loop;
  perform core.sy_gone_under('sales.amazon_listings', 'pt_amzListings/list#', keep);
  insert into core.settings (key, value, note, legacy_key) values ('sales.amazon_listings', A, 'pt_amzListings exactly as it is (at, by, brands, the whole list); its lines are also in sales.amazon_listings', 'pt_amzListings')
  on conflict (key) do update set value = excluded.value;
  update core.settings set value = 'false'::jsonb where key = 'sync.listings_dirty';
end $$;
-- =====================================================================================================================
-- HISTORY — the ERP's log lines (pt_audit/<month>/<id>) and recycle bin (pt_trash/<id>) as make-history.js builds them
-- =====================================================================================================================
create or replace function core.syh_put(p_table text, p_row jsonb) returns bigint language plpgsql security definer set search_path = core, public as $$
declare rid bigint;
begin
  perform core.load_history_rows(p_table, jsonb_build_array(p_row));
  execute format('select id from %s where legacy_key = $1', p_table) into rid using p_row ->> 'legacy_key';
  delete from core.sync_gone where tbl = p_table and legacy_key = p_row ->> 'legacy_key';
  return rid;
end $$;
create or replace function core.syh_person(e text) returns bigint language sql stable security definer set search_path = core, public as $$
  select id from core.people where lower(core.fb_trim(email)) = lower(core.fb_trim(e)) and lower(core.fb_trim(e)) <> '' order by id desc limit 1
$$;
create or replace function core.syh_record(reg text, lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare pid bigint; paths jsonb; np int; nv int; i int; v jsonb; has boolean; keep text[] := '{}'; ck text; p text; big boolean;
begin
  if reg = 'pt_trash' then
    perform core.syh_put('history.recycle_bin', jsonb_build_object('legacy_key', lk, 'firebase', x, 'trash_id', split_part(lk, '/', 2),
      'at_time', core.fb_conv_stock(x -> 'at', 'ts'), 'by_email', core.fb_conv(x -> 'by', 't'), 'tab', core.fb_conv(x -> 'tab', 't'), 'why', core.fb_conv(x -> 'why', 't'),
      'path', core.fb_conv(x -> 'path', 't'), 'list', nullif(split_part(trim(both '/' from coalesce(x ->> 'path', '')), '/', 1), ''),
      'value', case when x ? 'value' and jsonb_typeof(x -> 'value') <> 'null' then x -> 'value' end,
      'restored_at', core.fb_conv_stock(x -> 'restoredAt', 'ts'), 'restored_by', core.fb_conv(x -> 'restoredBy', 't'), 'person_id', core.syh_person(x ->> 'by')));
    return;
  end if;
  paths := case jsonb_typeof(x -> 'paths') when 'array' then x -> 'paths'
                when 'object' then (select coalesce(jsonb_agg(value order by (key ~ '^\d+$') desc, case when key ~ '^\d+$' then key::bigint end, key collate "C"), '[]') from jsonb_each(x -> 'paths'))
                else '[]'::jsonb end;
  np := jsonb_array_length(paths);
  nv := case jsonb_typeof(x -> 'vals') when 'array' then jsonb_array_length(x -> 'vals') when 'object' then (select count(*) from jsonb_object_keys(x -> 'vals')) else 0 end;
  pid := core.syh_put('history.audit_entries', jsonb_build_object('legacy_key', lk, 'firebase', x, 'month', split_part(lk, '/', 2), 'entry_id', split_part(lk, '/', 3),
    'at_time', core.fb_conv_stock(x -> 'at', 'ts'), 'by_email', core.fb_conv(x -> 'by', 't'), 'tab', core.fb_conv(x -> 'tab', 't'), 'kind', core.fb_conv(x -> 'kind', 't'),
    'n', core.fb_conv(x -> 'n', 'n'), 'note', core.fb_conv(x -> 'note', 't'), 'paths', case when jsonb_typeof(x -> 'paths') = 'null' then null else x -> 'paths' end,
    'person_id', core.syh_person(x ->> 'by'),
    'mark', case when x ? 'vals' and nv <> np then 'paths ' || np || ' · values ' || nv || ' — paired by place' end));
  for i in 0 .. np - 1 loop
    if jsonb_typeof(x -> 'vals') = 'array' then has := i < jsonb_array_length(x -> 'vals'); v := x -> 'vals' -> i;
    elsif jsonb_typeof(x -> 'vals') = 'object' then has := (x -> 'vals') ? i::text; v := x -> 'vals' -> (i::text);
    else has := false; v := null; end if;
    if has and v is not null and jsonb_typeof(v) = 'null' then v := 'null'::jsonb; end if;
    big := has and jsonb_typeof(v) = 'object' and (select count(*) from jsonb_object_keys(v)) = 1 and v ? '_bytes';
    p := core.js_str(paths -> i); ck := lk || '/paths/' || i; keep := keep || ck;
    perform core.syh_put('history.audit_changes', jsonb_build_object('legacy_key', ck, 'firebase', case when has and jsonb_typeof(v) <> 'null' then v end,
      'audit_entry_id', pid, 'place', i, 'path', core.fb_conv(paths -> i, 't'), 'list', nullif(split_part(trim(both '/' from p), '/', 1), ''),
      'mark', case when big then 'value too big — the ERP kept its size only (' || core.js_str(v -> '_bytes') || ' bytes)'
                   when has and jsonb_typeof(v) = 'null' then 'set to nothing (removed)' when not has then 'no value at this place' end));
  end loop;
  perform core.sy_gone_under('history.audit_changes', lk || '/paths/', keep);
end $$;

-- =====================================================================================================================
-- THE TEST ERP's CHECK LINES — fingerprints only, rows whose Firebase record is gone left out (they are not "extra")
-- =====================================================================================================================
create or replace function core.hr_fp() returns jsonb language sql stable security definer set search_path = core, public as $$
  select case when core.me_id() is not null or auth.role() = 'service_role' or session_user = 'postgres' then (
    select coalesce(jsonb_object_agg(x.k, x.fp), '{}'::jsonb) || jsonb_build_object('#copy_of', (select st.value #>> '{}' from core.settings st where st.key = 'sync.hr_backup'))
      from (select 'pt_empList/' || line_no k, fp, legacy_key, 'hr.workers' tb from hr.workers where line_no is not null
            union all select 'pt_rateList/' || line_no, fp, legacy_key, 'hr.piece_rates' from hr.piece_rates where line_no is not null
            union all select legacy_key, fp, legacy_key, 'hr.attendance' from hr.attendance union all select legacy_key, fp, legacy_key, 'hr.extra_hours' from hr.extra_hours
            union all select legacy_key, fp, legacy_key, 'hr.team_sizes' from hr.team_sizes union all select legacy_key, fp, legacy_key, 'hr.contractor_heads' from hr.contractor_heads
            union all select legacy_key, fp, legacy_key, 'core.login_directory' from core.login_directory union all select legacy_key, fp, legacy_key, 'core.vendor_logins' from core.vendor_logins
            union all select legacy_key, fp, legacy_key, 'core.vendor_map' from core.vendor_map union all select legacy_key, fp, legacy_key, 'core.printers' from core.printers
            union all select legacy_key, fp, legacy_key, 'archive.perms_copy' from archive.perms_copy) x
     where x.k is not null and x.fp is not null and not exists (select 1 from core.sync_gone g where g.tbl = x.tb and g.legacy_key = x.legacy_key)) end
$$;
create or replace function core.production_fp() returns jsonb language sql stable security definer set search_path = core, public as $$
  select case when core.me_id() is not null or auth.role() = 'service_role' or session_user = 'postgres' then (
    select coalesce(jsonb_object_agg(x.legacy_key, x.fp), '{}'::jsonb) || jsonb_build_object('#copy_of', (select st.value #>> '{}' from core.settings st where st.key = 'sync.production_backup'))
      from (select legacy_key, fp, 'production.ppc_plans' tb from production.ppc_plans union all select legacy_key, fp, 'production.print_blocks' from production.print_blocks
            union all select legacy_key, fp, 'production.cloth_challans' from production.cloth_challans union all select legacy_key, fp, 'production.fabric_ready' from production.fabric_ready
            union all select legacy_key, fp, 'production.print_orders' from production.print_orders union all select legacy_key, fp, 'production.cutting' from production.cutting
            union all select legacy_key, fp, 'production.job_work' from production.job_work union all select legacy_key, fp, 'production.qc_checks' from production.qc_checks
            union all select legacy_key, fp, 'production.qc_rework_out' from production.qc_rework_out union all select legacy_key, fp, 'production.qc_rework_back' from production.qc_rework_back
            union all select legacy_key, fp, 'production.fg_sends' from production.fg_sends union all select legacy_key, fp, 'production.shopify_board_press' from production.shopify_board_press
            union all select legacy_key, fp, 'production.shopify_board_status' from production.shopify_board_status) x
     where x.legacy_key is not null and x.fp is not null and not exists (select 1 from core.sync_gone g where g.tbl = x.tb and g.legacy_key = x.legacy_key)) end
$$;
create or replace function core.listings_fp() returns jsonb language sql stable security definer set search_path = core, public as $$
  select case when core.me_id() is not null or auth.role() = 'service_role' or session_user = 'postgres' then (
    select coalesce(jsonb_object_agg(x.legacy_key, x.fp), '{}'::jsonb)
      from (select legacy_key, fp, 'sales.listing_alerts' tb from sales.listing_alerts union all select legacy_key, fp, 'sales.amazon_listings' from sales.amazon_listings) x
     where x.legacy_key is not null and x.fp is not null and not exists (select 1 from core.sync_gone g where g.tbl = x.tb and g.legacy_key = x.legacy_key)) end
$$;
create or replace function core.history_fp_month(p_month text) returns jsonb language sql stable security definer set search_path = core, public as $$
  select case when core.me_id() is not null or auth.role() = 'service_role' or session_user = 'postgres' then (
    select coalesce(jsonb_object_agg(x.legacy_key, x.fp), '{}'::jsonb)
      from (select legacy_key, fp from history.audit_entries where month = p_month union all select legacy_key, fp from history.recycle_bin) x
     where x.fp is not null) end
$$;
revoke all on function core.hr_fp(), core.production_fp(), core.listings_fp(), core.history_fp_month(text) from public;
grant execute on function core.hr_fp(), core.production_fp(), core.listings_fp(), core.history_fp_month(text) to anon, authenticated, service_role;
create index if not exists audit_entries_month on history.audit_entries (month);
create index if not exists order_book_line_u on production.order_book (core.fb_u(order_no), core.fb_u(sku));
create index if not exists job_work_fb_id on production.job_work (fb_id);
create index if not exists cloth_challans_doc_no on production.cloth_challans (doc_no);


