create or replace function core.syf_put(p_table text, p_row jsonb) returns bigint language plpgsql security definer set search_path = core, public as $$
declare rid bigint;
begin
  if p_table = any (core.leftovers_tables()) then perform core.load_leftover_rows(p_table, jsonb_build_array(p_row));
  else perform core.load_sellora_rows(p_table, jsonb_build_array(p_row)); end if;
  execute format('select id from %s where legacy_key = $1', p_table) into rid using p_row ->> 'legacy_key';
  delete from core.sync_gone where tbl = p_table and legacy_key = p_row ->> 'legacy_key';
  return rid;
end $$;
create or replace function core.syf_setting(p_key text, p_value jsonb, p_note text, p_lk text) returns void language sql security definer set search_path = core, public as $$
  insert into core.settings (key, value, note, legacy_key) values (lower(regexp_replace(p_key, '[^A-Za-z0-9_.]', '_', 'g')), coalesce(p_value, 'null'::jsonb), p_note, p_lk)
  on conflict (key) do update set value = excluded.value
$$;
-- the loaders' ent(): a list → (place, item), a map → (key, item); empty places left out
create or replace function core.syf_ents(v jsonb) returns table (k text, e jsonb) language sql immutable as $$
  select (o - 1)::text, a.e from jsonb_array_elements(case when jsonb_typeof(v) = 'array' then v else '[]' end) with ordinality a(e, o) where jsonb_typeof(a.e) <> 'null'
  union all select m.key, m.value from jsonb_each(case when jsonb_typeof(v) = 'object' then v else '{}' end) m where jsonb_typeof(m.value) <> 'null'
$$;
-- one document → its rows (x null = the document was deleted: its rows go on the gone list)
create or replace function core.syf_doc(coll text, id text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare base text := 'fs/' || coll || '/' || id; keep text[] := '{}'; c record; lk text; tb text; meta jsonb;
begin
  perform set_config('core.loading', 'on', true);
  if coll in ('repl_india', 'replshoprows') then
    tb := case coll when 'repl_india' then 'planning.india_stock' else 'planning.amazon_stock' end;
    for c in select * from core.syf_ents(x -> 'r') z where jsonb_typeof(z.e) = 'object' loop
      lk := base || '/r/' || c.k; keep := keep || lk;
      meta := jsonb_build_object('doc_id', id, 'row_no', case when c.k ~ '^\d{1,9}$' then c.k::int end);
      perform core.syf_put(tb, (case coll when 'repl_india' then core.syf_india_stock(c.e, lk, meta, c.e)
                                 else core.syf_amazon_stock(c.e, lk, jsonb_build_object('brand', split_part(id, '_', 1)) || meta, c.e) end) || core.syp_sku(c.e ->> 'sku'));
    end loop;
    perform core.sy_gone_under(tb, base || '/r/', keep);
    if x is not null and x - 'r' <> '{}'::jsonb then perform core.syf_setting('planning.' || coll || '_' || id, x - 'r', 'Firestore ' || coll || '/' || id || ' without its rows', base); end if;
  elsif coll in ('replshop', 'stock') then
    tb := case coll when 'replshop' then 'planning.amazon_fulfillable' else 'planning.stock_snapshot' end;
    for c in select * from core.syf_ents(x -> (case coll when 'replshop' then 'ful' else 'm' end)) loop
      lk := base || case coll when 'replshop' then '/ful/' else '/m/' end || c.k; keep := keep || lk;
      perform core.syf_put(tb, jsonb_build_object('legacy_key', lk, 'firebase', c.e, 'brand', id, 'sku', c.k, 'qty', case when jsonb_typeof(c.e) = 'number' then c.e end) || core.syp_sku(c.k));
    end loop;
    perform core.sy_gone_under(tb, base || '/', keep);
    if x is not null then perform core.syf_setting(case coll when 'replshop' then 'planning.amazon_fulfillable_' else 'planning.stock_snapshot_' end || id,
      x - (case coll when 'replshop' then 'ful' else 'm' end),
      'Firestore ' || coll || '/' || id || ' without its ' || case coll when 'replshop' then 'ful map (the map is planning.amazon_fulfillable)' else 'm map (the map is planning.stock_snapshot)' end, base); end if;
  elsif coll = 'audit' and id in ('shoporders', 'skumeta') then
    tb := case id when 'shoporders' then 'sales.shopify_order_notes' else 'sales.sku_amazon_meta' end;
    for c in select * from core.syf_ents(x -> 'm') loop
      lk := base || '/m/' || c.k; keep := keep || lk;
      if id = 'shoporders' then
        perform core.syf_put(tb, core.syf_shop_notes(case when jsonb_typeof(c.e) = 'object' then c.e else jsonb_build_object('value', c.e) end, lk, jsonb_build_object('shop_order_id', c.k), c.e)
          || jsonb_build_object('shopify_order_id', (select so.id from sales.shopify_orders so where core.fb_u(so.shop_order_id) = core.fb_u(c.k) order by so.id limit 1)));
      else
        perform core.syf_put(tb, core.syf_sku_meta(case when jsonb_typeof(c.e) = 'object' then c.e else jsonb_build_object('value', c.e) end, lk, jsonb_build_object('sku', c.k), c.e) || core.syp_sku(c.k));
      end if;
    end loop;
    perform core.sy_gone_under(tb, base || '/m/', keep);
    if x is not null then perform core.syf_setting(case id when 'shoporders' then 'sellora.shoporders_meta' else 'sellora.skumeta_meta' end, x - 'm',
      'Firestore audit/' || id || ' without its m map', base); end if;
  elsif coll = 'b2bimg' then
    if id = '_index' then perform core.syf_setting('sellora.b2bimg_index', x, 'Firestore b2bimg/_index exactly as it is', base);
    elsif x is null then insert into core.sync_gone (tbl, legacy_key) values ('sales.b2b_images', base) on conflict do nothing;
    else perform core.syf_put('sales.b2b_images', core.syf_b2b_images(x, base, jsonb_build_object('doc_id', id), x) || core.syp_sku(x ->> 'sku')); end if;
  end if;
end $$;
-- a change to a Firestore document: into the working copy (Firestore keeps what it is given), then that document's rows
create or replace function core.syf_apply(p text, val jsonb, p_kind text) returns void language plpgsql security definer set search_path = core, public as $$
declare segs text[] := string_to_array(trim(both '/' from p), '/'); coll text := segs[2]; id text := segs[3]; old jsonb; nxt jsonb;
begin
  select r.value into old from core.sync_raw r where r.reg = 'fs/' || coll and r.k = id;
  nxt := case when array_length(segs, 1) = 3 then (case when p_kind = 'delete' then null else val end)
              else core.fs_set(old, segs[4:], coalesce(val, 'null'::jsonb)) end;
  insert into core.sync_raw as r (reg, k, value) values ('fs/' || coll, id, nxt) on conflict on constraint sync_raw_pkey do update set value = excluded.value, at = now();
  if coll = any (array['bsrweeks', 'bsr', 'parentnames', 'listingrules', 'auditlaunch', 'auditmanual', 'weeklyrows', 'sarows', 'salesanalysis', 'imgrows', 'imgsnap', 'age']::text[]) or (coll = 'audit' and id = any (array['deals', 'SP', 'ppc30', 'sales30', 'trends', 'weekly', 'skuloc']::text[])) then perform core.syf_sellora_doc(coll, id, nxt);   -- part 2
  else perform core.syf_doc(coll, id, nxt); end if;
end $$;


-- =====================================================================================================================
-- FIRESTORE (part 2: Sellora's documents) — as make-sellora.js / load-sellora.js
-- =====================================================================================================================
