$$;
create or replace function core.syf_deals(x jsonb, lk text, extra jsonb, fb jsonb) returns jsonb language sql immutable as $$
  select jsonb_build_object('legacy_key', lk, 'firebase', fb)
    || coalesce(extra, '{}'::jsonb)
    || jsonb_build_object('by_email', core.fb_conv_stock(core.syp_get(x, '{"by"}'::text[], false), 't'),
      'd', core.fb_conv_stock(core.syp_get(x, '{"d"}'::text[], false), 'n'),
      'end', core.fb_conv_stock(core.syp_get(x, '{"end"}'::text[], false), 'd'),
      'image', core.fb_conv_stock(core.syp_get(x, '{"image"}'::text[], false), 't'),
      's', core.fb_conv_stock(core.syp_get(x, '{"s"}'::text[], false), 'd'),
      'start', core.fb_conv_stock(core.syp_get(x, '{"start"}'::text[], false), 'd'),
      't', core.fb_conv_stock(core.syp_get(x, '{"t"}'::text[], false), 't'),
      'v', core.fb_conv_stock(core.syp_get(x, '{"v"}'::text[], false), 'n'))
$$;
create or replace function core.syf_parent_names(x jsonb, lk text, extra jsonb, fb jsonb) returns jsonb language sql immutable as $$
  select jsonb_build_object('legacy_key', lk, 'firebase', fb)
    || coalesce(extra, '{}'::jsonb)
    || jsonb_build_object('at_time', core.fb_conv_stock(core.syp_get(x, '{"at"}'::text[], false), 'd'),
      'by_email', core.fb_conv_stock(core.syp_get(x, '{"by"}'::text[], false), 't'),
      'v', core.fb_conv_stock(core.syp_get(x, '{"v"}'::text[], false), 't'))
$$;
-- load-sellora.js: SKU by ASIN = the first SKU (lowest id) with that ASIN
create or replace function core.syf_asin_sku(a text) returns bigint language sql stable security definer set search_path = core, public as $$
  select case when core.fb_u(a) = '' then null else (select id from core.skus where core.fb_u(asin) = core.fb_u(a) order by id limit 1) end
$$;
-- JSON.stringify(x).length: JavaScript counts a character beyond U+FFFF as two
create or replace function core.syf_js_len(x jsonb) returns int language plpgsql immutable as $$
declare s text := core.js_json(x);
begin
  return length(s) + length(regexp_replace(s, '[^\U00010000-\U0010FFFF]', '', 'g'));
end $$;
create or replace function core.syf_is_cache(coll text, id text) returns boolean language sql immutable as $$
  select coll = any (array['weeklyrows', 'sarows', 'salesanalysis', 'imgrows', 'imgsnap', 'age']::text[]) or (coll = 'listingrules' and id = any (array['catalog_CPC', 'catalog_SP']::text[])) or (coll = 'audit' and id = any (array['ppc30', 'sales30', 'trends', 'weekly', 'skuloc']::text[]))
$$;
-- one Sellora document → its rows and settings (x null = deleted: its rows on the gone list, settings kept)
create or replace function core.syf_sellora_doc(coll text, id text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
declare base text := 'fs/' || coll || '/' || id; keep text[] := '{}'; c record; lk text; it jsonb; ins int;
begin
  perform set_config('core.loading', 'on', true);
  if coll = 'bsrweeks' then
    for c in select * from core.syf_ents(x -> 'r') loop
      lk := base || '/r/' || c.k; keep := keep || lk;
      perform core.syf_put('sales.amazon_bsr', core.syf_bsr(case when jsonb_typeof(c.e) = 'object' then c.e else jsonb_build_object('value', c.e) end, lk,
        jsonb_build_object('brand', split_part(id, '__', 1), 'week', nullif(split_part(id, '__', 2), ''), 'asin', c.k), c.e) || jsonb_build_object('sku_id', core.syf_asin_sku(c.k)));
    end loop;
    perform core.sy_gone_under('sales.amazon_bsr', base || '/r/', keep);
    if x is not null then perform core.syf_setting('sellora.bsrweeks_' || id, x - 'r', 'Firestore bsrweeks/' || id || ' without its r map (the rows are sales.amazon_bsr)', base); end if;
  elsif coll = 'bsr' then
    if x is not null then perform core.syf_setting('sellora.bsr_' || id, x, 'Firestore bsr/' || id || ' exactly as it is', base); end if;
  elsif coll = 'parentnames' then
    for c in select * from core.syf_ents(x -> 'n') loop
      lk := base || '/n/' || c.k; keep := keep || lk;
      perform core.syf_put('sales.amazon_parent_names', core.syf_parent_names(case when jsonb_typeof(c.e) = 'object' then c.e else jsonb_build_object('name', c.e) end, lk,
        jsonb_build_object('brand', id, 'parent_asin', c.k), c.e));
    end loop;
    perform core.sy_gone_under('sales.amazon_parent_names', base || '/n/', keep);
    if x is not null then perform core.syf_setting('sellora.parentnames_' || id, x - 'n', 'Firestore parentnames/' || id || ' without its n map', base); end if;
  elsif coll = 'audit' and id = 'deals' then
    for c in select 'plan' kind, z.* from core.syf_ents(x -> 'plan') z union all select 'event', z.* from core.syf_ents(x -> 'events') z union all select 'image', z.* from core.syf_ents(x -> 'imgs') z loop
      lk := base || '/' || case c.kind when 'plan' then 'plan' when 'event' then 'events' else 'imgs' end || '/' || c.k; keep := keep || lk;
      it := case when jsonb_typeof(c.e) = 'object' then c.e when c.kind = 'image' then jsonb_build_object('image', c.e) else jsonb_build_object('value', c.e) end;
      perform core.syf_put('sales.amazon_deals', core.syf_deals(it, lk, jsonb_build_object('item_kind', c.kind, 'item_key', c.k,
          'asin', case c.kind when 'plan' then split_part(c.k, '|', 1) when 'image' then c.k end), c.e)
        || jsonb_build_object('sku_id', case c.kind when 'plan' then core.syf_asin_sku(split_part(c.k, '|', 1)) when 'image' then core.syf_asin_sku(c.k) end));
    end loop;
    perform core.sy_gone_under('sales.amazon_deals', base || '/', keep);
    if x is not null then perform core.syf_setting('sellora.deals_meta', x - 'plan' - 'events' - 'imgs', 'Firestore audit/deals without plan / events / imgs (those are sales.amazon_deals)', base); end if;
  elsif coll = 'listingrules' and id = 'config' then
    if x is not null then perform core.syf_setting('sellora.listingrules_config', x, 'Firestore listingrules/config exactly as it is (issues, templates, events)', base); end if;
  elsif coll = 'audit' and id = 'SP' then
    if x is not null then perform core.syf_setting('sellora.audit_sp', x, 'Firestore audit/SP exactly as it is', base); end if;
  elsif coll in ('auditlaunch', 'auditmanual') then
    if x is not null then perform core.syf_setting('sellora.' || coll || '_' || id, x, 'Firestore ' || coll || '/' || id || ' exactly as it is', base); end if;
  end if;
  -- the work people finished, inside two caches: kept as settings too
  if coll = 'audit' and id = 'weekly' and x is not null then
    perform core.syf_setting('sellora.weekly_done', jsonb_build_object('doneWeeks', coalesce(x -> 'doneWeeks', 'null'), 'pending', coalesce(x -> 'pending', 'null'),
      'adDone', coalesce(x -> 'adDone', 'null'), 'weeks', coalesce(x -> 'weeks', 'null')), 'audit/weekly: done weeks, pending, ads done (the whole doc is in archive.sellora_cache_docs)', 'fs/audit/weekly#done');
  elsif coll = 'audit' and id = 'trends' and x is not null then
    perform core.syf_setting('sellora.trends_done', jsonb_build_object('pending', coalesce(x -> 'pending', 'null'), 'adDone', coalesce(x -> 'adDone', 'null')),
      'audit/trends: pending, ads done (the whole doc is in archive.sellora_cache_docs)', 'fs/audit/trends#done');
  end if;
  -- caches: one archive row per document, whole
  if core.syf_is_cache(coll, id) then
    if x is null then insert into core.sync_gone (tbl, legacy_key) values ('archive.sellora_cache_docs', base) on conflict do nothing;
    else
      ins := case when jsonb_typeof(x -> 'r') = 'array' then jsonb_array_length(x -> 'r') when jsonb_typeof(x -> 'r') = 'object' then (select count(*) from jsonb_object_keys(x -> 'r'))::int
                  when jsonb_typeof(x -> 'rows') = 'array' then jsonb_array_length(x -> 'rows') end;
      perform core.syf_put('archive.sellora_cache_docs', jsonb_build_object('legacy_key', base, 'firebase', x, 'collection', coll, 'doc_id', id,
        'updated_in_firestore', nullif(current_setting('core.save_at', true), ''), 'bytes', core.syf_js_len(x), 'rows_inside', ins));
    end if;
  end if;
end $$;

