-- this engine takes a change when its list is one of the above (a whole Firestore collection at once is left to the PC processor).
-- HR waits until the engine's working copy has HR (setting sync.hr_ready, set by tools/sync-raw-seed.js): until then its saves stay "new".
-- the section a save belongs to: audit holds documents of two parts (shoporders / skumeta = the ERP's, the Sellora ones = part 2,
-- the rest — costs, CPC … — not yet)
create or replace function core.sy_sec(p text, l_reg text, l_sec text) returns text language sql immutable as $$
  select case when l_reg <> 'fs/audit' then l_sec
              when split_part(p, '/', 3) in ('shoporders', 'skumeta') then 'firestore'
              when split_part(p, '/', 3) = any (array['deals', 'SP', 'ppc30', 'sales30', 'trends', 'weekly', 'skuloc']::text[]) then 'sellora' end
$$;
create or replace function core.sy_handles(p text) returns boolean language sql stable as $$
  select exists (select 1 from core.sy_list(p) l, lateral (select core.sy_sec(p, l.reg, l.sec) s) z
                  where (l.base = 1 or array_length(string_to_array(p, '/'), 1) >= 3)
                    and z.s is not null
                    and (z.s not in ('hr', 'production', 'leftovers', 'firestore', 'sellora', 'misc') or exists (select 1 from core.settings s where s.key = 'sync.' || z.s || '_ready' and s.value = 'true'::jsonb)))
$$;

create or replace function core.sy_record(reg text, lk text, x jsonb) returns void language plpgsql security definer set search_path = core, public as $$
begin
  case reg
    when 'pt_salesOrders' then perform core.sy_sales(lk, x);
    when 'pt_orderBook' then perform core.sy_order_book(lk, x);
    when 'pt_vendorOrders' then perform core.sy_vendor_order(lk, x);
    when 'pt_vendorChallans' then perform core.sy_challan(lk, x);
    when 'pt_shopProd' then perform core.sy_shop_floor(lk, x);
    when 'fs/po' then perform core.sy_amazon_po(lk, x);
    when 'fs/packlist' then perform core.sy_packing_list(lk, x);
    when 'pt_masterDB', 'pt_customSkus', 'pt_skuImages', 'pt_skuPriority', 'pt_fnskuMap' then perform core.sy_skus(reg, lk, x);
    when 'pt_ppc', 'pt_flowDemand', 'pt_flowChallans', 'pt_flowPrintOrders', 'pt_cuttingData', 'pt_baseData', 'pt_baseDone', 'pt_qcChecks', 'pt_qcIssuance', 'pt_qcReturns',
         'pt_flowFgSend', 'pt_shpBoardPress', 'pt_shpBoardTest', 'pt_listingAlerts' then perform core.syp_record(reg, lk, x);
    when 'pt_audit', 'pt_trash' then perform core.syh_record(reg, lk, x);
    else perform core.sy_stock(reg, lk, x);
  end case;
end $$;
-- a record deleted in Firebase: it and its lists' rows go on the gone list — every row stays
create or replace function core.sy_record_gone(p_reg text, p_tbl text, p_kids text[], lk text) returns void language plpgsql security definer set search_path = core, public as $$
declare t text; was text;
begin
  insert into core.sync_gone (tbl, legacy_key) values (p_tbl, lk) on conflict do nothing;
  foreach t in array p_kids loop perform core.sy_gone_under(t, lk || '/', '{}'); end loop;
  if p_reg = 'pt_orderBook' then select firebase ->> 'shopOrderId' into was from production.order_book where legacy_key = lk; perform core.sy_shopify(was); end if;
  if p_reg in ('pt_masterDB', 'pt_customSkus') then      -- a SKU gone: its code's clash marks counted again
    execute format('select core.fb_u(sku) from %s where legacy_key = $1', p_tbl) into was using lk; perform core.sy_clash(was);
  end if;
end $$;
-- the record as Supabase holds it (nothing if it is gone)
create or replace function core.sy_current(tbl text, lk text) returns jsonb language plpgsql stable security definer set search_path = core, public as $$
declare v jsonb;
begin
  if exists (select 1 from core.sync_gone g where g.tbl = sy_current.tbl and g.legacy_key = lk) then return null; end if;
  if tbl = 'core.settings' then select s.value into v from core.settings s where s.legacy_key = lk; return v; end if;   -- pt_fnskuMap is kept as a setting
  execute format('select firebase from %s where legacy_key = $1', tbl) into v using lk;
  return v;
end $$;

-- Firestore keeps what it is given (empty lists, fields set to nothing): a field written into a document, nothing thrown away
create or replace function core.fs_set(node jsonb, segs text[], val jsonb) returns jsonb language plpgsql immutable as $$
begin
  if coalesce(array_length(segs, 1), 0) = 0 then return val; end if;
  if node is null or jsonb_typeof(node) <> 'object' then node := '{}'; end if;
  return node || jsonb_build_object(segs[1], coalesce(core.fs_set(node -> segs[1], segs[2:], val), 'null'::jsonb));
end $$;

drop function if exists core.sy_apply(text, jsonb);   -- now also told the kind of save (Firestore: a field set to nothing is kept)
create or replace function core.sy_apply(p text, val jsonb, p_kind text default 'put') returns int language plpgsql security definer set search_path = core, public as $$
declare l record; segs text[] := string_to_array(trim(both '/' from p), '/'); lk text; old jsonb; nxt jsonb; n int := 0;
        cpre text; cont jsonb; ncont jsonb; rec record; keys text[]; k text; o jsonb; v jsonb; d int; anyv boolean;
begin
  select * into l from core.sy_list(p);
  if l.reg is null then raise exception 'sy_apply: % is not a list the engine knows', p; end if;
  if l.sec in ('firestore', 'sellora') then perform core.syf_apply(p, val, p_kind); return 1; end if;      -- the ERP's Firestore documents: whole, through the working copy
  if l.tbl = 'core.sync_raw' then perform core.sy_raw_apply(p, val); return 1; end if;      -- Masters and Control: through the working copy
  if array_length(segs, 1) >= l.depth then
    -- one record: apply the change to it, rebuild its rows
    lk := array_to_string(segs[l.base:l.depth], '/');
    old := core.sy_current(l.tbl, lk);
    if l.base = 2 then           -- a Firestore document: written whole, or one field of it, exactly as given
      nxt := case when p_kind = 'delete' then null
                  when array_length(segs, 1) = l.depth then val
                  else core.fs_set(old, segs[l.depth + 1:], coalesce(val, 'null'::jsonb)) end;
    else nxt := core.fb_set(old, segs[l.depth + 1:], val); end if;
    if nxt is null then if old is not null then perform core.sy_record_gone(l.reg, l.tbl, l.kids, lk); end if;
    else perform core.sy_record(l.reg, lk, nxt); end if;      -- every save rebuilds its record, also one that looks unchanged (its summaries are counted again)
    return 1;
  end if;
  -- a whole list (or one vendor's group of orders) at once: the records before and after, compared one by one
  cpre := array_to_string(segs[l.base:], '/');                 -- e.g. pt_vendorOrders/V12  or  pt_orderBook
  d := l.depth - l.base + 1 - array_length(segs[l.base:], 1);   -- how many levels below the change a record sits (1 or 2)
  cont := null;
  for rec in execute format('select legacy_key, firebase from %s t where left(legacy_key, %s) = %L and firebase is not null
                               and not exists (select 1 from core.sync_gone g where g.tbl = %L and g.legacy_key = t.legacy_key)',
                            l.tbl, length(cpre) + 1, cpre || '/', l.tbl) loop
    cont := core.fb_set(cont, string_to_array(substr(rec.legacy_key, length(cpre) + 2), '/'), rec.firebase);
  end loop;
  ncont := core.fb_norm(val);
  anyv := l.reg in ('pt_skuImages', 'pt_skuPriority');        -- these two lists hold plain values (a picture link, a priority), not records
  -- every record key in either, at depth d
  for k in
    select distinct key from (
      select a.k as key from core.fb_ents(cont, anyv) a where d = 1
      union select a.k from core.fb_ents(ncont, anyv) a where d = 1
      union select a.k || '/' || b.k from core.fb_objs(cont) a, core.fb_objs(a.x) b where d = 2
      union select a.k || '/' || b.k from core.fb_objs(ncont) a, core.fb_objs(a.x) b where d = 2) z
  loop
    o := cont #> string_to_array(k, '/'); v := ncont #> string_to_array(k, '/');
    if v is not null and (jsonb_typeof(v) = 'null' or (jsonb_typeof(v) <> 'object' and not anyv)) then v := null; end if;
    lk := cpre || '/' || k;
    if v is null then if o is not null then perform core.sy_record_gone(l.reg, l.tbl, l.kids, lk); n := n + 1; end if;
    elsif o is distinct from v then perform core.sy_record(l.reg, lk, v); n := n + 1; end if;
  end loop;
  return n;
end $$;

-- 6 · THE ENGINE: take the waiting Orders changes in order and apply them. A change that fails is marked failed with the reason
--     (the others go on). Called every few seconds (pg_cron, sync_engine_cron.sql) or by hand: select core.sync_run();
drop function if exists core.sync_run(int);      -- gained two settings (14 Nov): whole-section builds yes/no, a time limit
-- ONE run at a time (a lock all runs share): saves are applied strictly in their order, whoever runs the engine —
-- the 10-second timer, the instant run inside the mirror door (core.sync_now), or a proof.
create or replace function core.sync_run(p_max int default 2000, p_rebuild boolean default true, p_ms int default null) returns jsonb language plpgsql security definer set search_path = core, public as $$
declare ch record; done int := 0; bad int := 0; t0 timestamptz := clock_timestamp();
begin
  if not pg_try_advisory_xact_lock(7426001) then         -- another run is busy: it takes these saves in a moment
    return jsonb_build_object('done', 0, 'failed', 0, 'ms', 0, 'busy', true,
      'waiting', (select count(*) from core.sync_inbox where status = 'new' and core.sy_handles(path)));
  end if;
  perform set_config('core.loading', 'on', true);
  for ch in select i.id, i.kind, i.path, i.value, i.saved_at, i.at from core.sync_inbox i
             where i.status = 'new' and core.sy_handles(i.path) order by i.id limit greatest(1, p_max) for update skip locked loop
    exit when p_ms is not null and clock_timestamp() - t0 > make_interval(secs => p_ms / 1000.0);   -- out of time: the rest wait for the timer
    begin
      perform set_config('core.save_at', to_char(coalesce(ch.saved_at, ch.at) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), true);   -- the time of the save (Sellora's cache rows keep it)
      perform core.sy_apply(ch.path, case when ch.kind = 'delete' then null
                                          else core.fb_sv(ch.value, (extract(epoch from coalesce(ch.saved_at, ch.at)) * 1000)::bigint) end, ch.kind);
      update core.sync_inbox set status = 'done', section = (select sec from core.sy_list(ch.path)), error = null, done_at = now() where id = ch.id;
      done := done + 1;
    exception
      -- stopped by another run (deadlock / lock wait / serialization): nothing of this save stays; it and every later one
      -- wait for the next round, so saves are still applied in their order
      when deadlock_detected or lock_not_available or serialization_failure then exit;
      when others then
        update core.sync_inbox set status = 'failed', section = (select sec from core.sy_list(ch.path)), error = left(SQLERRM, 2000), done_at = now() where id = ch.id;
        bad := bad + 1;
    end;
  end loop;
  -- whole-section builds (Masters, printing blocks, Amazon listing report, HR) take seconds: the instant run leaves them
  -- to the 10-second timer (their working copy is already up to date)
  if not p_rebuild then
    return jsonb_build_object('done', done, 'failed', bad, 'ms', round(extract(epoch from clock_timestamp() - t0) * 1000), 'waiting', 0);
  end if;
  -- Masters changed in this round: the whole Masters section built again, once
  if exists (select 1 from core.settings where key = 'sync.masters_dirty' and value = 'true'::jsonb) then
    begin
      perform core.sy_masters_rebuild();
      delete from core.settings where key = 'sync.masters_error';
    exception when others then
      insert into core.settings (key, value, note) values ('sync.masters_error', to_jsonb(left(SQLERRM, 1000)), 'Why the last Masters build did not finish (it is tried again next round)')
      on conflict (key) do update set value = excluded.value;
    end;
  end if;
  -- the printing-blocks list / the Amazon listing report changed in this round: built again from the working copy, once
  if exists (select 1 from core.settings where key = 'sync.blocks_dirty' and value = 'true'::jsonb) then
    begin perform core.syp_blocks_rebuild(); delete from core.settings where key = 'sync.blocks_error';
    exception when others then insert into core.settings (key, value, note) values ('sync.blocks_error', to_jsonb(left(SQLERRM, 1000)), 'Why the last printing-blocks build did not finish') on conflict (key) do update set value = excluded.value; end;
  end if;
  if exists (select 1 from core.settings where key = 'sync.listings_dirty' and value = 'true'::jsonb) then
    begin perform core.syl_listings_rebuild(); delete from core.settings where key = 'sync.listings_error';
    exception when others then insert into core.settings (key, value, note) values ('sync.listings_error', to_jsonb(left(SQLERRM, 1000)), 'Why the last Amazon-listings build did not finish') on conflict (key) do update set value = excluded.value; end;
  end if;
  -- HR changed in this round: the whole HR section built again, once
  if exists (select 1 from core.settings where key = 'sync.hr_dirty' and value = 'true'::jsonb) then
    begin
      perform core.sy_hr_rebuild();
      delete from core.settings where key = 'sync.hr_error';
    exception when others then
      insert into core.settings (key, value, note) values ('sync.hr_error', to_jsonb(left(SQLERRM, 1000)), 'Why the last HR build did not finish (it is tried again next round)')
      on conflict (key) do update set value = excluded.value;
    end;
  end if;
  return jsonb_build_object('done', done, 'failed', bad, 'ms', round(extract(epoch from clock_timestamp() - t0) * 1000),
    'waiting', (select count(*) from core.sync_inbox where status = 'new' and core.sy_handles(path)));
end $$;

-- the PC processor leaves the Orders changes to the engine
create or replace function core.sync_take(p_n int default 500)
returns table (id bigint, kind text, path text, value jsonb, saved_at timestamptz, at timestamptz)
language sql security definer set search_path = core, public as $$
  select i.id, i.kind, i.path, i.value, i.saved_at, i.at from core.sync_inbox i
   where i.status = 'new' and not core.sy_handles(i.path) order by i.id limit greatest(1, least(p_n, 5000))
$$;

-- INSTANT (Ravi, 14 Nov: "make the things instant"): the mirror door applies what it was just given straight away, in the
-- same request — the tables are right ~0.1–0.3 s after the save instead of at the next 10-second round. At most 3 s of
-- work; anything left (or a run already busy) is taken by the 10-second timer, which also does the whole-section builds.
-- Never makes the door fail: whatever goes wrong here, the saves are in the inbox and the timer takes them.
create or replace function core.sync_now() returns jsonb language plpgsql security definer set search_path = core, public as $$
begin
  return core.sync_run(300, false, 3000);
exception when query_canceled then return jsonb_build_object('timeout', true);
          when others then return jsonb_build_object('error', left(SQLERRM, 300));
end $$;
-- the door the ERP sends every save through (as sql/sync_switch.sql made it) + the instant run at the end
create or replace function core.mirror(p_changes jsonb, p_screen text default null) returns int
language plpgsql security definer set search_path = core, public as $$
declare n int;
begin
  if core.me_id() is null and auth.role() is distinct from 'service_role' then raise exception 'mirror: not an ERP sign-in'; end if;
  if exists (select 1 from core.settings where key = 'sync.mirror_off' and value = 'true'::jsonb) then return 0; end if;   -- switched off by hand
  if jsonb_typeof(p_changes) <> 'array' then raise exception 'mirror: changes must be a list'; end if;
  if jsonb_array_length(p_changes) > 2000 then raise exception 'mirror: at most 2,000 changes at once'; end if;
  if octet_length(p_changes::text) > 8000000 then raise exception 'mirror: at most 8 MB at once'; end if;
  insert into core.sync_inbox (saved_at, email, kind, path, value, screen)
  select case when c->>'t' ~ '^\d{4}-\d{2}-\d{2}' then (c->>'t')::timestamptz end,
         coalesce(core.me_email(), 'server'),
         c->>'k', c->>'p', case when c->'v' = 'null'::jsonb then null else c->'v' end, left(p_screen, 80)
    from jsonb_array_elements(p_changes) c
   where c->>'k' in ('put', 'patch', 'delete') and coalesce(c->>'p', '') <> '';
  get diagnostics n = row_count;
  -- instant: not for the engine proof (it runs the engine itself) and not when switched off by setting sync.instant_off
  if n > 0 and coalesce(p_screen, '') <> 'engine proof'
     and not exists (select 1 from core.settings where key = 'sync.instant_off' and value = 'true'::jsonb) then
    perform core.sync_now();
  end if;
  return n;
end $$;
revoke all on function core.mirror(jsonb, text) from public;
grant execute on function core.mirror(jsonb, text) to anon, authenticated, service_role;
insert into core.settings (key, value, note) values ('sync.instant_off', 'false', 'true = the mirror door no longer applies saves at once (the 10-second timer still does)') on conflict (key) do nothing;

do $$ declare f text; begin
  for f in select p.oid::regprocedure::text from pg_proc p join pg_namespace n on n.oid = p.pronamespace
            where n.nspname = 'core' and (p.proname like 'sy\_%' or p.proname like 'syr\_%' or p.proname like 'syk\_%' or p.proname like 'sys\_%' or p.proname like 'sym\_%' or p.proname like 'syc\_%' or p.proname like 'syp\_%' or p.proname like 'syl\_%' or p.proname like 'syh\_%' or p.proname like 'syf\_%' or p.proname in ('sync_run', 'sync_take', 'sync_raw_load', 'sync_now')) loop   -- the fb_* helpers are plain pure functions (used by indexes): left as they are
    execute 'revoke all on function ' || f || ' from public, anon, authenticated';
    execute 'grant execute on function ' || f || ' to service_role';
  end loop;
end $$;

-- =====================================================================================================================
-- TEST ERP ON SUPABASE — the read door, compare-and-set (the lists without a table are in sy_list, section 'misc')
-- =====================================================================================================================
-- WHO MAY READ (14 Nov: 4 people with Firebase rights were not in core.people and were refused): an R-one person, OR any
-- Firebase sign-in of the ERP's project that has a Firebase access-rights document (perms) and is not a vendor — the same
-- rule the Firebase database itself uses (signed in, not a vendor).
create or replace function core.rt_reader() returns boolean language plpgsql stable security definer set search_path = core, public as $$
declare em text := core.me_email(); p jsonb;
begin
  if auth.role() = 'service_role' then return true; end if;
  if em is null then return false; end if;
  if core.me_id() is not null then return true; end if;
  if to_regclass('core.fs_docs') is null then return false; end if;
  execute 'select value from core.fs_docs where project = ''price-research-48ff3'' and coll = ''perms'' and doc_id = $1 and gone_at is null' into p using em;
  return p is not null and coalesce((p ->> 'vendor')::boolean, false) = false;
end $$;
revoke all on function core.rt_reader() from public;
grant execute on function core.rt_reader() to anon, authenticated, service_role;

-- READY-BUILT LISTS (14 Nov: every screen rebuilt whole lists — 2–3 s of work for the order book — and ERP data choked).
-- A whole list is built once and kept; a save that reaches the list (its inbox row turns "done") marks it to be built again
-- at the next read. rt_cache_clear() after a load from this PC.
create table if not exists core.rt_cache (
  reg       text primary key,
  value     jsonb,
  built_at  timestamptz not null default now(),
  dirty     boolean not null default false
);
alter table core.rt_cache enable row level security;
revoke all on core.rt_cache from anon, authenticated;
create or replace function core.rt_cache_mark() returns trigger language plpgsql security definer set search_path = core, public as $$
begin
  if new.status = 'done' and old.status is distinct from 'done' then
    update core.rt_cache set dirty = true where reg = split_part(new.path, '/', 1) and not dirty;
  end if;
  return new;
end $$;
drop trigger if exists rt_cache_mark on core.sync_inbox;
create trigger rt_cache_mark after update of status on core.sync_inbox for each row execute function core.rt_cache_mark();
create or replace function core.rt_cache_clear() returns int language sql security definer set search_path = core, public as $$
  with d as (delete from core.rt_cache returning 1) select count(*)::int from d
$$;
revoke all on function core.rt_cache_clear() from public, anon, authenticated;
grant execute on function core.rt_cache_clear() to service_role;
-- Firebase answers a list whose keys are 0, 1, 2 … as an array (its REST rule: all keys whole numbers, more than half of
-- the places from 0 to the biggest one filled); anything else stays an object
create or replace function core.rt_arr(v jsonb) returns jsonb language plpgsql immutable as $$
declare n int; mx int;
begin
  if v is null or jsonb_typeof(v) <> 'object' or v = '{}'::jsonb then return v; end if;
  if exists (select 1 from jsonb_object_keys(v) k where k !~ '^(0|[1-9][0-9]{0,8})$') then return v; end if;
  select count(*), max(k::int) into n, mx from jsonb_object_keys(v) k;
  if 2 * n <= mx + 1 then return v; end if;
  return (select jsonb_agg(v -> i::text order by i) from generate_series(0, mx) i);
end $$;
-- the records of one list from a table: legacy_key = <list>/<key>[/<key>] → { key: firebase } (gone rows left out)
create or replace function core.rt_rows(p_tbl text, p_prefix text, p_depth int) returns jsonb language plpgsql stable security definer set search_path = core, public as $$
declare v jsonb; n int := length(p_prefix) + 1;
begin
  if p_depth = 1 then
    execute format('select jsonb_object_agg(substr(legacy_key, %s), firebase) from %s t where left(legacy_key, %s) = %L and firebase is not null
                    and not exists (select 1 from core.sync_gone g where g.tbl = %L and g.legacy_key = t.legacy_key)', n + 1, p_tbl, n, p_prefix || '/', p_tbl) into v;
  else
    execute format('select jsonb_object_agg(g, core.rt_arr(x)) from (select split_part(substr(legacy_key, %s), ''/'', 1) g, jsonb_object_agg(split_part(substr(legacy_key, %s), ''/'', 2), firebase) x
                      from %s t where left(legacy_key, %s) = %L and firebase is not null
                       and not exists (select 1 from core.sync_gone g where g.tbl = %L and g.legacy_key = t.legacy_key) group by 1) z',
                   n + 1, n + 1, p_tbl, n, p_prefix || '/', p_tbl) into v;
  end if;
  return core.rt_arr(v);
end $$;
-- one record (or anything below it) straight from its row
create or replace function core.rt_row(p_tbl text, p_lk text) returns jsonb language plpgsql stable security definer set search_path = core, public as $$
declare v jsonb;
begin
  if exists (select 1 from core.sync_gone g where g.tbl = p_tbl and g.legacy_key = p_lk) then return null; end if;
  execute format('select firebase from %s where legacy_key = $1', p_tbl) into v using p_lk;
  return v;
end $$;

alter table core.rt_cache add column if not exists changed_at timestamptz;
-- the trigger also notes when the list changed: a build that started before a change is not kept as fresh
create or replace function core.rt_cache_mark() returns trigger language plpgsql security definer set search_path = core, public as $$
begin
  if new.status = 'done' and old.status is distinct from 'done' then
    update core.rt_cache set dirty = true, changed_at = now() where reg = split_part(new.path, '/', 1);
  end if;
  return new;
end $$;
-- a whole list: always from its ready-built copy when there is one (a save marks it, and the background builder
-- core.rt_cache_warm — every 15 s — builds it again: the copy is at most ~15 s behind). Only a list never built yet is built
-- here, ONE builder per list at a time (14 Nov: ten big lists built at once by one page ran ERP data out of time).
create or replace function core.rt_value(p_path text) returns jsonb language plpgsql volatile security definer set search_path = core, public as $$
declare segs text[] := string_to_array(trim(both '/' from coalesce(p_path, '')), '/'); c record; v jsonb; t0 timestamptz; u bigint;
begin
  if coalesce(array_length(segs, 1), 0) = 1 and segs[1] not in ('pt_audit', 'pt_trash') then
    select * into c from core.rt_cache where reg = segs[1];
    if found and c.txt is not null and c.built_at > now() - interval '24 hours' then return c.value; end if;
    perform pg_advisory_xact_lock(hashtext('rt_build:' || segs[1]));        -- the others wait for this one build
    select * into c from core.rt_cache where reg = segs[1];
    if found and c.txt is not null and c.built_at > now() - interval '24 hours' then return c.value; end if;
    t0 := clock_timestamp();
    u := core.rt_upto();
    v := core.rt_build(p_path);
    insert into core.rt_cache as rc (reg, value, txt, built_at, dirty, upto) values (segs[1], v, coalesce(v::text, 'null'), t0, false, u)
    on conflict (reg) do update set value = excluded.value, txt = excluded.txt, built_at = t0, upto = excluded.upto, dirty = coalesce(rc.changed_at >= t0, false);
    return v;
  end if;
  return core.rt_build(p_path);
end $$;
-- THE BACKGROUND BUILDER (pg_cron, every 15 s): the lists a save changed (and any older than 50 minutes) built again, one by
-- one, within p_ms. Never in a reader's way: a reader always gets the copy that is there.
create or replace function core.rt_cache_warm(p_ms int default 8000) returns jsonb language plpgsql security definer set search_path = core, public as $$
declare r record; v jsonb; t0 timestamptz; s timestamptz := clock_timestamp(); n int := 0; u bigint;
begin
  -- only what a save changed (+ a copy without its ready text, + a once-a-day safety rebuild) — 16 Nov: rebuilding every list every
  -- 50 minutes kept the small server busy for nothing
  for r in select reg from core.rt_cache where dirty or upto is null or txt is null or built_at < now() - interval '23 hours' order by dirty desc, changed_at nulls last loop
    exit when clock_timestamp() - s > make_interval(secs => p_ms / 1000.0);
    if not pg_try_advisory_xact_lock(hashtext('rt_build:' || r.reg)) then continue; end if;
    t0 := clock_timestamp();
    u := core.rt_upto();
    v := core.rt_build(r.reg);
    update core.rt_cache as rc set value = v, txt = coalesce(v::text, 'null'), built_at = t0, upto = u, dirty = coalesce(rc.changed_at >= t0, false) where rc.reg = r.reg;
    n := n + 1;
  end loop;
  return jsonb_build_object('built', n, 'ms', round(extract(epoch from clock_timestamp() - s) * 1000));
end $$;
-- ONLY WHAT CHANGED (14 Nov: a page asks for 9 big lists, ~22 MB, on every open). The browser keeps its own copy of a list
-- with the inbox number it is complete up to (upto) and asks only for the records saved after that — like Firebase, which
-- sends a list once and then only its changes.
-- upto = every save with a number up to here has been applied (or is not the engine's): the copy of a list built after
-- that point holds them all.
alter table core.rt_cache add column if not exists upto bigint;
-- 16 Nov: rt_upto read through the WHOLE inbox (~10,000 saves with their contents) on every list read; ten at once queued every
-- request for a minute. The saves still waiting are few: this index holds just them.
create index if not exists sync_inbox_waiting on core.sync_inbox (id) where status = 'new';
-- the number a list's ready-built copy is complete up to — asked beside the list itself (the list is then sent as it is,
-- never packed again into a bigger answer)
create or replace function core.rt_list_upto(p_reg text) returns bigint language plpgsql stable security definer set search_path = core, public as $$
declare u bigint := core.rt_upto(); c bigint;
begin
  if not core.rt_reader() then raise exception 'rt_list_upto: not an ERP sign-in'; end if;
  select upto into c from core.rt_cache where reg = p_reg;
  return case when c is null then u else least(u, c) end;
end $$;
revoke all on function core.rt_list_upto(text) from public;
grant execute on function core.rt_list_upto(text) to anon, authenticated, service_role;

-- READY TEXT (16 Nov: a page's nine lists took 8 s although only 1.7 MB travels — ERP data unpacked each stored list and turned
-- it into text again on every read; on the small server ten of those at once filled the processor and even an empty list waited
-- 4 s). Each list is now also kept as its finished JSON text, made once when the list is built; a read hands it over as it is.
-- Kept compressed with lz4 (16 Nov: kept uncompressed, the biggest lists meant ~25 MB of disk reading at once on the small server;
-- lz4 reads ~8× less and unpacks at memory speed).
alter table core.rt_cache add column if not exists txt text;
alter table core.rt_cache alter column txt set storage extended;
alter table core.rt_cache alter column txt set compression lz4;
create or replace function core.rt_get_json(p_path text) returns json language plpgsql volatile security definer set search_path = core, public as $$
declare v_reg text := split_part(trim(both '/' from coalesce(p_path, '')), '/', 1); t text;
begin
  if not core.rt_reader() then raise exception 'rt_get: not an ERP sign-in'; end if;
  if position('/' in trim(both '/' from coalesce(p_path, ''))) > 0 or v_reg in ('pt_audit', 'pt_trash') then return core.rt_value(p_path)::json; end if;
  select rc.txt into t from core.rt_cache rc where rc.reg = v_reg and rc.txt is not null and rc.built_at > now() - interval '24 hours';
  if t is null then perform core.rt_value(p_path); select rc.txt into t from core.rt_cache rc where rc.reg = v_reg; end if;
  return coalesce(t, 'null')::json;
end $$;
revoke all on function core.rt_get_json(text) from public;
grant execute on function core.rt_get_json(text) to anon, authenticated, service_role;
create or replace function core.rt_upto() returns bigint language sql stable security definer set search_path = core, public as $$
  select coalesce((select min(id) - 1 from core.sync_inbox where status = 'new' and core.sy_handles(path)), (select max(id) from core.sync_inbox), 0)
$$;
-- a whole list + the number its copy is complete up to
create or replace function core.rt_get_v(p_path text) returns jsonb language plpgsql volatile security definer set search_path = core, public as $$
declare v jsonb; u bigint; c record; v_reg text := split_part(trim(both '/' from coalesce(p_path, '')), '/', 1);
begin
  if not core.rt_reader() then raise exception 'rt_get: not an ERP sign-in'; end if;
  u := core.rt_upto();
  v := core.rt_value(p_path);
  select * into c from core.rt_cache rc where rc.reg = v_reg and position('/' in trim(both '/' from p_path)) = 0;
  if found and c.upto is not null then u := least(u, c.upto); end if;          -- a ready-built copy: complete up to when it was built
  return jsonb_build_object('v', v, 'upto', u);
end $$;
-- the records of a list saved after the browser's copy: { upto, ch: { record key: record (null = gone) } } or { full: true }
create or replace function core.rt_changes(p_reg text, p_upto bigint) returns jsonb language plpgsql volatile security definer set search_path = core, public as $$
declare l record; nu bigint := core.rt_upto(); d int; keys text[]; ch jsonb;
begin
  if not core.rt_reader() then raise exception 'rt_changes: not an ERP sign-in'; end if;
  if p_upto is null or nu < p_upto then return jsonb_build_object('full', true); end if;
  if nu = p_upto then return jsonb_build_object('upto', nu, 'ch', '{}'::jsonb); end if;
  select * into l from core.sy_list(p_reg);
  if l.reg is null or l.tbl = 'core.settings' then return jsonb_build_object('full', true); end if;
  d := case when l.tbl = 'core.sync_raw' then 2 else l.depth end;               -- how many path parts make one record
  -- a save of the whole list (or a whole group) — or very many saves — : the whole list again
  if exists (select 1 from core.sync_inbox where id > p_upto and id <= nu and status = 'done' and split_part(path, '/', 1) = p_reg
               and coalesce(array_length(string_to_array(trim(both '/' from path), '/'), 1), 0) < d) then return jsonb_build_object('full', true); end if;
  select array_agg(distinct array_to_string((string_to_array(trim(both '/' from path), '/'))[1:d], '/')) into keys
    from core.sync_inbox where id > p_upto and id <= nu and status = 'done' and split_part(path, '/', 1) = p_reg;
  if coalesce(array_length(keys, 1), 0) > 1500 then return jsonb_build_object('full', true); end if;
  select coalesce(jsonb_object_agg(substr(k, length(p_reg) + 2), core.rt_build(k)), '{}') into ch from unnest(coalesce(keys, '{}')) k;
  return jsonb_build_object('upto', nu, 'ch', ch);
end $$;
revoke all on function core.rt_upto() from public, anon, authenticated;
grant execute on function core.rt_upto() to service_role;
revoke all on function core.rt_get_v(text), core.rt_changes(text, bigint) from public;
grant execute on function core.rt_get_v(text), core.rt_changes(text, bigint) to anon, authenticated, service_role;
revoke all on function core.rt_cache_warm(int) from public, anon, authenticated;
grant execute on function core.rt_cache_warm(int) to service_role;
do $cron$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('r1-rt-warm', '15 seconds', 'select core.rt_cache_warm(4000)');
  end if;
end $cron$;
-- the answer itself, built from the tables (what rt_value keeps ready)
create or replace function core.rt_build(p_path text) returns jsonb language plpgsql stable security definer set search_path = core, public as $$
declare segs text[] := string_to_array(trim(both '/' from coalesce(p_path, '')), '/'); reg text; l record; v jsonb; nseg int;
begin
  nseg := coalesce(array_length(segs, 1), 0);
  if nseg = 0 then raise exception 'rt_get: a whole-database read is not offered'; end if;
  reg := segs[1];
  -- the history: pt_audit/<month>/<id> · pt_trash/<id>
  if reg = 'pt_audit' then
    if nseg >= 3 then select firebase into v from history.audit_entries where legacy_key = array_to_string(segs[1:3], '/'); return v #> segs[4:]; end if;
    if nseg = 2 then select jsonb_object_agg(split_part(legacy_key, '/', 3), firebase) into v from history.audit_entries where left(legacy_key, length(segs[2]) + 10) = 'pt_audit/' || segs[2] || '/'; return v; end if;
    raise exception 'rt_get: pt_audit is read one month at a time';
  elsif reg = 'pt_trash' then
    if nseg >= 2 then select firebase into v from history.recycle_bin where legacy_key = 'pt_trash/' || segs[2]; return v #> segs[3:]; end if;
    select jsonb_object_agg(split_part(legacy_key, '/', 2), firebase) into v from history.recycle_bin where left(legacy_key, 9) = 'pt_trash/'; return v;
  end if;
  -- completed job work's two helper lists (_ver = one version per day, _auto) are kept as settings, not rows (16 Nov: the door
  -- answered "nothing", so the test link loaded NO completed job work)
  if reg = 'pt_baseDone' and nseg >= 2 and left(segs[2], 1) = '_' then
    select value into v from core.settings where key = 'production.job_work' || segs[2];
    return v #> segs[3:];
  end if;
  select * into l from core.sy_list(reg);
  if l.reg is null then return null; end if;                       -- a list Supabase does not keep (bookkeeping): nothing
  if l.tbl = 'core.sync_raw' then                                   -- the working copy: whole records by key
    select value into v from core.sync_raw where sync_raw.reg = segs[1] and k = '' and value is not null;   -- a list that is one value
    if v is not null then return v #> segs[2:]; end if;
    if nseg >= 2 then select value into v from core.sync_raw where sync_raw.reg = segs[1] and k = segs[2]; return v #> segs[3:]; end if;
    select jsonb_object_agg(k, value) into v from core.sync_raw where sync_raw.reg = segs[1] and value is not null;
    return core.rt_arr(v);
  elsif l.tbl = 'core.settings' then                                -- the FNSKU map: kept whole as a setting
    select value into v from core.settings where legacy_key = reg; return v #> segs[2:];
  end if;
  if nseg >= l.depth then return core.rt_row(l.tbl, array_to_string(segs[1:l.depth], '/')) #> segs[l.depth + 1:]; end if;
  if l.depth = 3 and nseg = 2 then return core.rt_rows(l.tbl, array_to_string(segs[1:2], '/'), 1); end if;
  v := core.rt_rows(l.tbl, reg, l.depth - 1);
  if reg = 'pt_baseDone' then                                         -- the whole list: its two helper lists too
    v := coalesce(v, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
      '_ver', (select value from core.settings where key = 'production.job_work_ver'),
      '_auto', (select value from core.settings where key = 'production.job_work_auto')));
  end if;
  return v;
end $$;

-- THE READ DOOR. Filters: the 3 kinds the ERP uses (Firebase REST: orderBy + equalTo, orderBy $key + limitToLast).
create or replace function core.rt_get(p_path text, p_order_by text default null, p_equal_to jsonb default null, p_limit_last int default null) returns jsonb
language plpgsql volatile security definer set search_path = core, public as $$
declare v jsonb;
begin
  if not core.rt_reader() then raise exception 'rt_get: not an ERP sign-in'; end if;
  v := core.rt_value(p_path);
  if v is null or p_order_by is null or jsonb_typeof(v) not in ('object', 'array') then return v; end if;
  if jsonb_typeof(v) = 'array' then v := (select jsonb_object_agg((o - 1)::text, e) from jsonb_array_elements(v) with ordinality t(e, o) where jsonb_typeof(e) <> 'null'); end if;
  if p_order_by = '$key' then
    return coalesce((select jsonb_object_agg(key, value) from (select key, value from jsonb_each(v) order by key desc limit coalesce(p_limit_last, 2147483647)) z), '{}');
  end if;
  return coalesce((select jsonb_object_agg(key, value) from jsonb_each(v) where p_equal_to is null or value -> p_order_by = p_equal_to), '{}');
end $$;
-- the helpers read every table: never from a browser (only through rt_get / rt_cas, which check the sign-in)
revoke all on function core.rt_value(text), core.rt_build(text), core.rt_rows(text, text, int), core.rt_row(text, text) from public, anon, authenticated;
grant execute on function core.rt_value(text), core.rt_build(text), core.rt_rows(text, text, int), core.rt_row(text, text) to service_role;
revoke all on function core.rt_get(text, text, jsonb, int) from public;
grant execute on function core.rt_get(text, text, jsonb, int) to anon, authenticated, service_role;

-- COMPARE-AND-SET: next is written only if the path still holds expect (one at a time per path)
create or replace function core.rt_cas(p_path text, p_expect jsonb, p_next jsonb) returns text
language plpgsql security definer set search_path = core, public as $$
declare cur jsonb;
begin
  if core.me_id() is null and auth.role() is distinct from 'service_role' then raise exception 'rt_cas: not an ERP sign-in'; end if;
  perform pg_advisory_xact_lock(hashtext('rt_cas:' || p_path));
  perform core.sync_now();                                           -- everything already sent is applied first
  cur := core.rt_value(p_path);
  if coalesce(cur, 'null'::jsonb) is distinct from coalesce(p_expect, 'null'::jsonb) then return 'changed'; end if;
  perform core.mirror(jsonb_build_array(jsonb_build_object('k', 'put', 'p', trim(both '/' from p_path), 'v', p_next, 't', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))), 'compare-and-set');
  return '';
end $$;
revoke all on function core.rt_cas(text, jsonb, jsonb) from public;
grant execute on function core.rt_cas(text, jsonb, jsonb) to anon, authenticated, service_role;

-- THE FIRESTORE DOOR: one document (fs_get) or a whole collection (fs_list), as Firestore holds it. Where from:
--   1 the engine's working copy (whole documents of the collections it builds rows from)
--   2 the Amazon PO / packing-list tables (each row keeps its whole document)
--   3 the live copy of Firestore kept by the Apps Script reader (core.fs_docs) — every other collection
-- API keys are never in Supabase (the reader leaves them out of config/*): a screen that needs one still reads Firebase.
create or replace function core.fs_value(p_coll text, p_id text) returns jsonb language plpgsql stable security definer set search_path = core, public as $$
declare v jsonb; l record;
begin
  select value into v from core.sync_raw where reg = 'fs/' || p_coll and k = p_id and value is not null;
  if v is not null then return v; end if;
  select * into l from core.sy_list('fs/' || p_coll || '/' || p_id);
  if l.reg is not null and l.tbl not in ('core.sync_raw') and l.sec = 'orders' then
    v := core.rt_row(l.tbl, p_coll || '/' || p_id); if v is not null then return v; end if;     -- these rows' address is <collection>/<id> (make-orders.js)
  end if;
  if to_regclass('core.fs_docs') is not null then
    execute 'select value from core.fs_docs where project = ''price-research-48ff3'' and path = $1 and gone_at is null' into v using p_coll || '/' || p_id;
  end if;
  return v;
end $$;
create or replace function core.fs_get(p_coll text, p_id text) returns jsonb language plpgsql stable security definer set search_path = core, public as $$
begin
  if not core.rt_reader() then raise exception 'fs_get: not an ERP sign-in'; end if;
  return core.fs_value(p_coll, p_id);              -- null = the document does not exist
end $$;
-- a whole collection: [{ id, data }] (ids sorted, as Firestore lists them)
create or replace function core.fs_list(p_coll text) returns jsonb language plpgsql stable security definer set search_path = core, public as $$
declare ids text[]; l record;
begin
  if not core.rt_reader() then raise exception 'fs_list: not an ERP sign-in'; end if;
  select array_agg(distinct k) into ids from core.sync_raw where reg = 'fs/' || p_coll and value is not null;
  select * into l from core.sy_list('fs/' || p_coll || '/x');
  if l.reg is not null and l.sec = 'orders' then
    execute format('select array_agg(split_part(legacy_key, ''/'', 2)) from %s t where left(legacy_key, %s) = %L and firebase is not null
                    and not exists (select 1 from core.sync_gone g where g.tbl = %L and g.legacy_key = t.legacy_key)',
                   l.tbl, length(p_coll) + 1, p_coll || '/', l.tbl) into ids;
  elsif to_regclass('core.fs_docs') is not null then         -- documents of the working copy + those only in the live copy (e.g. audit)
    execute 'select array_agg(distinct i) from (select unnest($2) i union select doc_id from core.fs_docs where project = ''price-research-48ff3'' and coll = $1 and gone_at is null) z'
      into ids using p_coll, coalesce(ids, '{}'::text[]);
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', i, 'data', core.fs_value(p_coll, i)) order by i) from unnest(ids) i), '[]');
end $$;
revoke all on function core.fs_value(text, text) from public, anon, authenticated;
grant execute on function core.fs_value(text, text) to service_role;
revoke all on function core.fs_get(text, text), core.fs_list(text) from public;
grant execute on function core.fs_get(text, text), core.fs_list(text) to anon, authenticated, service_role;

-- 7 · checks
notify pgrst, 'reload schema';
select 1 as n, 'Firebase path rules: set, remove, lists' as check_name,
       case when core.fb_set('{"a": {"b": 1}}', '{a,c}', '2') = '{"a": {"b": 1, "c": 2}}'::jsonb
             and core.fb_set('{"a": {"b": 1}}', '{a,b}', null) is null
             and core.fb_set('[{"x": 1}, {"y": 2}]', '{1}', null) = '[{"x": 1}]'::jsonb
             and core.fb_set(null, '{k}', '{"q": {}, "r": null}') is null then 'PASS' else 'FAIL' end as result
union all select 2, 'converters = the loaders'' (dates, yes/no, numbers, India time)',
       case when core.fb_conv('"2026-19-10"', 'd') is null and core.fb_conv('"5/11/2026"', 'd') = '"2026-11-05"'::jsonb
             and core.fb_conv('"10-Nov-26"', 'd') = '"2026-11-10"'::jsonb and core.fb_conv('"Yes"', 'b') = 'true'::jsonb
             and core.fb_conv('" 12.50 "', 'n') = '12.50'::jsonb and core.fb_conv('"2026-11-10 12:30"', 'ts') = '"2026-11-10T07:00:00.000Z"'::jsonb then 'PASS' else 'FAIL' end
union all select 3, 'server time placeholder → the time of the save', case when core.fb_sv('{"at": {".sv": "timestamp"}}', 1700000000000) = '{"at": 1700000000000}'::jsonb then 'PASS' else 'FAIL' end
union all select 4, 'the engine takes the Orders and Stock lists, the PC processor the rest',
       case when core.sy_handles('pt_orderBook/x/qty') and core.sy_handles('fs/po/P1') and not core.sy_handles('fs/po')
             and core.sy_handles('pt_fgiLedger/x') and core.sy_handles('pt_rfdStock/g/k') and core.sy_handles('pt_masterDB/x') and core.sy_handles('pt_fnskuMap/list')
             and core.sy_handles('pt_masters/size/x') and core.sy_handles('pt_jwCorrReqs/r1/status') and not core.sy_handles('pt_sync/x') then 'PASS' else 'FAIL' end
union all select 9, 'Control: a request becomes its approval row as the loader makes it',
       case when (select a ->> 'status' = 'approved' and a ->> 'kind' = 'order_delete' and (a ->> 'legacy_self_approved')::boolean
                    from (select core.syc_approval('pt_obDeleteReqs', 'k1', '{"status": "deleted", "by": "A@x.com", "answeredBy": "a@x.com", "at": "2026-11-01T10:00:00Z", "answeredAt": "2026-11-02T10:00:00Z"}') a) z)
            then 'PASS' else 'FAIL' end
union all select 10, 'Masters: sizes carry their shape; JavaScript value rules',
       case when core.sym_size('Round 60') = '{"shape": "round", "width_in": 60, "length_in": 60}'::jsonb and core.sym_size('60x90') ->> 'shape' = 'rectangle'
             and core.js_num('"60 in"') = 60 and core.js_json('[1, "a", {"b": 2}]') = '[1,"a",{"b":2}]' and not core.js_truthy('0') and core.js_truthy('"x"') then 'PASS' else 'FAIL' end
union all select 8, 'SKU times: a number is milliseconds, a bare day is UTC',
       case when core.fb_conv_sku('1700000000000', 'ts') = '"2023-11-14T22:13:20.000Z"'::jsonb and core.fb_conv_sku('"2026-11-10"', 'ts') = '"2026-11-10T00:00:00.000Z"'::jsonb
             and core.fb_conv_sku('"Yes"', 'b') = 'true'::jsonb then 'PASS' else 'FAIL' end
union all select 6, 'Stock dates: "24/09/2026, 17:54" is India time; a day may have a time after it',
       case when core.fb_conv_stock('"24/09/2026, 17:54"', 'ts') = '"2026-09-24T12:24:00.000Z"'::jsonb
             and core.fb_conv_stock('"24/09/2026, 17:54"', 'd') = '"2026-09-24"'::jsonb and core.fb_conv_stock('"31/09/2026"', 'd') is null then 'PASS' else 'FAIL' end
union all select 5, 'browsers cannot run the engine',
       case when not has_function_privilege('anon', 'core.sync_run(int,boolean,int)', 'execute') and not has_function_privilege('authenticated', 'core.sy_apply(text,jsonb,text)', 'execute')
             and not has_function_privilege('authenticated', 'core.sync_now()', 'execute') then 'PASS' else 'FAIL' end
union all select 16, 'test ERP on Supabase: lists answered in Firebase''s shape; browsers only through the signed-in door',
       case when core.rt_arr('{"0": "a", "1": "b"}') = '["a", "b"]'::jsonb and core.rt_arr('{"0": "a", "5": "b"}') = '{"0": "a", "5": "b"}'::jsonb
             and core.rt_arr('{"x": 1}') = '{"x": 1}'::jsonb
             and not has_function_privilege('anon', 'core.rt_value(text)', 'execute') and not has_function_privilege('authenticated', 'core.rt_rows(text,text,int)', 'execute')
             and position('rt_reader' in pg_get_functiondef('core.rt_get(text,text,jsonb,int)'::regprocedure)) > 0
             and not has_table_privilege('anon', 'core.rt_cache', 'select') and not has_function_privilege('anon', 'core.rt_build(text)', 'execute')
             and exists (select 1 from pg_trigger where tgname = 'rt_cache_mark')
             and (not exists (select 1 from pg_extension where extname = 'pg_cron') or exists (select 1 from cron.job where jobname = 'r1-rt-warm' and active))
             and core.sy_handles('pt_flowRev/c1') = exists (select 1 from core.settings where key = 'sync.misc_ready' and value = 'true'::jsonb)
             and not has_function_privilege('anon', 'core.fs_value(text,text)', 'execute')
             and position('rt_reader' in pg_get_functiondef('core.fs_get(text,text)'::regprocedure)) > 0 and position('rt_reader' in pg_get_functiondef('core.fs_list(text)'::regprocedure)) > 0
             and not core.rt_reader() is null then 'PASS' else 'FAIL' end
union all select 15, 'instant: the mirror door applies saves at once (one run at a time), and still needs a real ERP sign-in',
       case when position('sync_now' in pg_get_functiondef('core.mirror(jsonb,text)'::regprocedure)) > 0
             and position('me_id' in pg_get_functiondef('core.mirror(jsonb,text)'::regprocedure)) > 0
             and position('pg_try_advisory_xact_lock' in pg_get_functiondef('core.sync_run(int,boolean,int)'::regprocedure)) > 0
             and exists (select 1 from core.settings where key = 'sync.instant_off') then 'PASS' else 'FAIL' end
union all select 11, 'HR: value rules as make-hr.js; HR saves wait until the working copy has HR',
       case when core.sy_hr_k('"  Pradeep   Contractor "') = 'pradeep contractor' and core.sy_hr_day('"2026-19-10"') is null and core.sy_hr_day('"2026-09-14"') = '"2026-09-14"'::jsonb
             and core.sy_hr_n('"NA"') is null and core.sy_hr_n('" 45 "') = '45'::jsonb and core.sy_hr_b('"Yes"') = 'true'::jsonb
             and core.sy_hr_ts('""') is null and core.sy_hr_ts('"2026-09-12T14:57:38.678Z"') = '"2026-09-12T14:57:38.678Z"'::jsonb
             and core.sy_handles('pt_attend/x') = exists (select 1 from core.settings where key = 'sync.hr_ready' and value = 'true'::jsonb) then 'PASS' else 'FAIL' end
union all select 12, 'Production: a record flattens as the loader does; Production saves wait until the working copy is filled',
       case when core.syp_get('{"fabric": {"name": "Sheeting 62"}}', '{fabric,name}') = '"Sheeting 62"'::jsonb and core.syp_get('{"fabric": {"name": "x"}}', '{fabric}') is null
             and core.syp_get('{"fabric": {}}', '{fabric}') = '{}'::jsonb and core.syp_get('{"s": {"a": 1}}', '{s}', true) = '{"a": 1}'::jsonb
             and core.fb_conv_stock('"19/09/2026, 14:19"', 'ts') = '"2026-09-19T08:49:00.000Z"'::jsonb
             and core.sy_handles('pt_qcChecks/x') = exists (select 1 from core.settings where key = 'sync.production_ready' and value = 'true'::jsonb) then 'PASS' else 'FAIL' end
union all select 7, 'Firestore documents kept exactly as written (empty lists and empty fields stay)',
